(window.__RC=window.__RC||{})["guide"]={"sections":[{"id":"culture","title":"ثقافة راية","group":"الأساسيات","icon":"landmark","html":"\n<div class=\"section-body\">\n<div class=\"guest-steps\">\n<div class=\"guest-step active-step\" data-c=\"0\" onclick=\"showSectionTab('culture', 'vision', this)\" style=\"cursor:pointer;\">الرؤية</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('culture', 'mission', this)\" style=\"cursor:pointer;\">الرسالة</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('culture', 'values', this)\" style=\"cursor:pointer;\">القيم الأساسية</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('culture', 'culture', this)\" style=\"cursor:pointer;\">ثقافتنا</div>\n</div>\n<div class=\"section-tab-content\" id=\"culture-tab-vision\" style=\"display: block;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"1\">رؤيتنا</div>\n<div class=\"content-text\">أن نكون الشريك التجاري الأكثر تأثيراً وثقة، من خلال وضع معايير جديدة\n                          في تجربة العملاء، وتقديم حلول قائمة على القيمة، والتميز في خدمات ما بعد البيع، والتمكين المالي\n                          — بما يرسخ شراكات طويلة الأمد تُسهم في تشكيل المستقبل.</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"culture-tab-mission\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"2\">مهمتنا</div>\n<div class=\"content-text\">قيادة تحوّل السوق عبر شراكات استراتيجية، وابتكار مستدام، وحلول تركّز\n                          على العميل، بهدف توسيع نطاق الوصول ووضع معايير جديدة للقطاع.</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"culture-tab-values\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"3\">القيم الأساسية</div>\n<div class=\"values-grid\">\n<div class=\"value-card\">\n<div class=\"v-icon\">🎯</div>\n<div class=\"v-name\" data-c=\"4\">التركيز على العملاء</div>\n<div class=\"v-desc\">المبادئ الثابتة التي توجه القرارات</div>\n</div>\n<div class=\"value-card\">\n<div class=\"v-icon\">⭐</div>\n<div class=\"v-name\" data-c=\"5\">التميز</div>\n<div class=\"v-desc\">أفضل الممارسات والمعايير الدولية</div>\n</div>\n<div class=\"value-card\">\n<div class=\"v-icon\">🤝</div>\n<div class=\"v-name\" data-c=\"6\">احترام الآخرين</div>\n<div class=\"v-desc\">التوازن بين التكيف والمبادئ</div>\n</div>\n<div class=\"value-card\">\n<div class=\"v-icon\">👥</div>\n<div class=\"v-name\" data-c=\"7\">العمل الجماعي</div>\n<div class=\"v-desc\">قيادة تحوّل السوق عبر شراكات</div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"culture-tab-culture\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"8\">ثقافتنا وقيمنا</div>\n<div class=\"content-text\">تلتزم الشركة بتطبيق أفضل الممارسات العالمية في التشغيل، وأمن\n                          المعلومات، وإدارة الخدمات، بما يضمن جودة الخدمة واستمرارية الأعمال وفقًا للمعايير الدولية\n                          المعتمدة. رغم قدرتنا العالية على التكيف والاستجابة للتغيير، تظل قيمنا الأساسية ثابتة لا\n                          تتزعزع.</div>\n</div>\n</div>\n</div>\n","words":134},{"id":"experience","title":"تجربة العميل","group":"الأساسيات","icon":"heart","html":"\n<div class=\"section-body\">\n<div class=\"guest-steps\">\n<div class=\"guest-step active-step\" data-c=\"9\" onclick=\"showSectionTab('experience', 'service', this)\" style=\"cursor:pointer;\">خدمة العميل</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('experience', 'experience', this)\" style=\"cursor:pointer;\">تجربة العميل</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('experience', 'factors', this)\" style=\"cursor:pointer;\">عوامل التجربة</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('experience', 'vision', this)\" style=\"cursor:pointer;\">منظور صاحب البيت</div>\n</div>\n<div class=\"section-tab-content\" id=\"experience-tab-service\" style=\"display: block;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"10\">خدمة العميل</div>\n<div class=\"content-text\">تقدم للعميل اللي بيدور عليه وتجاوب على أسئلته. ده رد فعل مباشر على طلب\n                          واضح.</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"experience-tab-experience\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"11\">تجربة العميل</div>\n<div class=\"content-text\">الرحلة اللي العميل بيعيشها من أول ما بيوصل الفرع لحد خدمة ما بعد\n                          البيع. سلسلة بتتجمع وبتكون الإنطباع النهائي عن الشركة. مش مجرد بيع وبس... دي تجربة كاملة.\n                        </div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"experience-tab-factors\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"12\">عوامل التجربة</div>\n<div class=\"do-dont-grid\">\n<div class=\"do-box\">\n<span class=\"box-label\">🏢 الفرع</span>\n<ul style=\"list-style:none;padding:0\">\n<li>• نظافة الفرع والمنتجات</li>\n<li>• خريطة عرض المنتجات</li>\n<li>• الموسيقى</li>\n</ul>\n</div>\n<div style=\"background:rgba(26,47,110,0.07); border:1px solid rgba(26,47,110,0.2); padding:12px 14px; border-radius:8px; font-size:12.5px; color:#1a2f6e;\">\n<span class=\"box-label\" style=\"color:#1a2f6e; font-weight:800; font-size:12px; margin-bottom:6px; display:block;\">👥\n                              الفريق</span>\n<ul style=\"list-style:none;padding:0; color:#4a5a8a;\">\n<li>• الاستقبال والتوديع</li>\n<li>• تعامل الفريق مع بعضه</li>\n<li>• طريقة التواصل مع العملاء</li>\n<li>• المظهر والنظافة الشخصية</li>\n<li>• تسهيل الإجراءات</li>\n</ul>\n</div>\n</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"experience-tab-vision\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"13\">نظرة صاحب البيت لتقديم تجربة ناجحة</div>\n<div class=\"content-text\">هنحقق تجربة ناجحة للعميل لما نتعامل بمنظور مختلف.. تكون شايف العميل\n                          كأنه <strong>ضيفك</strong> والضيف دا جايلك <strong>بيتك</strong> اللي هو الفرع. فتقدمله أحسن\n                          تجربة يفضل دايما فاكرك بيها عشان يكون عميل دائم. انت هدفك تكسب العميل مش تكسب بس مجرد عملية\n                          البيع.</div>\n<div class=\"info-row\" style=\"margin-top:10px;\">\n<span class=\"info-badge badge-blue\">🚫 ليس: زبون</span>\n<span class=\"info-badge badge-green\">✅ العميل = ضيف</span>\n<span class=\"info-badge badge-blue\">🚫 ليس: محل</span>\n<span class=\"info-badge badge-green\">✅ الفرع = بيتك</span>\n<span class=\"info-badge badge-blue\">🚫 ليس: بياع</span>\n<span class=\"info-badge badge-green\">✅ استشاري بيع</span>\n</div>\n</div>\n</div>\n</div>\n","words":159},{"id":"skills","title":"المهارات الأساسية","group":"الأساسيات","icon":"sparkles","html":"\n<div class=\"section-body\">\n<div class=\"guest-steps\">\n<div class=\"guest-step active-step\" data-c=\"14\" onclick=\"showSectionTab('skills', 'comm', this)\" style=\"cursor:pointer;\">الاتصال الفعال</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('skills', 'listen', this)\" style=\"cursor:pointer;\">الاستماع الفعال</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('skills', 'barriers', this)\" style=\"cursor:pointer;\">الحواجز والمظهر</div>\n</div>\n<div class=\"section-tab-content\" id=\"skills-tab-comm\" style=\"display: block;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"15\">1- مهارة التواصل الفعال</div>\n<div class=\"content-text\">اللي هو القدرة على توصيل أفكارك بطريقة يفهمها العميل بشكل صحيح، من\n                          خلال الكلام (لفظي) ومن خلال لغة الجسد ونبرة الصوت (غير لفظي). 93% غير لفظي (لغة الجسد ونبرة\n                          الصوت) و7% لفظي (الكلمات).</div>\n</div>\n<div id=\"comm-sub-container\" style=\"margin-top: 15px;\">\n<div class=\"guest-steps\" style=\"border-radius: 8px; overflow: hidden; margin-bottom: 15px;\">\n<div class=\"sub-step active-sub-step\" onclick=\"showSubTab('comm-sub-container', 'nonverbal', this)\">التواصل غير اللفظي (93%)</div>\n<div class=\"sub-step\" onclick=\"showSubTab('comm-sub-container', 'verbal', this)\">التواصل\n                            اللفظي (7%)</div>\n</div>\n<div class=\"sub-tab-content\" id=\"comm-sub-container-tab-nonverbal\" style=\"display: block;\">\n<div class=\"rule-list\">\n<li data-c=\"16\"><span class=\"bullet\"></span><strong>التواصل البصري:</strong> استخدام طريقة المثلث\n                              (العينين مع الجبهة) + (العينين مع الأنف) - من 3 لـ 5 ثواني. تجنب النظر للشفاه.</li>\n<li><span class=\"bullet\"></span><strong>الابتسامة:</strong> بنستخدمها في الترحيب، بدون إظهار\n                              الأسنان أو المبالغة. لا تُستخدم أثناء غضب العميل.</li>\n<li><span class=\"bullet\"></span><strong>تعبيرات الوجه:</strong> تعبير وجه بشوش ومفرود بدون\n                              تكشير. تعبير عن التضامن عند المشكلات.</li>\n<li><span class=\"bullet\"></span><strong>وضعية الجسد:</strong> اتجاه الجسد بكلا الكتفين نحو\n                              العميل. استقامة الوقوف وعدم تربيع اليدين.</li>\n<li><span class=\"bullet\"></span><strong>نبرة الصوت:</strong> مستوى صوت متوسط لا عالي ولا\n                              منخفض. نبرة مناسبة مع الموقف. تيمبو متوسط.</li>\n<li><span class=\"bullet\"></span><strong>المسافة مع العميل:</strong> 1م (مقدار ذراع) رجل-رجل\n                              / امرأة-امرأة. 1.5م (مقدار ذراع ونصف) رجل-امرأة.</li>\n</div>\n</div>\n<div class=\"sub-tab-content\" id=\"comm-sub-container-tab-verbal\" style=\"display: none;\">\n<div class=\"do-dont-grid\">\n<div class=\"do-box\" data-c=\"17\">\n<span class=\"box-label\">✅ استخدم</span>\n                              حضرتك / فندم / أستاذ / أستاذة / مدام / آنسة\n                            </div>\n<div class=\"dont-box\">\n<span class=\"box-label\">🚫 لا تستخدم</span>\n                              أخويا / باشا / بيه / عسوله / حاج / كبير / غالي / معلم\n                            </div>\n</div>\n<div style=\"margin-top:10px;\">\n<div class=\"do-box\" style=\"margin-bottom:8px;\">\n<span class=\"box-label\">✅ بدلاً من الردود المختصرة قل:</span>\n                              \"ممكن أستفسر لحضرتك وأرد عليك حالاً\" - \"أقترحلك بديل مناسب\" - \"نشوف مع بعض أنسب حل لحضرتك\"\n                            </div>\n<div class=\"dont-box\">\n<span class=\"box-label\">🚫 تجنب:</span>\n                              ماعرفش / مش موجود / مش عارف / طيب خلاص / مش هينفع / هو ده الموجود / استنى شوية\n                            </div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"skills-tab-listen\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"18\">2- مهارة الاستماع الفعال</div>\n<div class=\"personality-grid\">\n<div class=\"personality-card\" style=\"border-color:rgba(239,68,68,0.3);\">\n<div class=\"p-title\" data-c=\"19\" style=\"color:#b91c1c;\">❌ استماع تظاهري</div>\n<div class=\"p-desc\">التظاهر بالاستماع من غير تركيز حقيقي. ردود عامة غير مرتبطة بما قيل.\n                            </div>\n</div>\n<div class=\"personality-card\" style=\"border-color:rgba(239,68,68,0.3);\">\n<div class=\"p-title\" data-c=\"20\" style=\"color:#b91c1c;\">❌ استماع انتقائي</div>\n<div class=\"p-desc\">التركيز على أجزاء معينة وتجاهل باقي الرسالة. يوصل انطباع سلبي.</div>\n</div>\n<div class=\"personality-card\" style=\"border-color:rgba(34,197,94,0.3);\">\n<div class=\"p-title\" data-c=\"21\" style=\"color:#15803d;\">✅ استماع فعال</div>\n<div class=\"p-desc\">الاستماع بتركيز كامل. اسأل أسئلة توضيحية. أعد صياغة الكلام. لا تقاطع.\n                            </div>\n</div>\n<div class=\"personality-card\" style=\"border-color:rgba(34,197,94,0.3);\">\n<div class=\"p-title\" data-c=\"22\" style=\"color:#15803d;\">✅ استماع تضامني</div>\n<div class=\"p-desc\">يُستخدم عند غضب العميل. إظهار التعاطف مع مشاعره. لا ابتسامة نهائياً.\n                            </div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"skills-tab-barriers\" style=\"display: none;\">\n<div id=\"barriers-sub-container\" style=\"margin-top: 15px;\">\n<div class=\"guest-steps\" style=\"border-radius: 8px; overflow: hidden; margin-bottom: 15px;\">\n<div class=\"sub-step active-sub-step\" data-c=\"23\" onclick=\"showSubTab('barriers-sub-container', 'pressure', this)\">الضغوط والحواجز</div>\n<div class=\"sub-step\" onclick=\"showSubTab('barriers-sub-container', 'appearance', this)\">\n                            المظهر والنظافة</div>\n</div>\n<div class=\"sub-tab-content\" id=\"barriers-sub-container-tab-pressure\" style=\"display: block;\">\n<div class=\"subsection-title\" data-c=\"24\">حواجز تؤثر على المهارات – الضغط</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>حط نفسك مكان العميل:</strong> إن العميل مش عارف\n                              ضغوطك، متوقع يعيش تجربة حلوة.</li>\n<li><span class=\"bullet\"></span><strong>افصل نفسك عند انفعالات العملاء:</strong> الموضوع\n                              مرتبط بسبب الانفعال، العميل بيكون منفعل بسبب إحباط من الخدمة مش منك.</li>\n<li><span class=\"bullet\"></span><strong>افصل مشاكلك الشخصية عن الشغل:</strong> عشان تكون\n                              قادر تتعامل مع أي مشكلة.</li>\n<li><span class=\"bullet\"></span><strong>راقب لغة جسدك:</strong> دا محتاج منك تمرين ورقابة\n                              على نفسك بشكل مستمر.</li>\n<li><span class=\"bullet\"></span><strong>اطلب دعم:</strong> لو مش قادر تتحكم في الموقف،\n                              استعين بزميل أو مديرك.</li>\n</div>\n</div>\n<div class=\"sub-tab-content\" id=\"barriers-sub-container-tab-appearance\" style=\"display: none;\">\n<div class=\"subsection-title\" data-c=\"25\">المظهر والنظافة الشخصية</div>\n<div class=\"do-dont-grid\">\n<div class=\"do-box\">\n<span class=\"box-label\">✅ مسموح به</span>\n                              قميص بولو \"راية\" نظيف ومكوي<br/>\n                              بنطلون جينز غير ممزق<br/>\n                              أحذية كاجوال أنيقة\n                            </div>\n<div class=\"dont-box\">\n<span class=\"box-label\">🚫 ممنوع</span>\n                              شورت<br/>\n                              قميص مجعد أو غير نظيف<br/>\n                              شباشب، أحذية رياضية\n                            </div>\n</div>\n<div class=\"content-text\" style=\"margin-top:10px;\">النظافة الشخصية: الأظافر – اللحية – الشعر –\n                            رائحة الفم – رائحة الجسد</div>\n</div>\n</div>\n</div>\n</div>\n","words":395},{"id":"guest","title":"منهج GUEST","group":"البيع","icon":"route","html":"\n<div class=\"section-body\">\n<div class=\"guest-steps\">\n<div class=\"guest-step active-step\" data-c=\"26\" onclick=\"showGuestTab('G', this)\" style=\"cursor:pointer;\">\n<span class=\"step-letter\">G</span>Greeting الترحيب</div>\n<div class=\"guest-step\" onclick=\"showGuestTab('U', this)\" style=\"cursor:pointer;\"><span class=\"step-letter\">U</span>Understand الفهم</div>\n<div class=\"guest-step\" onclick=\"showGuestTab('E', this)\" style=\"cursor:pointer;\"><span class=\"step-letter\">E</span>Expose العرض</div>\n<div class=\"guest-step\" onclick=\"showGuestTab('S', this)\" style=\"cursor:pointer;\"><span class=\"step-letter\">S</span>Selling البيع</div>\n<div class=\"guest-step\" onclick=\"showGuestTab('T', this)\" style=\"cursor:pointer;\"><span class=\"step-letter\">T</span>Thank الشكر</div>\n</div>\n<div class=\"guest-tab-content\" id=\"guest-tab-G\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"27\">G – الترحيب (Greeting)</div>\n<div class=\"content-text\">هو أول سلوك بيلاحظه العميل منك لما بيدخل الفرع. عشان العميل يحس بأنه\n                          مرحب بيه وبيتعامل كضيف جايلك بيتك (الفرع).</div>\n<div class=\"do-dont-grid\" style=\"margin-top:10px;\">\n<div class=\"do-box\">\n<span class=\"box-label\">✅ غير لفظي</span>\n                            • ابتسامة صادقة مُرحبة<br/>\n                            • تواصل بصري<br/>\n                            • وضعية جسم مفتوحة (كلا الكتفين ناحية العميل)\n                          </div>\n<div class=\"do-box\">\n<span class=\"box-label\">✅ لفظي</span>\n                            1. صباح الخير / مساء الخير<br/>\n                            2. مع حضرتك (اسمك)*<br/>\n                            3. أقدر أساعدك ازاي؟**\n                          </div>\n</div>\n<div class=\"info-row\" style=\"margin-top:10px;\">\n<span class=\"info-badge badge-red\">⚠️ ماتبدأش بالهزار مع العميل أو تخطي لأي حدود بحجة كسر\n                            الحاجز</span>\n</div>\n<div class=\"content-text\" style=\"margin-top:8px; font-size:12px;\">* انك تَعَرف العميل باسمك\n                          ويكلمك بيه دا بيخلق رابطة إنسانية بينك وبينه.<br/>** الألفاظ اللي بتحسس العميل بحسن المعاملة:\n                          \"تحت أمرك\" - \"زي ماحضرتك تحب\" - \"اختيار موفق\"</div>\n</div>\n</div>\n<div class=\"guest-tab-content\" id=\"guest-tab-U\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"28\">U – فهم العميل (Understand)</div>\n<div class=\"content-text\">الاستشاري الشاطر هو اللي يعرف يسأل صح فيوصل لاحتياج العميل بسرعة.\n                        </div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>Value (القيمة):</strong> القيمة الوظيفية / الاقتصادية\n                            / الاجتماعية / العاطفية / التجريبية</li>\n<li><span class=\"bullet\"></span><strong>Pain (الألم):</strong> الحاجات اللي بتزعج العميل –\n                            تجربة سيئة سابقة – مشكلة سمع عنها</li>\n<li><span class=\"bullet\"></span><strong>الملاحظة:</strong> لاحظ طريقة دخوله ونظراته وتوقفه\n                            قدام منتج معين</li>\n<li><span class=\"bullet\"></span><strong>التساؤل:</strong> استخدم الأسئلة المفتوحة أولاً ثم\n                            المغلقة</li>\n<li><span class=\"bullet\"></span><strong>الاستماع الفعال:</strong> بعد السؤال بتيجي أهمية\n                            الاستماع</li>\n</div>\n<div class=\"info-row\" style=\"margin-top:10px;\">\n<span class=\"info-badge badge-red\">⚠️ لا تحكم مطلقاً على مظهر العميل في قدرته الشرائية أو\n                            طريقة الدفع</span>\n</div>\n</div>\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"29\">شخصيات العملاء (DISC)</div>\n<div class=\"personality-grid\">\n<div class=\"personality-card\">\n<div class=\"p-title\" data-c=\"30\">D – Dominant (المستعجل/العصبي)</div>\n<div class=\"p-desc\">محدد وحاسم، غير صبور، يحب أن يكون صاحب القرار.<br/><strong>افعل:</strong>\n                              لخص المنتجات بشكل محدد وكن سريعاً.<br/><strong>تجنب:</strong> لا تفرض رؤيتك، لا تعطيه بدائل\n                              كثيرة.</div>\n</div>\n<div class=\"personality-card\">\n<div class=\"p-title\" data-c=\"31\">I – Influencer (الاجتماعي/الودود)</div>\n<div class=\"p-desc\">يستخدم لغة جسده كثيراً، يحب يتكلم، مركز\n                              الاهتمام.<br/><strong>افعل:</strong> تفاعل معه وشارك الأمثلة.<br/><strong>تجنب:</strong> لا\n                              تقاطعه، لا تهمل تعليقاته.</div>\n</div>\n<div class=\"personality-card\">\n<div class=\"p-title\" data-c=\"32\">S – Steady (المتردد/الصامت)</div>\n<div class=\"p-desc\">مش بيبادر بالكلام، صبور وهادئ، لا يميل\n                              للتغيير.<br/><strong>افعل:</strong> تضامن معه، أخبره رأيك كخبير، أعطه بدائل\n                              قليلة.<br/><strong>تجنب:</strong> لا تضغط عليه، لا تعطيه بدائل كثيرة.</div>\n</div>\n<div class=\"personality-card\">\n<div class=\"p-title\" data-c=\"33\">C – Cautious (الشكاك/الناصح)</div>\n<div class=\"p-desc\">دقيق ويهتم بالتفاصيل، منطقي وكثير التساؤلات.<br/><strong>افعل:</strong>\n                              كن دقيقاً في معلوماتك، اذكرها بطريقة منطقية.<br/><strong>تجنب:</strong> لا تتجاهل التفاصيل،\n                              لا ترد بإجابات عامة.</div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"guest-tab-content\" id=\"guest-tab-E\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"34\">E – عرض المنتج (Expose)</div>\n<div class=\"content-text\">دور الاستشاري مش بس إنه يبيع مواصفات الجهاز أو يعرض SPECs، دوره إنه\n                          يوضح للعميل ازاي المواصفات دي هتفيده هو بالتحديد.</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>المعلومة والفائدة:</strong> اعرض \"المعلومة\" ثم\n                            \"الفائدة\" = \"ايه هو\" + \"هيفيدك ازاي\" + \"وهيوفر عليك ايه\"</li>\n<li><span class=\"bullet\"></span><strong>المشكلة والحل:</strong> ابدأ بمشكلة واقعية العملاء\n                            ممكن يقابلوها، ثم وضح الحل اللي بيقدمه المنتج</li>\n<li><span class=\"bullet\"></span><strong>المقارنة:</strong> بتوضيح النقاط البيعية في البراندات\n                            المختلفة ومساعدة العميل في تحديد أنسب نوع</li>\n</div>\n<div class=\"dont-box\" style=\"margin-top:10px;\">\n<span class=\"box-label\">🚫 أشهر أخطاء المقارنة:</span>\n                          مايسألش عن استخدام العميل / يقارن السعر قبل الأداء / يقول كلام عام من غير أرقام / يميل لبراند\n                          واحد / يسيء لبراند معين / يعرض بدائل كثيرة جداً بدون داعي\n                        </div>\n</div>\n</div>\n<div class=\"guest-tab-content\" id=\"guest-tab-S\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"35\">S – المهارات البيعية</div>\n<div class=\"do-dont-grid\">\n<div class=\"do-box\">\n<span class=\"box-label\">أ – بيع رأسي</span>\n                            عرض نسخة أعلى من نفس نوع المنتج المطلوب (ضمن احتياج العميل)\n                          </div>\n<div class=\"do-box\">\n<span class=\"box-label\">ب – بيع أفقي</span>\n                            عرض منتج آخر (مكمل) للمنتج الأساسي\n                          </div>\n</div>\n<div class=\"do-box\" style=\"margin-top:8px;\">\n<span class=\"box-label\">ج – بيع بديل</span>\n                          عند عدم توافر منتج ما، يجب اقتراح بديل قريب في الجودة أو الاستخدام\n                        </div>\n<div class=\"subsection-title\" data-c=\"36\" style=\"margin-top:12px;\">التفاوض</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>لم يشعر بالقيمة:</strong> ارجع لاحتياج العميل، اربط\n                            كلامك عن فائدة المنتج بالحاجة اللي هو فعلاً محتاجها</li>\n<li><span class=\"bullet\"></span><strong>سعر أقل:</strong> استخدم التقسيط كحل للعميل للوصول\n                            لمنطقة وسط</li>\n<li><span class=\"bullet\"></span><strong>مقارنة منافس:</strong> خصومات بناء على المنافس إذا\n                            وُضح إنه نفس المنتج بسعر أقل</li>\n<li><span class=\"bullet\"></span><strong>ركز على القيمة:</strong> لا تبدأ بالسعر، ابدأ\n                            بالفائدة. هيوفر ايه على المدى الطويل</li>\n</div>\n</div>\n</div>\n<div class=\"guest-tab-content\" id=\"guest-tab-T\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"37\">T – الشكر والتوديع (Thank)</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>إغلاق البيعة:</strong> تلخيص مزايا المنتج مع احتياج\n                            العميل في النهاية لتأكيد أن هذا هو المنتج المناسب</li>\n<li><span class=\"bullet\"></span><strong>رسالة Survey:</strong> بعد إتمام عملية البيع قبل ما\n                            العميل يمشي، لازم نعرفه إنه هيجيله Survey في رسالة SMS على تليفونه</li>\n<li><span class=\"bullet\"></span><strong>التوديع اللفظي:</strong> \"نورتنا يا فندم\" - \"نحب نشوف\n                            حضرتك تاني\"</li>\n<li><span class=\"bullet\"></span><strong>التوديع غير اللفظي:</strong> ابتسامة بسيطة – وقفة\n                            معتدلة – تواصل بصري مع العميل</li>\n</div>\n</div>\n</div>\n</div>\n","words":573},{"id":"complaints","title":"التعامل مع الشكاوى","group":"البيع","icon":"message-warning","html":"\n<div class=\"section-body\">\n<div class=\"guest-steps\">\n<div class=\"guest-step active-step\" data-c=\"38\" onclick=\"showSectionTab('complaints', 'angry', this)\" style=\"cursor:pointer;\">العميل الغاضب</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('complaints', 'objection', this)\" style=\"cursor:pointer;\">التعامل مع الاعتراض</div>\n<div class=\"guest-step\" onclick=\"showSectionTab('complaints', 'escalation', this)\" style=\"cursor:pointer;\">تصعيد الشكاوى</div>\n</div>\n<div class=\"section-tab-content\" id=\"complaints-tab-angry\" style=\"display: block;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"39\">عند التعامل مع العميل الغاضب – ثلاث خطوات</div>\n<div class=\"protocol-step\">\n<div class=\"protocol-step-num\">1</div>\n<div class=\"protocol-step-content\">\n<div class=\"protocol-step-title\" data-c=\"40\">الوعي</div>\n<div class=\"protocol-step-text\">قبل أي رد فعل، لازم تكون واعي ليه العميل متضايق: هل المشكلة\n                              معايا شخصياً؟ لو كنت مكانه، هل كنت هحس بنفس الانفعال؟</div>\n</div>\n</div>\n<div class=\"protocol-step\">\n<div class=\"protocol-step-num\">2</div>\n<div class=\"protocol-step-content\">\n<div class=\"protocol-step-title\" data-c=\"41\">التضامن</div>\n<div class=\"protocol-step-text\">أظهر تعاطفك بتعابير وجه حريصة: \"متفهم موقف حضرتك\" أو \"لو كنت\n                              مكانك كنت هحس كده برضه\". تجنب قول كلمات زي \"أهدى\". لا تستخدم ابتسامة أبداً والعميل متعصب.\n                            </div>\n</div>\n</div>\n<div class=\"protocol-step\">\n<div class=\"protocol-step-num\">3</div>\n<div class=\"protocol-step-content\">\n<div class=\"protocol-step-title\" data-c=\"42\">الفهم والحل</div>\n<div class=\"protocol-step-text\">اسأل أسئلة تساعدك تفهم المشكلة بعمق. رد بطريقة واضحة وصريحة.\n                              استخدم كلمات تعكس حرص الشركة: \"احنا في RAYA حريصين على تحقيق رضا حضرتك\".</div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"complaints-tab-objection\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"43\">التعامل مع الاعتراض</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>الاستماع الجيد + تلخيص الكلام على العميل (عشان يحس أنه فعلاً\n                            وصلك رأيه)</li>\n<li><span class=\"bullet\"></span>شكر العميل على مشاركته لرأيه معنا وأنه رأيه مهم</li>\n<li><span class=\"bullet\"></span>التأكيد عليه أننا في RAYA بنحرص دايما على التطور والاستماع\n                            للعملاء</li>\n</div>\n</div>\n</div>\n<div class=\"section-tab-content\" id=\"complaints-tab-escalation\" style=\"display: none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"44\">تصعيد الشكاوى – المسار الرسمي (أقصى 48 ساعة)</div>\n<div class=\"escalation-flow\">\n<div class=\"escalation-step\">\n<div class=\"e-num e-num-1\">1</div>\n<div>\n<div class=\"e-title\" data-c=\"45\">الموظف (الوجهة الأولى)</div>\n<div class=\"e-desc\">استقبال شكوى العميل ومحاولة الحل الفوري</div>\n</div>\n</div>\n<div class=\"escalation-step\">\n<div class=\"e-num e-num-2\">2</div>\n<div>\n<div class=\"e-title\" data-c=\"46\">مدير الفرع</div>\n<div class=\"e-desc\">يتدخل ويحاول حل المشكلة إذا لم يتم الحل</div>\n</div>\n</div>\n<div class=\"escalation-step\">\n<div class=\"e-num e-num-3\">3</div>\n<div>\n<div class=\"e-title\" data-c=\"47\">مدير المنطقة</div>\n<div class=\"e-desc\">يتخذ قراراً فورياً</div>\n</div>\n</div>\n<div class=\"escalation-step\">\n<div class=\"e-num e-num-4\">4</div>\n<div>\n<div class=\"e-title\" data-c=\"48\">مدير المبيعات</div>\n<div class=\"e-desc\">المراجعة النهائية واتخاذ القرار – الحل المرضي لجميع الأطراف</div>\n</div>\n</div>\n</div>\n<div class=\"info-badge badge-red\" style=\"display:inline-block; margin-top:8px; font-size:13px; padding:6px 14px;\">⏱️ إجمالي\n                          الوقت المسموح لجميع مراحل التصعيد: 48 ساعة كحد أقصى</div>\n</div>\n</div>\n</div>\n","words":188},{"id":"policies","title":"السياسات","group":"القواعد","icon":"scroll","html":"\n<div class=\"section-body\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; margin-bottom: 16px;\">\n<div class=\"guest-step active-step\" data-c=\"49\" onclick=\"showMainPolicyTab('exchange', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">سياسة الاستبدال والاسترجاع</div>\n<div class=\"guest-step\" onclick=\"showMainPolicyTab('omni', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">Omni-Channel</div>\n<div class=\"guest-step\" onclick=\"showMainPolicyTab('csat', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">C-SAT vs NPS</div>\n<div class=\"guest-step\" onclick=\"showMainPolicyTab('rewards', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">مكافآت العملاء</div>\n<div class=\"guest-step\" onclick=\"showMainPolicyTab('maintenance_centers', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">عناوين الصيانة</div>\n<div class=\"guest-step\" onclick=\"showMainPolicyTab('raya_dealer', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">صيانة راية والوكيل</div>\n</div>\n<div class=\"main-policy-tab-content\" id=\"main-policy-exchange\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; margin-bottom: 16px;\">\n<div class=\"guest-step active-step\" data-c=\"50\" onclick=\"showSubPolicyTab('timeframe', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">الإطار الزمني</div>\n<div class=\"guest-step\" onclick=\"showSubPolicyTab('conditions', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">شروط القبول</div>\n<div class=\"guest-step\" onclick=\"showSubPolicyTab('refund', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">إرجاع الفلوس</div>\n</div>\n<div class=\"sub-policy-tab-content\" id=\"sub-policy-timeframe\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"51\">الإطار الزمني للاسترجاع</div>\n<table class=\"policy-table\">\n<tr>\n<th>المدة</th>\n<th>الشرط</th>\n<th>نوع الحق</th>\n</tr>\n<tr>\n<td>14 يوم</td>\n<td>المنتج بحالته الأصلية (مقفول ومتبرشم)</td>\n<td>تغيير الرأي</td>\n</tr>\n<tr>\n<td>30 يوم</td>\n<td>تقديم \"تقرير فني\" من وكيل المنتج يُثبت العيب</td>\n<td>عيوب الصناعة</td>\n</tr>\n</table>\n</div>\n</div>\n<div class=\"sub-policy-tab-content\" id=\"sub-policy-conditions\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"52\">شروط قبول الاسترجاع</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>الفاتورة أولاً:</strong> فاتورة الشراء هي جواز السفر\n                              لأي عملية استرجاع</li>\n<li><span class=\"bullet\"></span><strong>الأجهزة الذكية (الموبايل والتابلت):</strong> العلبة\n                              لازم تكون متبرشمة ولم يتم فتحها أو تفعيل الجهاز</li>\n<li><span class=\"bullet\"></span><strong>منتجات العناية الشخصية:</strong> لأسباب صحية بحتة،\n                              لا تُسترجع ولا تُستبدل بمجرد فتح علبتها (إلا في حالة إثبات عيب صيانة)</li>\n<li><span class=\"bullet\"></span><strong>سوء النقل والاستلام:</strong> لو العميل نقل الجهاز\n                              بشكل خاطئ وتضرر، هنا بنعتذر بلباقة عن الاسترجاع</li>\n</div>\n</div>\n</div>\n<div class=\"sub-policy-tab-content\" id=\"sub-policy-refund\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"53\">طريقة إرجاع الفلوس</div>\n<div class=\"do-dont-grid\">\n<div class=\"do-box\">\n<span class=\"box-label\">💵 كاش</span>\n                              العميل بيستلم قيمة المنتج نقداً من أي فرع من فروعنا\n                            </div>\n<div class=\"do-box\">\n<span class=\"box-label\">💳 فيزا/بطاقة</span>\n                              المبلغ بيرجع لحسابه خلال 14 يوم عمل عبر طلب Remedy\n                            </div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"main-policy-tab-content\" id=\"main-policy-omni\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"54\">Omni-Channel – راية كلها بيت واحد</div>\n<div class=\"content-text\">معناها إننا بنقدم للضيف أفضل خدمة من خلال كل قنوات بيع راية، سواء كان\n                          أونلاين، في الفرع، أو عن طريق الكول سنتر.</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>سيناريو 1:</strong> المنتج مش عندي → ابحث في الفروع\n                            التانية، اعرض الحجز والدفع في فرعك والاستلام من الفرع الآخر</li>\n<li><span class=\"bullet\"></span><strong>سيناريو 2:</strong> ضيف الأونلاين والكول سنتر → رحب\n                            بيه جداً واطلب رقم الأوردر وسلمه المنتج فوراً</li>\n<li><span class=\"bullet\"></span><strong>سيناريو 3:</strong> شراء المنتج من فرع آخر واسترجاعه →\n                            رحب بيه واستلم المرتجع فوراً</li>\n<li><span class=\"bullet\"></span><strong>سيناريو 4:</strong> المنتج مش في الفروع نهائياً → افتح\n                            راية شوب Online وساعد العميل يطلبه</li>\n</div>\n<div class=\"info-row\"><span class=\"info-badge badge-yellow\">📞 للاستعلام والاستفسار:\n                            19900</span></div>\n</div>\n</div>\n<div class=\"main-policy-tab-content\" id=\"main-policy-csat\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"55\">C-SAT vs NPS – مقياس نجاح صاحب البيت</div>\n<div class=\"do-dont-grid\">\n<div class=\"do-box\">\n<span class=\"box-label\">😊 C-SAT (رضا العميل)</span>\n                            مدى رضاه عن تجربته الآن. الهدف: رضا فوري.<br/>\n                            الحساب: عدد التقييمات الإيجابية ÷ إجمالي عدد التقييمات × 100\n                          </div>\n<div class=\"do-box\">\n<span class=\"box-label\">📣 NPS (ولاء العميل)</span>\n                            مدى احتمالية ترشيحه لراية. الهدف: ولاء دائم.<br/>\n                            الحساب: % المروجين (9-10) - % المنتقدين (0-6)\n                          </div>\n</div>\n<div class=\"content-text\" style=\"margin-top:8px; font-style:italic; color:var(--raya-blue);\">الـ\n                          CSAT بيقيس نجاحك في بيعة النهاردة، لكن الـ NPS بيقيس نجاحك في بناء علاقة دائمة مع العميل.\n                        </div>\n</div>\n</div>\n<div class=\"main-policy-tab-content\" id=\"main-policy-rewards\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"56\">برنامج مكافآت لعملاء راية</div>\n<div class=\"content-text\" style=\"text-align:center;\">\n<h3 data-c=\"57\">أمسح الكود</h3>\n<div style=\"width:200px; height:200px; background:#fff; display:inline-flex; align-items:center; justify-content:center; margin:20px 0;\">\n<img alt=\"QR Code\" src=\"rewards-qr.png\" style=\"width:100%; height:100%; object-fit:contain;\"/>\n</div>\n<br/>\n<a href=\"#\" style=\"display:inline-block; background:#000; color:#fff; padding:10px 20px; border-radius:30px; text-decoration:none; font-size:20px;\">\n                            📱 Scan Me\n                          </a>\n</div>\n</div>\n</div>\n<div class=\"main-policy-tab-content\" id=\"main-policy-maintenance_centers\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"58\">عناوين مراكز صيانة راية</div>\n<div style=\"background:var(--raya-blue); color:white; padding:8px 12px; border-radius:8px; margin-bottom:10px; font-weight:bold; width:max-content;\">\n                          القاهرة والجيزة</div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li><span class=\"bullet\"></span><strong>مدينة نصر:</strong> 1 شارع عبد الحميد لطفي - آخر مكرم\n                            عبيد - راية</li>\n<li><span class=\"bullet\"></span><strong>شبرا:</strong> 57 ش شبرا - بجوار بنك مصر - ميجا ستور\n                            راية</li>\n<li><span class=\"bullet\"></span><strong>جسر السويس:</strong> 43 شارع الليث من جسر السويس -\n                            أمام عمارات الميرلاند - راية</li>\n<li><span class=\"bullet\"></span><strong>الهرم:</strong> 166 شارع الهرم - بجوار شارع العريش -\n                            راية</li>\n<li><span class=\"bullet\"></span><strong>الدقي:</strong> 14 ش مصدق - راية</li>\n</div>\n<div style=\"background:var(--raya-blue); color:white; padding:8px 12px; border-radius:8px; margin-bottom:10px; font-weight:bold; width:max-content;\">\n                          محافظات أخرى</div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li><span class=\"bullet\"></span><strong>الإسكندرية:</strong> برج 7 أبراج الصيادلة - شارع جامع\n                            حاتم - بجوار مديرية الأمن - راية</li>\n<li><span class=\"bullet\"></span><strong>الزقازيق:</strong> شارع د/ طلبة عويضة - برج أديب -\n                            راية</li>\n<li><span class=\"bullet\"></span><strong>أسيوط:</strong> 14 ب ش الجمهورية - ميجا ستور راية</li>\n<li><span class=\"bullet\"></span><strong>طنطا:</strong> ش المديرية - مبنى عمر أفندي - الدور\n                            الأول - ميجا ستور راية</li>\n<li><span class=\"bullet\"></span><strong>المنصورة:</strong> 22 ش الجمهورية - برج النورس - أمام\n                            جامعة المنصورة - راية</li>\n<li data-c=\"59\"><span class=\"bullet\"></span><strong>الأقصر:</strong> ش التلفزيون مع ش المدينة المنورة -\n                            ميجا ستور راية</li>\n</div>\n<div style=\"background:var(--raya-blue); color:white; padding:8px 12px; border-radius:8px; margin-bottom:10px; font-weight:bold; width:max-content;\">\n                          فروع التجميع</div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li><span class=\"bullet\"></span><strong>الإسماعيلية:</strong> 37 شارع الإسكندرية - بجوار\n                            المحطة الجديدة - هاي تك</li>\n<li><span class=\"bullet\"></span><strong>السويس:</strong> 31 شارع الجيش - بجوار مسجد الأربعين -\n                            سيد عوض</li>\n<li><span class=\"bullet\"></span><strong>المنيا:</strong> ش طه حسين - أمام النادي الرياضي -\n                            العالمية</li>\n<li><span class=\"bullet\"></span><strong>المنيا:</strong> شارع الجمهورية - أمام مطعم الهادي -\n                            مغاغة - ستار</li>\n</div>\n<div class=\"info-row\"><span class=\"info-badge badge-blue\" style=\"font-size:16px;\">للاستعلام\n                            والاستفسار يرجى الاتصال على 19900</span></div>\n</div>\n</div>\n<div class=\"main-policy-tab-content\" id=\"main-policy-raya_dealer\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"60\">صيانة راية &amp; صيانة الوكيل</div>\n<div class=\"content-text\" style=\"margin-bottom:16px;\">\n                          من أهم أدوارك كـ \"صاحب بيت\" إنك تبلغ ضيفك بمراكز الصيانة من غير ما يسأل وكمان تقف جنب ضيفك لو\n                          جهازه حصله مشكلة بعد البيع. عشان توجه العميل صح وبثقة، دي الخريطة الكاملة والمعتمدة لكل\n                          الماركات:\n                        </div>\n<div style=\"background:#e0e0e0; padding:10px; border-radius:8px; font-weight:bold; margin-bottom:12px;\">\n                          1. أجهزة صيانتها في \"بيتنا\" بتدخل صيانة راية وتُتابع عبر الكول سنتر 19900 📞\n                        </div>\n<div class=\"content-text\" style=\"margin-bottom:12px;\">البراندات دي العميل بيسلمها لينا أو\n                          بيتابعها معانا مباشرة:</div>\n<div class=\"do-dont-grid\" style=\"grid-template-columns: repeat(2, 1fr); gap: 10px; margin-bottom:20px;\">\n<div class=\"do-box\" style=\"border-top:4px solid #3498db; background:#f0f8ff;\">\n<span class=\"box-label\">الموبايلات والإكسسوارات (HHP)</span>\n<div style=\"font-size:12px; line-height:1.4;\">ACE, AllCall, Aukey, Benco, CMF, HMD, Hoco,\n                              Huawei, IKU, Infinix, itel, Lenovo, Micromax, Motorola, Nokia, Nothing, Oraimo, TECNO,\n                              SARY</div>\n</div>\n<div class=\"do-box\" style=\"border-top:4px solid #2ecc71; background:#f0fff0;\">\n<span class=\"box-label\">أجهزة التكنولوجيا واللاب توب (IT)</span>\n<div style=\"font-size:12px; line-height:1.4;\">Asus, Canon, Lexmark, Xerox, MSI</div>\n</div>\n<div class=\"do-box\" data-c=\"61\" style=\"border-top:4px solid #f39c12; background:#fffdf0;\">\n<span class=\"box-label\">الشاشات (TV)</span>\n<div style=\"font-size:12px; line-height:1.4;\">Beko, SARY</div>\n</div>\n<div class=\"do-box\" style=\"border-top:4px solid #9b59b6; background:#fdf0ff;\">\n<span class=\"box-label\">الأجهزة المنزلية الصغيرة والعناية</span>\n<div style=\"font-size:12px; line-height:1.4;\">Braun, DELONGHI, Kenwood, Philips, SARY</div>\n</div>\n</div>\n<div style=\"background:#e0e0e0; padding:10px; border-radius:8px; font-weight:bold; margin-bottom:12px;\">\n                          2. أجهزة صيانتها عند \"الوكيل الخارجي\" Call Service Provider ⚙️\n                        </div>\n<div class=\"content-text\" style=\"margin-bottom:12px;\">البراندات دي بتوجه العميل يتواصل مباشرة مع\n                          خدمة عملاء الوكيل المختص لتوفير وقته لأنهم أسرع في التعامل معاها:</div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li><span class=\"bullet\"></span><strong>سامسونج (Samsung):</strong> تحول للوكيل لجميع المنتجات\n                            📞 19580</li>\n<li><span class=\"bullet\"></span><strong>بيكو (Beko):</strong> الأجهزة المنزلية الكبيرة\n                            والتكييفات تحول للوكيل الخارجي 📞 16165 (الشاشات والأجهزة الصغيرة صيانة داخلية راية)</li>\n<li><span class=\"bullet\"></span><strong>كونتكس (Contex):</strong> الشاشات (TV) تحول للوكيل\n                            الخارجي للشاشات 📞 19501</li>\n</div>\n<div style=\"background:#fff3cd; border-right:4px solid #ffc107; padding:12px; border-radius:4px;\">\n<h4 data-c=\"62\" style=\"color:#856404; margin:0 0 8px 0;\">📌 خد بالك:</h4>\n<div class=\"content-text\" style=\"font-size:13px;\">\n                            \"لما العميل يجيلك بعطل، متقولوش روح للتوكيل وتسيبه يمشي. افتح الدليل ده،\"\n                            <ul style=\"margin-top:8px; padding-right:20px;\">\n<li>ولو الجهاز تبعنا قوله: \"يا فندم الجهاز ده صيانته تبعنا، ونبلغه أقرب عنوان لمراكز\n                                الصيانة القريب منه\" وكمان حضرتك تقدر تكلم 19900</li>\n<li>ولو تبع الوكيل قوله: \"الجهاز ده صيانته بتتم أسرع من خلال التوكيل المعتمد\".. توجيهك\n                                الدقيق هو خدمة ما بعد البيع الحقيقية!</li>\n</ul>\n</div>\n</div>\n</div>\n</div>\n</div>\n","words":724},{"id":"protocols","title":"بروتوكولات التقسيط والتمويل","group":"القواعد","icon":"wallet","html":"\n<div class=\"section-body\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; margin-bottom: 16px;\">\n<div class=\"guest-step active-step\" data-c=\"63\" onclick=\"showMainProtocolTab('raya', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكولات راية</div>\n<div class=\"guest-step\" onclick=\"showMainProtocolTab('installment', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكولات التقسيط</div>\n</div>\n<div class=\"main-protocol-tab-content\" id=\"main-protocol-raya\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; margin-bottom: 16px;\">\n<div class=\"guest-step active-step\" data-c=\"64\" onclick=\"showSubProtocolTab('owner', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">صاحب البيت</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('clean', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">النظافة</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('deploy', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">الانتشار</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('close', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">الإغلاق</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-owner\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"65\">بروتوكول \"صاحب البيت\"</div>\n<div class=\"content-text\" style=\"margin-bottom:16px;\">\n                            الفرع مش مجرد مكان بنبيع فيه، ده \"بيتنا\" اللي بنستقبل فيه ضيوفنا كل يوم. وعشان التجربة تكون\n                            مثالية، لازم يكون عندنا نظام واضح من أول دقيقة بنفتح فيها الباب لحد ما نقفله.\n                          </div>\n<div style=\"background:#003399; color:white; padding:8px; border-radius:4px; font-weight:bold; margin-bottom:10px;\">\n                            9:30 صباحاً: الاستعداد لبدء العمل</div>\n<div class=\"rule-list\" style=\"margin-bottom:16px;\">\n<li data-c=\"66\"><span class=\"bullet\"></span><strong>تأكد من تواجد جميع أفراد الفريق</strong></li>\n<li><span class=\"bullet\"></span><strong>تجهيز الفرع:</strong> تشغيل الإضاءة، التكييف، وأجهزة\n                              العرض</li>\n<li data-c=\"67\"><span class=\"bullet\"></span><strong>مراجعة سريعة للأهداف اليومية</strong></li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px; border-radius:4px; font-weight:bold; margin-bottom:10px;\">\n                            مظهر الموظف المحترف (سياسة الملابس)</div>\n<div class=\"do-dont-grid\" style=\"margin-bottom:16px;\">\n<div class=\"do-box\">\n<span class=\"box-label\">✅ المسموح به</span>\n<ul style=\"margin:5px 0 0 20px; padding:0;\">\n<li>قميص بولو \"راية\" نظيف ومكوي</li>\n<li>بنطلون جينز غير ممزق</li>\n<li>أحذية كاجوال أنيقة</li>\n</ul>\n</div>\n<div class=\"dont-box\">\n<span class=\"box-label\">❌ الممنوع</span>\n<ul style=\"margin:5px 0 0 20px; padding:0;\">\n<li>شورت</li>\n<li>قميص مجعد أو غير نظيف</li>\n<li>شباشب، أحذية رياضية</li>\n</ul>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px; border-radius:4px; font-weight:bold; margin-bottom:10px;\">\n                            10:00 صباحاً: فتح الأبواب للعملاء</div>\n<div class=\"rule-list\" style=\"margin-bottom:16px;\">\n<li><span class=\"bullet\"></span>فتح أبواب الفرع واستقبال العملاء بابتسامة واحترافية</li>\n</div>\n<div class=\"info-row\"><span class=\"info-badge badge-yellow\" style=\"font-size:16px;\">(الضيف\n                              الأول زي الضيف الأخير، بياخد أحسن خدمة)</span></div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-clean\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"68\">بروتوكول النظافة واجهة بيتك</div>\n<div class=\"do-dont-grid\" style=\"margin-bottom:16px;\">\n<div class=\"do-box\" style=\"border-top:4px solid #3498db; background:#f4f9f9;\">\n<span class=\"box-label\">النظافة مش بتمشي لوحدها، \"متابعة\" صاحب البيت هي السر.</span>\n<ul style=\"margin:5px 0 0 20px; padding:0;\">\n<li>صاحب البيت بيفكر عامل النظافة بمسؤوليته</li>\n<li>تذكير يومي بجميع نقاط النظافة (التأكد من النظافة بعد الانتهاء)</li>\n<li>المسؤولية هنا هي \"المتابعة\" من صاحب البيت لكل تفصيلة.</li>\n</ul>\n</div>\n<div class=\"do-box\" style=\"border-top:4px solid #3498db; background:#f4f9f9;\">\n<span class=\"box-label\">متابعة نظافة الفرع</span>\n<ul style=\"margin:5px 0 0 20px; padding:0;\">\n<li>الموبايلات خالية من البصمات</li>\n<li>الشاشات بتلمع بوضوح</li>\n<li>الأرفف مترتبة بشكل مثالي</li>\n</ul>\n</div>\n</div>\n<div style=\"background:#fdf2e9; border:2px solid #f39c12; padding:12px; border-radius:8px; text-align:center;\">\n<h4 data-c=\"69\" style=\"color:#d35400; margin:0 0 8px 0; font-size:18px;\">القاعدة الذهبية: متى وكيف؟</h4>\n<div style=\"font-weight:bold; font-size:16px; margin-bottom:10px;\">\n                              النظافة بتتعمل \"قبل\" دخول العملاء أو في أوقات الهدوء...<br/>\n<span style=\"color:red;\">إياك تمسح أو تنظف والضيف واقف قدامك!</span>\n</div>\n<div style=\"display:flex; justify-content:space-around;\">\n<div style=\"color:green; font-weight:bold;\">✅ قبل دخول العملاء / أوقات الهدوء (CORRECT)\n                              </div>\n<div style=\"color:red; font-weight:bold;\">❌ أوقات دخول العملاء (WRONG / NO!)</div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-deploy\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"70\">بروتوكول الانتشار</div>\n<div style=\"font-weight:bold; font-size:16px; margin-bottom:10px;\">أولاً: حسب حجم الفرع عادي\n                            ولا ميجا؟</div>\n<div class=\"do-dont-grid\" style=\"margin-bottom:20px;\">\n<div class=\"do-box\">\n<span class=\"box-label\" style=\"background:#003399; color:white; padding:4px 8px; border-radius:4px; display:inline-block; margin-bottom:8px;\">الفروع\n                                العادية: المناطق والتغطية السريعة</span>\n<ul style=\"margin:0 0 0 20px; padding:0;\">\n<li><strong>طريقة:</strong> الفرع بيتقسم لمناطق، وكل موظف مسؤول عن منطقة بس عينه على\n                                  الفرع كله.</li>\n<li>لو زميلك مشغول مع ضيف، إنت بتتحرك فوراً تغطي مكانه عشان مفيش ضيف يدخل وميلاقيش حد\n                                  يستقبله.</li>\n</ul>\n</div>\n<div class=\"do-box\">\n<span class=\"box-label\" style=\"background:#003399; color:white; padding:4px 8px; border-radius:4px; display:inline-block; margin-bottom:8px;\">فروع\n                                الميجا الأدوار المتعددة: الأدوار والمسؤوليات</span>\n<ul style=\"margin:0 0 0 20px; padding:0;\">\n<li><strong>موظف الاستقبال:</strong> أهم شخص في الفرع الميجا! لازم يكون فيه استاف متمركز\n                                  على الباب الرئيسي، بيستقبل الضيف، يرحب بيه، ويوجهه للدور أو القسم الصح فوراً.</li>\n<li><strong>قائد لكل دور:</strong> كل دور لازم يكون فيه موظف ثابت مبيسيبوش، عشان العميل\n                                  ميطلعش السلم ويلاقي الدور فاضي.</li>\n<li data-c=\"71\"><strong>بروتوكول تسليم الضيف عبر الأدوار (التسليم):</strong> \"اتفضل، مع حضرتك (اسم\n                                  الشخص) من (القسم أو البراند) هيساعدك في كل اللي تحتاجه\".</li>\n</ul>\n</div>\n</div>\n<div style=\"font-weight:bold; font-size:16px; margin-bottom:10px;\">ثانياً: حسب موقع الفرع شارع\n                            ولا مول؟</div>\n<div class=\"do-dont-grid\" style=\"margin-bottom:20px;\">\n<div class=\"do-box\">\n<span class=\"box-label\" style=\"background:#003399; color:white; padding:4px 8px; border-radius:4px; display:inline-block; margin-bottom:8px;\">فروع\n                                الشارع: الترافيك والواجهة</span>\n<ul style=\"margin:0 0 0 20px; padding:0;\">\n<li>الترافيك بييجي على فترات، وفي أوقات الذروة بيكون مكثف.</li>\n<li>الاستاف متواجد في النصف الأول كل من الفرع (الواجهة).</li>\n<li>بيدي تشجيع للناس إنها تدخل.</li>\n</ul>\n</div>\n<div class=\"do-box\">\n<span class=\"box-label\" style=\"background:#003399; color:white; padding:4px 8px; border-radius:4px; display:inline-block; margin-bottom:8px;\">فروع\n                                المولات: الوقت والتوزيع</span>\n<ul style=\"margin:0 0 0 20px; padding:0;\">\n<li>عميل المول غالباً وقته أضيق وبيلف على محلات كتير وبيعمل مقارنات سريعة.</li>\n<li>التوزيع هنا بيعتمد على 30 ثانية \"سرعة الالتقاط\".</li>\n</ul>\n</div>\n</div>\n<div class=\"info-row\"><span class=\"info-badge badge-yellow\" style=\"font-size:16px;\">(تأكد من\n                              وجود استاف في واجهة فروع الشارع، وركز على سرعة الالتقاط في أول 30 ثانية في المول.)</span>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-close\" style=\"display:none;\">\n<div class=\"subsection\" style=\"margin-top:16px;\">\n<div class=\"subsection-title\" data-c=\"72\">بروتوكول الاغلاق</div>\n<div class=\"do-dont-grid\" style=\"margin-bottom:16px;\">\n<div class=\"do-box\">\n<span class=\"box-label\" style=\"background:#003399; color:white; padding:4px 8px; border-radius:4px; display:inline-block; margin-bottom:8px;\">آخر\n                                ضيف</span>\n<ul style=\"margin:0 0 0 20px; padding:0;\">\n<li><strong>الضيف الأهم:</strong> لو عميل دخل الفرع قبل موعد الإغلاق بدقيقة واحدة،\n                                  بيتعامل كأنه أول عميل في اليوم.</li>\n<li>ممنوع تماماً نقفل الأنوار أو نلم الأجهزة أو نحسسه إننا مستعجلين.</li>\n</ul>\n</div>\n<div class=\"do-box\">\n<span class=\"box-label\" style=\"background:#003399; color:white; padding:4px 8px; border-radius:4px; display:inline-block; margin-bottom:8px;\">بعد\n                                خروج آخر ضيف</span>\n<ul style=\"margin:0 0 0 20px; padding:0;\">\n<li>ترتيب الفرع عشان زمايلنا بتوع الشفت الصباحي ييجي يلاقيه جاهز بنسبة 100%.</li>\n</ul>\n</div>\n</div>\n<div class=\"info-row\"><span class=\"info-badge badge-yellow\" style=\"font-size:16px;\">(الضيف\n                              الأخير زي الضيف الأول، بياخد أحسن خدمة وتوديع يليق ببيتنا.)</span></div>\n</div>\n</div>\n</div>\n<div class=\"main-protocol-tab-content\" id=\"main-protocol-installment\" style=\"display:none;\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; margin-bottom: 16px;\">\n<div class=\"guest-step active-step\" data-c=\"73\" onclick=\"showSubProtocolTab('inst_1', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول التقسيط</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('inst_2', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">مقابل بطاقة</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('inst_3', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">مقابل حد ائتماني</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('inst_4', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">راتب افتراضي</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('inst_5', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">تمويل غير المؤمن عليهم</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-inst_1\">\n<div style=\"text-align:center; padding: 10px;\">\n<div style=\"background-color: #f8f9fa; border: 1px solid #ddd; border-radius: 8px; padding: 20px; direction: rtl; text-align: right; font-family: 'Tajawal', sans-serif;\">\n<h2 data-c=\"74\" style=\"color: #1a2f6e; text-align: center; font-size: 28px; font-weight: 900; margin-bottom: 10px;\">\n                              بروتوكول التقسيط</h2>\n<p style=\"text-align: center; color: #555; font-size: 15px; margin-bottom: 25px;\">\n                              في Raya، إحنا بنسهل على العميل يشتري اللي نفسه فيه، بس كـ \"صاحب بيت\" شاطر، لازم تبقى عارف\n                              إزاي تختار البرامج الصح والورق المظبوط عشان العملية تمشي بسرعة وبدون أخطاء. دي قواعدنا\n                              الثابتة:\n                            </p>\n<h3 data-c=\"75\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">1. برنامج\n                              الأفراد العميل الأساسي</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">السن:</strong> من 21 لحد 65 سنة. وممكن لحد 67 سنة لو\n                                جاب ضامن درجة أولى.</li>\n<li><strong style=\"color: #0033cc;\">الدخل:</strong> الحد الأدنى لدخله الشهري 3000 جنيه.\n                              </li>\n<li><strong style=\"color: #0033cc;\">لو هيقسط بالبطاقة بس مكتوب فيها الوظيفة:</strong>\n                                بنعتمدها بس لازم دخله كحد أدنى يكون 7000 جنيه.</li>\n<li><strong style=\"color: #0033cc;\">مدة الشغل:</strong> لازم يكون بقاله في وظيفته الحالية\n                                3 شهور على الأقل.</li>\n<li><strong style=\"color: #0033cc;\">عبء الدين DBR:</strong> أقساط العميل كلها متعديش 50%\n                                من دخله.</li>\n<li><strong style=\"color: #0033cc;\">الوظائف الحكومية المؤقتة:</strong> بنقبلها بشرط يجيب\n                                برنت تأميني ودخله لا يقل عن 7000 جنيه. لو دخله أعلى، لازم يجيب مفردات مرتب + ضامن درجة\n                                أولى.</li>\n</ul>\n<h3 data-c=\"76\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">2. إمتى\n                              بنحتاج نعمل \"زيارة ميدانية\" للعميل؟</h3>\n<p style=\"color: #444; font-size: 14px; margin-bottom: 5px;\">في حالات معينة لازم فريقنا يزور\n                              العميل للتأكد، وهي:</p>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>العميل بدون عمل أو ربة منزل.</li>\n<li>البطاقة مش مكتوب فيها وظيفة.</li>\n<li>العميل ملوش تاريخ ائتماني أو أول مرة يقسط عدم وجود I-Score.</li>\n<li>لو العميل بيقدم الطلب من فرع خارج محافظة سكنه.</li>\n</ul>\n<h3 data-c=\"77\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">3. إثبات\n                              الدخل: إيه الورق اللي بنقبله؟</h3>\n<strong style=\"color: #0033cc; font-size: 15px;\">المقبول 100%</strong>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>مفردات مرتب مختومة وحديثة، صلاحيتها 3 شهور من تاريخها.</li>\n<li>كشف حساب بنكي لآخر 6 شهور باين فيه تحويل الراتب.</li>\n<li>الـ Payslip، بنجيب بتاع الشهر الحالي + واحد أقدم.</li>\n<li>رسالة SMS موثقة من جهة العمل فيها صافي القبض.</li>\n<li>برنت تأميني حديث مكملش 3 شهور، مختوم بختم النسر أو طالع من \"مصر الرقمية\"، ومكتوب فيه\n                                اسم الشركة وآخر أجر تأميني.</li>\n<li>بيان معاش خلال 3 شهور ومختوم بختم النسر.</li>\n</ul>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>حاجات بتسند دخل إضافي بجانب الأساسي: شهادات استثمار أو ودائع باسمه، أو عقود إيجار\n                                بتدخله فلوس فعلية.</li>\n<li>لتعليات الليمت Limit Increase: لو العميل عاوز يزود الرصيد لازم يجيب أي إثبات دخل جديد\n                                من اللي ذكرناهم.</li>\n</ul>\n<h3 data-c=\"78\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">4. برامج\n                              تانية لضيوفنا</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">برنامج أصحاب الأعمال Self-Employed:</strong> للنشاط\n                                القائم. بيحتاج سجل تجاري + كشف حساب 6 شهور + زيارة ميدانية للسكن والنشاط.</li>\n<li><strong style=\"color: #0033cc;\">برنامج الشركاء Partners:</strong> نفس شروط أصحاب\n                                الأعمال بالظبط، بس بنزود عليها \"مستند رسمي\" يوضح نسبة ملكية العميل في الشركة دي.</li>\n<li><strong style=\"color: #0033cc;\">برنامج جيل Z للطلاب:</strong> لطلبة الجامعات الحكومية\n                                والخاصة المحددة. الضامن: الأب أو الأم بوظيفة مثبتة. الورق المطلوب: كارنيه الطالب + بطاقة\n                                الضامن + إثبات دخل الضامن. والحد الائتماني هنا بيتحدد بناءً على دخل الأسرة.</li>\n</ul>\n<h3 data-c=\"79\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">5. خطوط\n                              حمراء: المحظورات عشان نحمي بيتنا</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">مناطق لا نقسط لها Blacklisted Areas:</strong> شمال\n                                سيناء، حلايب وشلاتين، الواحات، مرسى مطروح، قنطرة شرق.</li>\n<li><strong style=\"color: #0033cc;\">مهن لا نقسط لها Blacklisted Professions:</strong> ضباط\n                                الشرطة إلا لو مدنيين، الصحفيون، موظفو هيئة الإسعاف، والمحامي الحر / المستقل بنقبل\n                                المحامي بس لو بطاقته مكتوب فيها إنه موظف جوه شركة.</li>\n<li><strong style=\"color: #0033cc;\">ورق مرفوض تماماً:</strong> شهادة الدخل من أي محاسب\n                                قانوني، أو الوظائف الحكومية بنظام \"اليومية\".</li>\n</ul>\n<h3 data-c=\"80\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">6. ضيوفنا\n                              الغاليين ذوي الاحتياجات الخاصة</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>بالنسبة للعملاء من المكفوفين، بنرحب بيهم جداً، ولكن لتسهيل وتأمين الإجراءات يُشترط\n                                وجود \"ضامن درجة أولى\" الزوج أو الزوجة.</li>\n</ul>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-inst_2\" style=\"display:none;\">\n<div style=\"text-align:center; padding: 10px;\">\n<div style=\"background-color: #f8f9fa; border: 1px solid #ddd; border-radius: 8px; padding: 20px; direction: rtl; text-align: right; font-family: 'Tajawal', sans-serif;\">\n<h2 data-c=\"81\" style=\"color: #1a2f6e; text-align: center; font-size: 26px; font-weight: 900; margin-bottom: 5px;\">\n                              💳 بروتوكول \"حد ائتماني مقابل بطاقة\"</h2>\n<h3 data-c=\"82\" style=\"color: #333; text-align: center; font-size: 20px; font-weight: bold; margin-bottom: 20px;\">\n                              إزاي نقسط لضيفنا بناءً على كارت المشتريات؟</h3>\n<p style=\"text-align: center; color: #555; font-size: 15px; margin-bottom: 25px;\">\n                              لو ضيفنا معاه بطاقة ائتمان Credit Card وعاوز يعتمد عليها عشان ياخد حد ائتماني يقسط بيه\n                              عندنا، دي الشروط اللي لازم نمشي عليها عشان نسهلها عليه ونحفظ حق \"بيتنا\":\n                            </p>\n<h3 data-c=\"83\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">1. مين الضيف\n                              اللي يقدر يستفيد من البرنامج ده؟</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">السن:</strong> لازم يكون عمره من 21 سنة كحد أدنى، لحد\n                                65 سنة كحد أقصى.</li>\n<li><strong style=\"color: #0033cc;\">التعليم:</strong> البرنامج ده مخصص للضيوف الحاصلين على\n                                مؤهل جامعي بكالوريوس أو ليسانس.</li>\n<li><strong style=\"color: #0033cc;\">الشغل:</strong> لازم يكون بقاله في وظيفته 6 شهور على\n                                الأقل وبنتأكد من ده من البطاقة، أو التأمينات، أو منصة مصر الرقمية.</li>\n<li><strong style=\"color: #0033cc;\">مهن مش هينفع معاها البرنامج:</strong> الفنيين، العمالة\n                                اليدوية، السائقين، تجار الخضار والفاكهة، الجزارين، والمزارعين / الجناينية.</li>\n<li><strong style=\"color: #0033cc;\">الورق المطلوب:</strong> أسهل حاجة.. بطاقة رقم قومي\n                                سارية وبس!</li>\n</ul>\n<h3 data-c=\"84\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">2. الفحص\n                              الائتماني I-Score: هو لميزان بتاعنا</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>لازم نعمل استعلام إلزامي.</li>\n<li>بطاقة الائتمان بتاعة العميل لازم تكون من النوع \"الغير مضمنة\" Unsecured.</li>\n<li>العميل لازم يكون عنده بطاقة ائتمان حقيقية مبنية على ثقة البنك فيه مش بطاقة معمولها\n                                إصدار بضمان فلوس محجوزة.</li>\n</ul>\n<h3 data-c=\"85\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">3. تفاصيل\n                              التمويل والمدة</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">عبء الدين DBR:</strong> زي ما إحنا متعودين، أقساط\n                                الضيف كلها متعديش 50% من دخله.</li>\n<li><strong style=\"color: #0033cc;\">مدة التقسيط:</strong> بتبدأ من 10 شهور لحد 36 شهر.\n                              </li>\n</ul>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-inst_3\" style=\"display:none;\">\n<div style=\"text-align:center; padding: 10px;\">\n<div style=\"background-color: #f8f9fa; border: 1px solid #ddd; border-radius: 8px; padding: 20px; direction: rtl; text-align: right; font-family: 'Tajawal', sans-serif;\">\n<h2 data-c=\"86\" style=\"color: #1a2f6e; text-align: center; font-size: 26px; font-weight: 900; margin-bottom: 5px;\">\n                              💳 بروتوكول \"الحد الائتماني مقابل الحد الائتماني\"</h2>\n<h3 data-c=\"87\" style=\"color: #333; text-align: center; font-size: 20px; font-weight: bold; margin-bottom: 20px;\">\n                              التقسيط بضمان ليميت شركات تانية</h3>\n<p style=\"text-align: center; color: #555; font-size: 15px; margin-bottom: 25px;\">\n                              لو ضيفنا معندوش بطاقة ائتمان بنكية، بس عنده ليميت تقسيط شغال مع شركات تانية معتمدة نقدر\n                              نعتمد عليه ونديله ليميت يشتري بيه من عندنا.\n                              دي القواعد اللي هنمشي عليها:\n                            </p>\n<h3 data-c=\"88\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">1. مين الضيف\n                              اللي يقدر يستفيد من البرنامج ده؟</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">السن:</strong> لازم يكون عمره من 21 سنة كحد أدنى، لحد\n                                65 سنة كحد أقصى.</li>\n<li><strong style=\"color: #0033cc;\">التعليم:</strong> البرنامج ده مخصص للضيوف الحاصلين على\n                                مؤهل جامعي بكالوريوس أو ليسانس.</li>\n<li><strong style=\"color: #0033cc;\">الشغل:</strong> لازم يكون بقاله في وظيفته 6 شهور على\n                                الأقل وبنتأكد من ده من البطاقة، أو التأمينات، أو منصة مصر الرقمية.</li>\n<li><strong style=\"color: #0033cc;\">مهن مش هينفع معاها البرنامج:</strong> الفنيين، العمالة\n                                اليدوية، السائقين، تجار الخضار والفاكهة، الجزارين، والمزارعين / الجناينية.</li>\n<li><strong style=\"color: #0033cc;\">الورق المطلوب:</strong> أسهل حاجة.. بطاقة رقم قومي\n                                سارية وبس!</li>\n</ul>\n<h3 data-c=\"89\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">2. الفحص\n                              الائتماني I-Score: هو لميزان بتاعنا</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>لازم نعمل فحص إلزامي للـ I-Score.</li>\n</ul>\n<h3 data-c=\"90\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">3. تفاصيل\n                              التمويل والمدة</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">حجم العملية:</strong> الحد الأدنى لمبلغ التمويل Ticket\n                                Size هو 25,000 جنيه مصري.</li>\n<li><strong style=\"color: #0033cc;\">مدة السداد:</strong> Tenor التقسيط متاح من 10 شهور لحد\n                                36 شهر.</li>\n<li><strong style=\"color: #0033cc;\">عبء الدين DBR:</strong> زي ما إحنا متعودين، أقساط\n                                الضيف كلها متعديش 50% من دخله.</li>\n</ul>\n<h3 data-c=\"91\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">5. إيه هي\n                              الشركات المعتمدة عندنا؟</h3>\n<strong style=\"color: #0033cc; font-size: 15px;\">بنقبل الليميت من الشركات دي فقط</strong>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>أمان Aman</li>\n<li>فاليو Valu</li>\n<li>سهولة Souhoula</li>\n<li>كليفر Clever</li>\n<li>حالاً Halan</li>\n<li>ترو True</li>\n</ul>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-inst_4\" style=\"display:none;\">\n<div style=\"text-align:center; padding: 10px;\">\n<div style=\"background-color: #f8f9fa; border: 1px solid #ddd; border-radius: 8px; padding: 20px; direction: rtl; text-align: right; font-family: 'Tajawal', sans-serif;\">\n<h2 data-c=\"92\" style=\"color: #1a2f6e; text-align: center; font-size: 28px; font-weight: 900; margin-bottom: 5px;\">\n                              بروتوكول دخل الراتب الافتراضي</h2>\n<h3 data-c=\"93\" style=\"color: #333; text-align: center; font-size: 20px; font-weight: bold; margin-bottom: 20px;\">\n                              إزاي نقسط بالوظيفة</h3>\n<p style=\"text-align: center; color: #555; font-size: 15px; margin-bottom: 25px;\">\n                              البرنامج ده بقى معمول عشان نسهّل على ضيوفنا اللي معندهمش إثبات دخل مباشر، بس شغالين في\n                              وظايف ممتازة ومستقرة. الهدف هنا إننا نحدد الليميت للعميل بناءً على متوسط رواتب السوق\n                              لمهنته عشان تناسب أسعار الإلكترونيات عندنا.\n                            </p>\n<h3 data-c=\"94\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">1. مين الضيف\n                              المؤهل للبرنامج؟ شروط الموافقة السريعة</h3>\n<p style=\"color: #444; font-size: 14px; margin-bottom: 5px;\">عشان تدخل العميل في البرنامج\n                              ده، لازم تنطبق عليه الشروط دي:</p>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">السن:</strong> من 21 عاماً إلى 65 عاماً كحد أقصى.</li>\n<li><strong style=\"color: #0033cc;\">التعليم:</strong> مؤهل جامعي بكالوريوس / ليسانس.</li>\n<li><strong style=\"color: #0033cc;\">مدة العمل:</strong> لا تقل عن 3 أشهر يتم التحقق عبر\n                                ظهر البطاقة، التأمينات، أو بوابة مصر الرقمية.</li>\n<li><strong style=\"color: #0033cc;\">استثناء بسيط للموظف المبتدئ Junior:</strong> لو شغال\n                                في القطاع الحكومي بقاله أقل من 6 شهور، لازم نسأله عن قيمة دخله الفعلي وبنفصح عنه صراحةً.\n                              </li>\n<li><strong style=\"color: #0033cc;\">مهن خارج البرنامج:</strong> الفنيين، العمالة اليدوية،\n                                السائقين، بائعي الخضروات والفاكهة، الجزارين، والجناينية.</li>\n</ul>\n<h3 data-c=\"95\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">2. الفحص\n                              الائتماني I-Score الميزان بتاعنا</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li>لازم نعمل استعلام إلزامي.</li>\n</ul>\n<h3 data-c=\"96\" style=\"color: #333; font-size: 18px; margin-top: 20px; font-weight: bold;\">3. تفاصيل\n                              التقسيط</h3>\n<ul style=\"list-style-type: disc; padding-right: 20px; color: #444; font-size: 14px; line-height: 1.8;\">\n<li><strong style=\"color: #0033cc;\">عبء الدين DBR:</strong> أقساط الضيف كلها متعديش 50% من\n                                الدخل الافتراضي اللي هنحسبهوله.</li>\n<li><strong style=\"color: #0033cc;\">مدة التقسيط:</strong> التقسيط متاح من 10 شهور لحد 36\n                                شهر.</li>\n</ul>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-inst_5\" style=\"display:none;\">\n<div style=\"padding: 10px 0;\">\n<style>\n#sub-protocol-inst_5 {\n  --navy:#001780; --blue:#225FAC; --deep:#001E5A;\n  --bg:#F3F6FB; --surface:#FFFFFF; --tint:#E8EEF8; --line:#D3DCEC;\n  --fg:#14203D; --muted:#56637E;\n  --drv:#225FAC; --drv-soft:#E6EEF9;\n  --med:#0E7C74; --med-soft:#E2F3F1;\n  --ok:#1C7C45; --ok-soft:#E4F4EA; --no:#B3261E; --no-soft:#FBE9E7;\n  --warn:#9A5B00; --warn-soft:#FFF3DC;\n  --c: var(--drv); --cs: var(--drv-soft);\n  direction: rtl;\n  text-align: right;\n  font-family: 'Tajawal', 'Cairo', sans-serif;\n  font-size: 15.5px;\n  line-height: 1.7;\n  color: var(--fg);\n}\n#sub-protocol-inst_5 * { box-sizing: border-box; }\n#sub-protocol-inst_5 .wrap { max-width: 860px; margin: 0 auto; padding: 4px 6px; display: grid; gap: 24px; }\n#sub-protocol-inst_5 section { display: grid; gap: 12px; }\n#sub-protocol-inst_5 section > h2 { font-size: 20px; font-weight: 800; color: var(--navy); margin: 0 0 4px 0; border-bottom: 2px solid var(--tint); padding-bottom: 6px; }\n#sub-protocol-inst_5 .sub { color: var(--muted); font-size: 14px; margin: 0; }\n#sub-protocol-inst_5 .num { font-weight: 800; font-variant-numeric: tabular-nums; }\n#sub-protocol-inst_5 p { margin: 0; }\n/* idea */\n#sub-protocol-inst_5 .idea { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 18px; display: grid; gap: 12px; box-shadow: 0 2px 6px rgba(0,0,0,0.03); }\n#sub-protocol-inst_5 .idea .big { font-size: 17px; font-weight: 700; line-height: 1.6; color: var(--deep); }\n#sub-protocol-inst_5 .why { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; }\n#sub-protocol-inst_5 .why div { background: var(--tint); border-radius: 10px; padding: 12px 14px; font-size: 14px; }\n#sub-protocol-inst_5 .why b { display: block; font-weight: 800; margin-bottom: 4px; color: var(--blue); }\n/* program file */\n#sub-protocol-inst_5 .prog { border-radius: 16px; overflow: hidden; border: 1.5px solid var(--c); background: var(--surface); box-shadow: 0 2px 8px rgba(0,0,0,0.04); }\n#sub-protocol-inst_5 .prog.drv { --c: var(--drv); --cs: var(--drv-soft); }\n#sub-protocol-inst_5 .prog.med { --c: var(--med); --cs: var(--med-soft); }\n#sub-protocol-inst_5 .prog-head { background: var(--cs); padding: 16px 18px; display: grid; gap: 4px; border-bottom: 1.5px solid var(--c); }\n#sub-protocol-inst_5 .prog-head h3 { font-size: 20px; font-weight: 800; color: var(--c); margin: 0; }\n#sub-protocol-inst_5 .prog-body { display: grid; }\n#sub-protocol-inst_5 .row { display: grid; grid-template-columns: 130px 1fr; gap: 12px; padding: 12px 16px; border-top: 1px solid var(--line); align-items: start; }\n#sub-protocol-inst_5 .row:first-child { border-top: 0; }\n#sub-protocol-inst_5 .row > .k { font-weight: 700; color: var(--c); font-size: 14.5px; padding-top: 2px; }\n#sub-protocol-inst_5 .row > .v { min-width: 0; display: grid; gap: 8px; }\n@media (max-width: 600px) { #sub-protocol-inst_5 .row { grid-template-columns: 1fr; gap: 4px; } }\n#sub-protocol-inst_5 .range { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n#sub-protocol-inst_5 .range .num { font-size: 22px; color: var(--c); line-height: 1; }\n#sub-protocol-inst_5 .range .to { color: var(--muted); font-size: 14px; }\n#sub-protocol-inst_5 ul.check { list-style: none; margin: 0; padding: 0; display: grid; gap: 7px; }\n#sub-protocol-inst_5 ul.check li { position: relative; padding-inline-start: 24px; font-size: 14.5px; }\n#sub-protocol-inst_5 ul.check li::before { content: \"✓\"; position: absolute; inset-inline-start: 0; top: 0; color: var(--c); font-weight: 800; font-size: 15px; }\n#sub-protocol-inst_5 .or-box { display: grid; gap: 8px; }\n#sub-protocol-inst_5 .opt { border: 1.5px dashed var(--c); border-radius: 10px; padding: 10px 12px; display: grid; gap: 4px; font-size: 14px; background: rgba(255,255,255,0.6); }\n#sub-protocol-inst_5 .opt .tag { font-weight: 800; color: var(--c); font-size: 13px; }\n#sub-protocol-inst_5 .or { font-weight: 800; text-align: center; color: var(--muted); font-size: 13px; }\n#sub-protocol-inst_5 .formula { background: var(--tint); border-radius: 10px; padding: 10px 14px; font-weight: 700; font-size: 15px; line-height: 1.6; }\n#sub-protocol-inst_5 .formula .op { color: var(--c); }\n#sub-protocol-inst_5 .mult { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n#sub-protocol-inst_5 .mult div { border-radius: 10px; padding: 10px 12px; background: var(--cs); display: grid; gap: 2px; }\n#sub-protocol-inst_5 .mult .num { font-size: 24px; color: var(--c); line-height: 1.1; }\n#sub-protocol-inst_5 .mult small { font-size: 13px; color: var(--fg); }\n#sub-protocol-inst_5 .example { border-inline-start: 4px solid var(--c); background: var(--cs); border-radius: 0 10px 10px 0; padding: 8px 12px; font-size: 14px; display: grid; gap: 3px; }\n#sub-protocol-inst_5 .example .t { font-weight: 700; color: var(--c); font-size: 13px; }\n#sub-protocol-inst_5 .note { display: flex; gap: 10px; align-items: flex-start; background: var(--warn-soft); color: var(--fg); border-radius: 10px; padding: 10px 12px; font-size: 14px; }\n#sub-protocol-inst_5 .note::before { content: \"!\"; flex: 0 0 20px; height: 20px; border-radius: 50%; background: var(--warn); color: #fff; font-weight: 800; display: grid; place-items: center; font-size: 13px; margin-top: 2px; }\n/* companies finder */\n#sub-protocol-inst_5 .finder { display: grid; gap: 10px; padding: 14px 16px; border-top: 1px solid var(--line); }\n#sub-protocol-inst_5 .finder label { font-weight: 700; font-size: 14px; }\n#sub-protocol-inst_5 .finder input { width: 100%; padding: 9px 12px; border-radius: 10px; border: 1.5px solid var(--line); background: #fff; font: inherit; font-size: 14px; }\n#sub-protocol-inst_5 .cats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n@media (max-width: 600px) { #sub-protocol-inst_5 .cats { grid-template-columns: 1fr; } }\n#sub-protocol-inst_5 .cat { border-radius: 12px; border: 1px solid var(--line); overflow: hidden; background: #fff; }\n#sub-protocol-inst_5 .cat h4 { margin: 0; font-size: 15px; padding: 10px 12px; display: flex; justify-content: space-between; align-items: center; }\n#sub-protocol-inst_5 .cat.a h4 { background: var(--med); color: #fff; }\n#sub-protocol-inst_5 .cat.b h4 { background: var(--cs); color: var(--med); }\n#sub-protocol-inst_5 .cat ul { list-style: none; margin: 0; padding: 0; max-height: 280px; overflow-y: auto; }\n#sub-protocol-inst_5 .cat li { padding: 7px 12px; border-top: 1px solid var(--line); display: flex; justify-content: space-between; font-size: 13.5px; }\n#sub-protocol-inst_5 .cat li.hit { background: var(--warn-soft); font-weight: bold; }\n#sub-protocol-inst_5 .empty { color: var(--muted); font-size: 14px; padding: 12px; text-align: center; }\n/* table */\n#sub-protocol-inst_5 .tbl { overflow-x: auto; border: 1px solid var(--line); border-radius: 12px; background: #fff; margin-top: 6px; }\n#sub-protocol-inst_5 table { border-collapse: collapse; width: 100%; font-size: 14px; }\n#sub-protocol-inst_5 th, #sub-protocol-inst_5 td { padding: 9px 12px; text-align: right; border-top: 1px solid var(--line); }\n#sub-protocol-inst_5 thead th { border-top: 0; font-weight: 800; font-size: 14.5px; background: var(--tint); }\n#sub-protocol-inst_5 thead th:nth-child(2) { color: var(--drv); }\n#sub-protocol-inst_5 thead th:nth-child(3) { color: var(--med); }\n#sub-protocol-inst_5 tbody th { font-weight: 700; color: var(--muted); white-space: nowrap; }\n#sub-protocol-inst_5 td.diff { background: var(--warn-soft); }\n/* dialogue */\n#sub-protocol-inst_5 .chat { display: grid; gap: 10px; background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 16px; }\n#sub-protocol-inst_5 .msg { max-width: 85%; padding: 10px 14px; border-radius: 14px; font-size: 14.5px; line-height: 1.5; }\n#sub-protocol-inst_5 .msg b { display: block; font-size: 12px; color: var(--muted); margin-bottom: 2px; }\n#sub-protocol-inst_5 .msg.c { background: var(--tint); justify-self: start; }\n#sub-protocol-inst_5 .msg.s { background: var(--drv-soft); justify-self: end; }\n/* say / don't */\n#sub-protocol-inst_5 .say { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 10px; }\n@media (max-width: 600px) { #sub-protocol-inst_5 .say { grid-template-columns: 1fr; } }\n#sub-protocol-inst_5 .say > div { border-radius: 12px; padding: 14px; display: grid; gap: 6px; }\n#sub-protocol-inst_5 .say .yes { background: var(--ok-soft); border: 1px solid rgba(28,124,69,0.2); }\n#sub-protocol-inst_5 .say .nope { background: var(--no-soft); border: 1px solid rgba(179,38,30,0.2); }\n#sub-protocol-inst_5 .say h3 { font-size: 16px; margin: 0; }\n#sub-protocol-inst_5 .say .yes h3 { color: var(--ok); }\n#sub-protocol-inst_5 .say .nope h3 { color: var(--no); }\n#sub-protocol-inst_5 .say ul { margin: 0; padding-inline-start: 18px; display: grid; gap: 5px; font-size: 14px; }\n/* red lines */\n#sub-protocol-inst_5 .red { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }\n#sub-protocol-inst_5 .red li { background: var(--surface); border: 1px solid var(--line); border-inline-start: 4px solid var(--no); border-radius: 10px; padding: 10px 14px; font-size: 14px; }\n/* questions / test */\n#sub-protocol-inst_5 .qs { display: grid; gap: 8px; }\n#sub-protocol-inst_5 details { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }\n#sub-protocol-inst_5 summary { cursor: pointer; list-style: none; padding: 12px 14px; font-weight: 700; display: flex; gap: 10px; align-items: center; font-size: 14px; user-select: none; }\n#sub-protocol-inst_5 summary::-webkit-details-marker { display: none; }\n#sub-protocol-inst_5 summary .qn { flex: 0 0 24px; height: 24px; border-radius: 50%; background: var(--tint); color: var(--blue); font-weight: 800; display: grid; place-items: center; font-size: 13px; }\n#sub-protocol-inst_5 summary .hint { margin-inline-start: auto; flex: 0 0 auto; font-size: 12px; color: var(--blue); background: var(--tint); padding: 3px 10px; border-radius: 999px; }\n#sub-protocol-inst_5 details[open] summary .hint { visibility: hidden; }\n#sub-protocol-inst_5 details .ans { padding: 0 14px 12px 48px; color: var(--ok); font-weight: 700; font-size: 14px; margin: 0; }\n/* takeaway */\n#sub-protocol-inst_5 .take { background: var(--head-bg); color: #fff; border-radius: 14px; padding: 18px 20px; display: grid; gap: 8px; }\n#sub-protocol-inst_5 .take h2 { color: #fff; font-size: 18px; margin: 0; border: 0; padding: 0; }\n#sub-protocol-inst_5 .take p { font-size: 15px; line-height: 1.6; margin: 0; }\n#sub-protocol-inst_5 .take .next { font-weight: 700; background: rgba(255,255,255,0.15); border-radius: 8px; padding: 8px 12px; font-size: 14px; }\n</style>\n<div style=\"background: linear-gradient(135deg, #001780 0%, #225FAC 100%); color: #fff; padding: 22px 20px; border-radius: 14px; margin-bottom: 20px; text-align: center;\">\n<div data-c=\"97\" style=\"display: inline-block; background: rgba(255,255,255,0.18); padding: 4px 14px; border-radius: 999px; font-size: 13px; font-weight: bold; margin-bottom: 8px;\">أكاديمية راية للتجزئة · مهارة في كبسولة</div>\n<h2 data-c=\"98\" style=\"font-size: 24px; font-weight: 900; margin: 0 0 8px 0; color: #fff;\">العميل اللي مش مؤمن عليه… ليه طريق للتقسيط</h2>\n<p style=\"font-size: 15px; opacity: 0.92; max-width: 650px; margin: 0 auto; line-height: 1.6;\">\n      برنامجين تمويل لازم تكون حافظهم: سواقين أوبر وديدي وإن درايفر، وأصحاب الكروت الطبية من شركات التأمين.\n    </p>\n</div>\n<main>\n<div class=\"wrap\">\n<section id=\"idea\">\n<h2 data-c=\"99\">المهارة في جملة</h2>\n<div class=\"idea\">\n<p class=\"big\">لما العميل يقولك «أنا مش متأمن عليا»، ما تقفلش الكلام. اسأله بيشتغل إيه، ولو سواق على تطبيق أو معاه كارت طبي، اطلب منه الورق الصح من أول مرة.</p>\n<div class=\"why\">\n<div><b>ليه مهمة للعميل؟</b>بياخد الجهاز اللي محتاجه بالتقسيط، ومن غير ما يرجع البيت يجيب ورق ناقص.</div>\n<div><b>ليه مهمة ليك؟</b>بيعة كانت هتضيع بتتقفل، والملف بيعدّي من أول مرة من غير رفض أو تأخير.</div>\n</div>\n</div>\n</section>\n<section id=\"drivers\">\n<h2 data-c=\"100\">البرنامج الأول</h2>\n<article class=\"prog drv\">\n<div class=\"prog-head\">\n<h3 data-c=\"101\">سواقين أوبر وديدي وإن درايفر</h3>\n<p class=\"sub\">العميل بيشتغل على عربيته في تطبيق توصيل ركاب</p>\n</div>\n<div class=\"prog-body\">\n<div class=\"row\"><div class=\"k\">السن</div><div class=\"v\">\n<div class=\"range\"><span class=\"num\">30</span><span class=\"to\">سنة لحد</span><span class=\"num\">60</span><span class=\"to\">سنة</span></div>\n</div></div>\n<div class=\"row\"><div class=\"k\">مدة التقسيط</div><div class=\"v\">\n<div class=\"range\"><span class=\"num\">10</span><span class=\"to\">شهور لحد</span><span class=\"num\">36</span><span class=\"to\">شهر</span></div>\n</div></div>\n<div class=\"row\"><div class=\"k\">إثبات الدخل</div><div class=\"v\">\n<p>اختار <b>واحد بس</b> من الاتنين:</p>\n<div class=\"or-box\">\n<div class=\"opt\"><span class=\"tag\">الطريقة الأولى</span>كشف صافي أرباح آخر 6 شهور من التطبيق + فيديو من التطبيق يظهر فيه بيانات العميل</div>\n<div class=\"or\">أو</div>\n<div class=\"opt\"><span class=\"tag\">الطريقة التانية</span>كشف حساب بنكي آخر 6 شهور فيه تحويلات الدخل، ويعتمده قسم الـFRMU</div>\n</div>\n</div></div>\n<div class=\"row\"><div class=\"k\">ورق لازم في كل الحالات</div><div class=\"v\">\n<ul class=\"check\">\n<li>بطاقة رقم قومي سارية</li>\n<li>العميل هو <b>مالك العربية</b> وصاحب الرخصة</li>\n<li>رخصة العربية سارية <b>6 شهور على الأقل</b> وتغطي مدة التقسيط كلها (يعتمدها الـFRMU)</li>\n<li>موديل العربية <b>ما يزيدش عن 10 سنين</b></li>\n</ul>\n</div></div>\n<div class=\"row\"><div class=\"k\">حساب الدخل</div><div class=\"v\">\n<p>متوسط صافي الإيرادات المحولة في آخر 6 شهور.</p>\n<div class=\"example\" data-c=\"102\"><span class=\"t\">لو العميل كمان بياخد مرتب</span>الدخل = متوسط المرتب + متوسط دخل التطبيقات</div>\n</div></div>\n<div class=\"row\"><div class=\"k\">الشغل والتحقق</div><div class=\"v\">\n<ul class=\"check\">\n<li>شغال على التطبيق من <b>6 شهور على الأقل</b>، وده بيبان من كشف التطبيق أو فيديو يوضح تاريخ إنشاء الحساب</li>\n<li><b>زيارة منزلية إلزامية</b> لحد ما نظام الـDVS الجديد يتطبق</li>\n</ul>\n</div></div>\n<div class=\"row\"><div class=\"k\">الآي سكور</div><div class=\"v\">\n<p>نفس معايير التاريخ الائتماني العادية، داخليًا وخارجيًا.</p>\n</div></div>\n<div class=\"row\"><div class=\"k\">مضاعف الائتمان</div><div class=\"v\">\n<div class=\"formula\">(متوسط الدخل <span class=\"op\">÷ 2</span>) <span class=\"op\">−</span> التزامات الآي سكور <span class=\"op\">× 8</span></div>\n<div class=\"mult\">\n<div><span class=\"num\">×8</span><small>عنده سجل آي سكور أكتر من 6 شهور</small></div>\n<div><span class=\"num\">×4</span><small>مالوش آي سكور، أو سجله أقل من 6 شهور</small></div>\n</div>\n<div class=\"example\"><span class=\"t\">مثال للتوضيح</span>متوسط دخله 14,000 ← النص 7,000 ← ناقص التزامات 2,000 = 5,000 ← × 8 = <b>40,000 جنيه</b></div>\n<p class=\"note\">الحد الأقصى لعبء الدين (DBR) هو 50% من الدخل في كل الحالات.</p>\n</div></div>\n</div>\n</article>\n</section>\n<section id=\"medical\">\n<h2 data-c=\"103\">البرنامج التاني</h2>\n<article class=\"prog med\">\n<div class=\"prog-head\">\n<h3 data-c=\"104\">عملاء الكارت الطبي (شركات التأمين)</h3>\n<p class=\"sub\">العميل مش مؤمن عليه اجتماعيًا، بس شغله عامله كارت طبي من شركة تأمين</p>\n</div>\n<div class=\"prog-body\">\n<div class=\"row\"><div class=\"k\">السن</div><div class=\"v\">\n<div class=\"range\"><span class=\"num\">25</span><span class=\"to\">سنة لحد</span><span class=\"num\">60</span><span class=\"to\">سنة</span></div>\n</div></div>\n<div class=\"row\"><div class=\"k\">مدة التقسيط</div><div class=\"v\">\n<div class=\"range\"><span class=\"num\">10</span><span class=\"to\">شهور لحد</span><span class=\"num\">36</span><span class=\"to\">شهر</span></div>\n</div></div>\n<div class=\"row\"><div class=\"k\">الورق المطلوب</div><div class=\"v\">\n<ul class=\"check\">\n<li>بطاقة هوية سارية</li>\n<li>كارت طبي صادر من <b>6 شهور على الأقل</b></li>\n<li>فيديو من تطبيق شركة التأمين على الموبايل يظهر فيه بيانات العميل</li>\n</ul>\n</div></div>\n<div class=\"row\"><div class=\"k\">حساب الدخل</div><div class=\"v\">\n<p>على أساس <b>برنامج الدخل الافتراضي</b>.</p>\n</div></div>\n<div class=\"row\"><div class=\"k\">مدة الخدمة</div><div class=\"v\">\n<p>شغال من 6 شهور على الأقل.</p>\n<p class=\"note\">لو الكارت الطبي أحدث من 6 شهور، العميل لازم يجيب مستند زيادة يثبت مدة خدمته.</p>\n</div></div>\n<div class=\"row\"><div class=\"k\">الآي سكور</div><div class=\"v\">\n<p>سجل <b>نضيف</b> داخليًا وخارجيًا.</p>\n</div></div>\n<div class=\"row\"><div class=\"k\">مضاعف الائتمان</div><div class=\"v\">\n<div class=\"mult\">\n<div><span class=\"num\">×8</span><small>شركات الفئة (أ)</small></div>\n<div><span class=\"num\">×4</span><small>شركات الفئة (ب)</small></div>\n</div>\n<p class=\"note\">الحد الأقصى لعبء الدين (DBR) هو 50% في الفئتين.</p>\n</div></div>\n</div>\n<div class=\"finder\">\n<label data-c=\"105\" for=\"q\">شركة التأمين في أنهي فئة؟ اكتب اسمها من على الكارت</label>\n<input autocomplete=\"off\" id=\"uninsured_company_q\" placeholder=\"مثلًا: أكسا أو AXA\" type=\"search\"/>\n<p class=\"note\">خلي بالك من الأسماء اللي شبه بعض: «الدلتا للتأمين» فئة (أ) لكن «الدلتا لتأمينات الحياة» فئة (ب). ونفس الكلام في «قناة السويس». و«مصر للتأمين» و«مصر لتأمينات الحياة» (أ) لكن «مصر للتأمين التكافلي» (ب).</p>\n<div class=\"cats\">\n<div class=\"cat a\"><h4 data-c=\"106\"><span>الفئة (أ)</span><span>×8</span></h4><ul id=\"listA\"><li><span>ميتلايف مصر</span><small>MetLife Egypt</small></li><li><span>أروب للتأمين</span><small>Arope Insurance</small></li><li><span>المهندس للتأمين</span><small>Mohandes Insurance</small></li><li><span>الدلتا للتأمين</span><small>Delta Insurance</small></li><li><span>قناة السويس للتأمين</span><small>Suez Canal Insurance</small></li><li><span>رويال للتأمين</span><small>Royal Insurance</small></li><li><span>أكسا مصر</span><small>AXA Egypt</small></li><li><span>المصرية للتأمين التكافلي</span><small>Egyptian Takaful Insurance</small></li><li><span>بوبا مصر</span><small>Bupa Egypt</small></li><li><span>مصر للتأمين</span><small>Misr Insurance</small></li><li><span>أليانز مصر</span><small>Allianz Egypt</small></li><li><span>جي آي جي مصر</span><small>GIG Egypt</small></li><li><span>أورينت للتأمين التكافلي (نكست كير)</span><small>Orient Takaful Insurance (Next Care)</small></li><li><span>مصر لتأمينات الحياة</span><small>Misr Life Insurance</small></li></ul></div>\n<div class=\"cat b\"><h4 data-c=\"107\"><span>الفئة (ب)</span><span>×4</span></h4><ul id=\"listB\"><li><span>جلوب ميد مصر</span><small>Globe Med Egypt</small></li><li><span>إسكان للتأمين</span><small>Iskan Insurance</small></li><li><span>طوكيو مارين مصر</span><small>Tokio Marine Egypt</small></li><li><span>الدلتا لتأمينات الحياة</span><small>Delta Life Assurance</small></li><li><span>قناة السويس لتأمينات الحياة</span><small>Suez Canal Life Insurance</small></li><li><span>إيه آي جي مصر</span><small>AIG Egypt</small></li><li><span>ثروة للتأمين</span><small>Sarwa Insurance</small></li><li><span>تشب للتأمين</span><small>Chubb Insurance</small></li><li><span>المصرية السعودية للتأمين</span><small>Egyptian Saudi Insurance House</small></li><li><span>صندوق معاشات المقاولون العرب</span><small>Arab Contractors Pension Fund</small></li><li><span>مصر للتأمين التكافلي</span><small>Misr Takaful Insurance</small></li><li><span>إيجي كير</span><small>Egy Care</small></li></ul></div>\n</div>\n<p class=\"empty\" hidden=\"\" id=\"uninsured_company_none\">الشركة دي مش في القايمة. ارجع لمديرك أو لقسم الائتمان قبل ما توعد العميل بحاجة.</p>\n</div>\n</article>\n</section>\n<section id=\"compare\">\n<h2 data-c=\"108\">مقارنة سريعة</h2>\n<p class=\"sub\">الخانات الملونة هي اللي بيحصل فيها لخبطة.</p>\n<div class=\"tbl\">\n<table>\n<thead><tr><th>البند</th><th>السواقين</th><th>الكارت الطبي</th></tr></thead>\n<tbody>\n<tr><th>السن</th><td class=\"diff\">30 – 60</td><td class=\"diff\">25 – 60</td></tr>\n<tr><th>مدة التقسيط</th><td>10 – 36 شهر</td><td>10 – 36 شهر</td></tr>\n<tr><th>إثبات الدخل</th><td>كشف التطبيق + فيديو، أو كشف بنكي</td><td>كارت طبي + فيديو من تطبيق التأمين</td></tr>\n<tr><th>حساب الدخل</th><td class=\"diff\">متوسط صافي آخر 6 شهور</td><td class=\"diff\">برنامج الدخل الافتراضي</td></tr>\n<tr><th>مدة الشغل</th><td>6 شهور على التطبيق</td><td>6 شهور خدمة</td></tr>\n<tr><th>زيارة منزلية</th><td class=\"diff\">إلزامية</td><td class=\"diff\">مش مذكورة</td></tr>\n<tr><th>الآي سكور</th><td class=\"diff\">المعايير العادية</td><td class=\"diff\">سجل نضيف</td></tr>\n<tr><th>المضاعف</th><td class=\"diff\">×8 بآي سكور، ×4 من غيره</td><td class=\"diff\">×8 فئة (أ)، ×4 فئة (ب)</td></tr>\n<tr><th>عبء الدين</th><td>50% بحد أقصى</td><td>50% بحد أقصى</td></tr>\n</tbody>\n</table>\n</div>\n</section>\n<section id=\"floor\">\n<h2 data-c=\"109\">موقف من الفرع</h2>\n<div class=\"chat\">\n<div class=\"msg c\"><b>العميل</b>عاوز التلاجة دي قسط، بس أنا مش متأمن عليا.</div>\n<div class=\"msg s\"><b>أنت</b>ولا يهمك، عندنا برامج لده. حضرتك بتشتغل إيه؟</div>\n<div class=\"msg c\"><b>العميل</b>سواق على أوبر بعربيتي.</div>\n<div class=\"msg s\"><b>أنت</b>تمام. العربية والرخصة باسم حضرتك؟ وشغال على التطبيق بقالك قد إيه؟</div>\n<div class=\"msg c\"><b>العميل</b>باسمي، وبقالي سنة تقريبًا.</div>\n<div class=\"msg s\"><b>أنت</b>ممتاز. هنحتاج بطاقتك، ورخصة العربية، وكشف أرباح آخر 6 شهور من التطبيق مع فيديو يبين بياناتك. ولو تحب، كشف حساب البنك بتاع آخر 6 شهور ينفع بدل كشف التطبيق.</div>\n</div>\n<div class=\"say\">\n<div class=\"yes\"><h3 data-c=\"110\">قول</h3><ul>\n<li>«حضرتك بتشتغل إيه؟»</li>\n<li>«العربية والرخصة باسمك؟»</li>\n<li>«الكارت الطبي ده طالع من إمتى؟»</li>\n<li>«ده الورق اللي هنحتاجه، عشان الملف يعدي من أول مرة»</li>\n</ul></div>\n<div class=\"nope\"><h3 data-c=\"111\">ما تقولش</h3><ul>\n<li>«مفيش تقسيط من غير تأمينات»</li>\n<li>«هات أي ورق وإحنا نشوف»</li>\n<li>«مضمونة، هتتقبل أكيد»</li>\n<li>«اتعملك رفض عشان كذا» (سبب الرفض ما بيتقالش)</li>\n</ul></div>\n</div>\n</section>\n<section id=\"redlines\">\n<h2 data-c=\"112\">نقاط لازم تاخد بالك منها</h2>\n<ul class=\"red\">\n<li>السواق لازم يكون <b>هو</b> مالك العربية. لو العربية باسم حد تاني، ما ينفعش على البرنامج ده.</li>\n<li>موديل العربية أقدم من 10 سنين؟ ما ينفعش.</li>\n<li>الرخصة لازم تغطي <b>مدة التقسيط كلها</b>، مش بس 6 شهور.</li>\n<li>الكارت الطبي أحدث من 6 شهور؟ اطلب مستند يثبت مدة الخدمة قبل ما تبدأ.</li>\n<li>دايمًا اتأكد من فئة شركة التأمين من القايمة، لأنها بتفرق في المضاعف.</li>\n<li>ما تديش العميل وعد بالقبول، وما تقولوش سبب الرفض لو حصل.</li>\n</ul>\n</section>\n<section id=\"check\">\n<h2 data-c=\"113\">اختبر نفسك قبل الامتحان</h2>\n<p class=\"sub\">فكر في الإجابة، وبعدين دوس على السؤال تشوفها.</p>\n<div class=\"qs\">\n<details><summary><span class=\"qn\">1</span><span>سواق على إن درايفر عنده 28 سنة. ينفع على برنامج السواقين؟</span><span class=\"hint\">الإجابة</span></summary><p class=\"ans\">لأ، السن في برنامج السواقين من 30 لـ 60 سنة.</p></details>\n<details><summary><span class=\"qn\">2</span><span>عميل معاه كارت طبي من «بوبا مصر». المضاعف كام؟</span><span class=\"hint\">الإجابة</span></summary><p class=\"ans\">×8، لأن بوبا مصر فئة (أ).</p></details>\n<details><summary><span class=\"qn\">3</span><span>سواق أوبر ما عندوش كشف أرباح من التطبيق. فيه بديل؟</span><span class=\"hint\">الإجابة</span></summary><p class=\"ans\">أيوه، كشف حساب بنكي آخر 6 شهور فيه تحويلات الدخل، ويعتمده الـFRMU.</p></details>\n<details><summary><span class=\"qn\">4</span><span>الكارت الطبي طالع من 4 شهور بس. نعمل إيه؟</span><span class=\"hint\">الإجابة</span></summary><p class=\"ans\">نطلب من العميل مستند إضافي يثبت إن مدة خدمته 6 شهور على الأقل.</p></details>\n<details><summary><span class=\"qn\">5</span><span>سواق ديدي ما عندوش أي سجل آي سكور. المضاعف كام؟</span><span class=\"hint\">الإجابة</span></summary><p class=\"ans\" data-c=\"114\">×4، وعبء الدين ما يزيدش عن 50%.</p></details>\n<details><summary><span class=\"qn\">6</span><span>عربية السواق موديل 2014. ينفع؟</span><span class=\"hint\">الإجابة</span></summary><p class=\"ans\">لأ، موديل العربية لازم ما يزيدش عن 10 سنين.</p></details>\n</div>\n</section>\n<section class=\"take\">\n<h2 data-c=\"115\">الخلاصة</h2>\n<p>اسأل العميل بيشتغل إيه قبل ما تقوله لأ. السواق ليه برنامج، وصاحب الكارت الطبي ليه برنامج، والورق الصح من أول مرة بيقفل البيعة.</p>\n<p class=\"next\">ذاكر الكبسولة كويس، وبعدها امتحان الكبسولة.</p>\n</section>\n</div>\n</main>\n</div>\n</div>\n</div>\n</div>\n","words":2574},{"id":"sales-procedures","title":"إجراءات البيع","group":"القواعد","icon":"clipboard","html":"\n<div class=\"section-body\">\n<div class=\"main-protocol-tab-content\" id=\"main-protocol-sales-procedures\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; margin-bottom: 16px;\">\n<div class=\"guest-step active-step\" data-c=\"116\" onclick=\"showSubProtocolTab('sales_completion', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول إتمام البيع</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('home_delivery', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول التوصيل للمنزل</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('call_center', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول طلبات الكول سنتر</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('shipping', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول الشحن</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('discount', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول طلبات الخصم الاستثنائي</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('other_branch_delivery', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول تسليم طلب من فرع تاني</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('large_appliance_exchange', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول استبدال الأجهزة الكبيرة</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('small_appliance_returns', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول مرتجعات الأجهزة الصغيرة\n                          واسترداد الفلوس</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('large_appliance_returns', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول الإرجاع والاسترداد للأجهزة\n                          الكبيرة</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('taqsiti_system', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول التقسيط بنظام \"تقسيطى\"</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-sales_completion\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"117\" style=\"text-align: center; font-size: 22px; margin-bottom: 8px;\">بروتوكول إتمام البيع</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                            إزاي تقفل البيعة بأسلوب \"صاحب البيت\"</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            إنت كاستشاري بيع في راية، إتمام البيعة مش مجرد فاتورة بتطبعها، دي رحلة بتبدأ بابتسامة\n                            وبتنتهي بعميل ولاؤه ليك وللفرع.<br/>\n<strong>دي الخطوات الرسمية الثابتة عشان نقفل البيعة صح 100%:</strong>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            1- الاستقبال وكشف الاحتياج الترحيب</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>زي ما متعودين، استقبل ضيفك بابتسامة عشان تفتح\n                                الكلام.</strong></li>\n<li><span class=\"bullet\"></span><strong>ابدأ اطرح أسئلة بسيطة وذكية عشان تفهم احتياجاته\n                                الفعلية والسبب الأساسي للشراء.</strong></li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            2- الاختيار والعرض البيع</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>زي ما بنعمل دايماً ساعد العميل يختار المنتج الأنسب\n                                ليه حسب احتياجاته</strong></li>\n<li><span class=\"bullet\"></span><strong><span style=\"color:#003399;\">دورك كاستشاري:</span>\n                                اقترح بدائل مناسبة، أو منتجات إضافية إكسسوارات/أجهزة تكميلية مع شرح مميزاتها\n                                بوضوح.</strong></li>\n</div>\n<div data-c=\"118\" style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            3- المراجعة والتأكيد قبل السيستم</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>اتأكد إن العميل استقر على المنتج النهائي ومقتنع بيه\n                                100%.</strong></li>\n<li><span class=\"bullet\"></span><strong><span style=\"color:#003399;\">خطوة إلزامية:</span>\n                                راجع مع العميل تفاصيل الطلب كاملة الموديل - الكمية - السعر النهائي قبل ما تفتح\n                                السيستم.</strong></li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            4- شغل السيستم: إنشاء الطلب على الداينمكس</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; font-weight:bold; margin-bottom:10px;\">افتح نظام Dynamics\n                              وابدأ إدخال البيانات بالترتيب الآتي:</div>\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">بيانات المنتج:</div>\n<div class=\"rule-list\" style=\"margin-bottom:10px;\">\n<li><span class=\"bullet\"></span>إدخال كود المنتج Item Code والكمية. <strong><span style=\"color:#003399;\">ملاحظة:</span> تقدر تضيف أكتر من منتج في نفس الطلب.</strong>\n</li>\n<li><span class=\"bullet\"></span>إدخال السيريال نمبر Serial Number: إلزامي للأجهزة اللي\n                                ليها سيريال زي الموبايلات.</li>\n<li><span class=\"bullet\"></span>إضافة تعليق Comment: خطوة اختيارية لو محتاج تسجل ملاحظة\n                                معينة.</li>\n</div>\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">بيانات العميل البروفايل:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>ابحث أولاً باستخدام رقم الموبايل.</li>\n<li data-c=\"119\"><span class=\"bullet\"></span>لو العميل مسجل قبل كده ← البيانات هتظهر تلقائياً.</li>\n<li><span class=\"bullet\"></span>لو عميل جديد ← يتم إنشاء حساب جديد فوراً وتسجيل الاسم +\n                                العنوان + رقم الموبايل.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            5- مرحلة الدفع Tender</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; margin-bottom:10px;\">اختار مع العميل طريقة الدفع الأنسب ليه\n                              من الخيارات المتاحة:</div>\n<div style=\"display:flex; justify-content:center; gap:12px; flex-wrap:wrap; margin-bottom:10px; font-weight:bold; color:#003399; background:#f0f4ff; padding:10px; border-radius:8px;\">\n<span>• كاش</span>\n<span>• بطاقة ائتمان</span>\n<span>• بطاقة خصم مباشر</span>\n<span>• تقسيطي</span>\n<span>• شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan)</span>\n</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة جزء كاش + جزء\n                                تقسيط أو فيزا.</li>\n<li><span class=\"bullet\"></span>بمجرد إتمام الدفع، النظام بيصدر الفاتورة تلقائياً.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            6- التسليم وما بعد البيع الضمان والتقييم</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>اطبع الفاتورة وسلمها للعميل في إيده مع المنتج</li>\n<li><span class=\"bullet\"></span>اشكره بلباقة على اختياره لـ \"راية\".</li>\n<li data-c=\"120\"><span class=\"bullet\"></span><strong><span style=\"color:#003399;\">شرح الضمان</span> خطوة\n                                هامة جداً: وضح للعميل الآتي بالتفصيل:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>مين الجهة المسئولة عن الضمان راية ولا شركة تانية؟.</li>\n<li>عناوين فروع الصيانة الخاصة بالمنتج.</li>\n<li>تفعيل ضمان الـ QR Code نبه العميل على ضرورة مسح الـ QR Code لتفعيل الضمان لمنتجات\n                                  البراندات دي: De'Longhi - Kenwood - Philips - Sary - Braun.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            7- التسليم وما بعد البيع الضمان والتقييم</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-bottom:5px;\">رسالة التقييم: NPS/CSAT\n                            </div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>بلغ العميل إنه هيستقبل رسالة نصية SMS لتقييم الخدمة، وأكد\n                                له إن رأيه مهم جداً بالنسبة لينا عشان نحسن مستوانا.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            8- التوديع ختام الرحلة</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>راجع سريعاً في سرك إنك عملت كل الخطوات بنجاح</li>\n<li><span class=\"bullet\"></span>ودع العميل بشكل لبق واحترافي زي ما انت بتعمل يا بطل كل مرة ،\n                              وقوله منتظرين زيارتك مرة تانية.</li>\n</div>\n<div class=\"dont-box\" style=\"margin-top:20px; background:#fef9ee; border:1px solid #b8891a; color:#92400e; padding:15px; border-radius:8px;\">\n<div data-c=\"121\" style=\"font-weight:bold; font-size:15px; margin-bottom:8px; color:#b8891a;\">💡 القاعدة\n                              الذهبية لصاحب البيت:</div>\n                            \"النظام في إدخال البيانات مش روتين، ده حماية ليك وللعميل.. والبيعة مبتنتهيش عند الدفع،\n                            بتنتهي لما العميل يفهم ضمانه ويخرج مبسوط!\"\n                          </div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-home_delivery\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"122\" style=\"text-align: center; font-size: 22px; margin-bottom: 8px;\">بروتوكول التوصيل للمنزل\n                          </div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                            من الفرع لحد باب البيت</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            لما العميل يختار أجهزة محتاجة توصيل زي الشاشات TV، الأجهزة الكبيرة HA/MDA، أو حتى الأجهزة\n                            الصغيرة SDA دورك كـ \"صاحب بيت\" إنك تضمن وصول أجهزته بأمان وبدون أي خطأ في البيانات.<br/>\n<strong>دي الخطوات الرسمية:</strong>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            1- الاستقبال وتأكيد الاختيار</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>استقبل ضيفك بود وافهم احتياجاته بأسئلة بسيطة.</li>\n<li><span class=\"bullet\"></span>ساعده يختار الأنسب، واقترح عليه بدائل أو منتجات إضافية\n                              Up-selling</li>\n<li><span class=\"bullet\"></span>بعد الاستقرار النهائي، أكد معاه تفاصيل المنتج بوضوح الموديل\n                              - الكمية - السعر.</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            2- شغل السيستم: إنشاء الطلب على الداينمكس</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">بيانات المنتج:</div>\n<div class=\"rule-list\" style=\"margin-bottom:10px;\">\n<li><span class=\"bullet\"></span>إدخال كود المنتج Item Code والكمية متاح إضافة أكثر من\n                                منتج.</li>\n<li data-c=\"123\"><span class=\"bullet\"></span>إدخال السيريال نمبر Serial Number للأجهزة اللي ليها\n                                سيريال.</li>\n<li><span class=\"bullet\"></span>إضافة تعليق Comment لو في أي ملاحظة اختيارية.</li>\n</div>\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">بيانات العميل:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>ابحث برقم الموبايل لو مسجل، بياناته هتظهر فوراً.</li>\n<li><span class=\"bullet\"></span>لو عميل جديد: اختار Add Customer ▶ Create New\n                                Customer وسجل: الاسم - العنوان - رقم الموبايل.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            3- ضبط البوصلة: تحديد الشحن والتوصيل</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>مراجعة دقيقة: راجع مع العميل عنوان التوصيل ورقم الموبايل\n                              حرفاً حرفاً لضمان دقة التسليم.</li>\n<li data-c=\"124\"><span class=\"bullet\"></span><strong>على السيستم:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>اضغط على Order → Shipping Product → Change Origin.</li>\n<li>ثم اختار \"المخزن الرئيسي\".</li>\n<li>حدد \"تاريخ التوصيل\" المطلوب والمناسب للعميل.</li>\n</ul>\n</li>\n<li><span class=\"bullet\"></span><span style=\"color:#003399; font-weight:bold;\">المراجعة\n                                النهائية:</span> أكد مع العميل للمرة الأخيرة الموديل، الكمية، السعر، عنوان وتاريخ\n                              التوصيل.</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            4- مرحلة الدفع Tender</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; margin-bottom:10px;\">اختار مع العميل طريقة الدفع الأنسب ليه\n                              من الخيارات المتاحة:</div>\n<div style=\"display:flex; justify-content:center; gap:12px; flex-wrap:wrap; margin-bottom:10px; font-weight:bold; color:#003399; background:#f0f4ff; padding:10px; border-radius:8px;\">\n<span>• كاش</span>\n<span>• بطاقة ائتمان</span>\n<span>• بطاقة خصم مباشر</span>\n<span>• تقسيطي</span>\n<span>• شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan)</span>\n</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة جزء كاش + جزء\n                                تقسيط أو فيزا.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            5- إذن التسليم Delivery Note</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; font-weight:bold; margin-bottom:10px;\">بمجرد إتمام الدفع،\n                              السيستم بيصدر \"إذن التسليم\" تلقائياً.</div>\n<div class=\"rule-list\" style=\"margin-bottom:10px;\">\n<li data-c=\"125\"><span class=\"bullet\"></span><span style=\"color:#003399; font-weight:bold;\">محتويات\n                                  الإذن:</span> رقم العملية - Transaction Number - اسم الفرع - كود الموظف - اسم العميل\n                                ورقم موبايله - تاريخ التوصيل - رقم الإيصال - كود المنتج والسيريال إن وجد.</li>\n<li><span class=\"bullet\"></span><span style=\"color:#003399; font-weight:bold;\">التسليم:</span> اطبع الإذن وسلمه للعميل في\n                                إيده، وأكد عليه إن \"المندوب هيكلمه يوم التوصيل المحدد للتنسيق\".</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            6- الضمان ورسالة التقييم CSAT-NPS</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>وضح مين المسئول عن الضمان راية ولا شركة تانية؟ وإديله عناوين\n                              فروع الصيانة.</li>\n<li><span class=\"bullet\"></span>تفعيل الـ QR Code: نبه العميل إنه لازم يمسح الكيو آر كود\n                              لتفعيل الضمان للبراندات دي: De'Longhi - Kenwood - Philips - Sary - Braun.</li>\n<li><span class=\"bullet\"></span>بلغ العميل إنه هيستقبل رسالة SMS لتقييم الخدمة وإن رأيه\n                              بيفرق معانا جداً. ودعه باحترافية.</li>\n</div>\n<div style=\"background:#eef2f6; border:1px solid #003399; padding:15px; border-radius:12px; margin-top:20px;\">\n<div data-c=\"126\" style=\"background:#003399; color:white; padding:6px 16px; border-radius:15px; font-weight:bold; text-align:center; width:fit-content; margin:0 auto 10px auto;\">\n                              ما وراء الكواليس: معلومات تهمك عشان تطمن العميل</div>\n<div style=\"text-align:center; font-weight:bold; margin-bottom:10px; color:#003399;\">عشان\n                              تكون عارف دورة حياة المنتج بعد ما بتعمل الأوردر:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>الطلب يُرسل تلقائياً لنظام المخزن.</li>\n<li><span class=\"bullet\"></span>فريق المخزن بيجهز الطلبات من 7:00 صباحاً لـ 3:00 مساءً.\n                              </li>\n<li><span class=\"bullet\"></span>أمين المخزن بيسلم المنتجات لمندوب العمليات عشان تتحول\n                                لمركز الفرز Sorting Center.</li>\n<li><span class=\"bullet\"></span>الشحنات بتتغلف والفواتير بتطبع قبل الساعة 4:00 مساءً عشان\n                                تخرج للتوصيل تاني يوم.</li>\n<li><span class=\"bullet\"></span><strong>مدة التوصيل الفعلية:</strong> من 3 لـ 5 أيام في\n                                القاهرة والجيزة، ومن 5 لـ 7 أيام في الإسكندرية والصعيد.</li>\n</div>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-call_center\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"127\" style=\"text-align: center; font-size: 22px; margin-bottom: 4px;\">بروتوكول طلبات الكول سنتر\n                          </div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 4px; color: #003399;\">\n                            الاستلام من الفرع</div>\n<div style=\"text-align: center; font-size: 16px; font-weight: bold; margin-bottom: 15px; color: #64748b;\">\n                            \"كمل بيعة زميلك للاستلام الفوري\"</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            لما العميل يطلب أوردر من خلال خدمة العملاء ويختار يستلمه من فرعك، ده معناه إن زميلك في الكول\n                            سنتر بدأ البيعة، ودورك كـ \"صاحب بيت\" إنك تكملها وتقفلها بسرعة واحترافية. دي الخطوات الرسمية\n                            من أول ما العميل يدخل الفرع:\n                          </div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            1. ما وراء الكواليس (إيه اللي حصل قبل ما العميل يجيلك؟)</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-bottom:8px;\">عشان تكون فاهم الصورة كاملة\n                              موظف الكول سنتر عمل الآتي:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>استقبل العميل، حدد طلبه، وتأكد من توافر المنتج في فرعك.\n                              </li>\n<li><span class=\"bullet\"></span>سجل بيانات العميل وتفاصيل الطلب على شاشة (Remedy – Inquiry\n                                Window).</li>\n<li><span class=\"bullet\"></span>حفظ الطلب، واللي اترحل تلقائياً كنظام بيع (Sales Order)\n                                على سيستم Dynamics.</li>\n<li data-c=\"128\"><span class=\"bullet\"></span>بلّغ العميل يتوجه لفرعك ومعه \"رقم الأوردر\".</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            2. دورك كـ \"صاحب البيت\" (استقبال وتسليم)</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-bottom:8px;\">بمجرد دخول العميل الفرع، دي\n                              الخطوات الإلزامية اللي هتعملها:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>الاستقبال: رحب بضيفك بابتسامة، واطلب منه \"رقم الموبايل\" أو\n                                \"رقم الطلب\".</li>\n<li><span class=\"bullet\"></span>مراجعة الطلب على السيستم (Dynamics).</li>\n<li><span class=\"bullet\"></span>اضغط على Order ▶ Recall Order</li>\n<li><span class=\"bullet\"></span>ابحث برقم الموبايل أو رقم الطلب، وراجع كل التفاصيل مع\n                                العميل.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            3. مرحلة الدفع (Tender)</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; margin-bottom:10px;\">اختار مع العميل طريقة الدفع الأنسب ليه\n                              من الخيارات المتاحة:</div>\n<div style=\"display:flex; justify-content:center; gap:12px; flex-wrap:wrap; margin-bottom:10px; font-weight:bold; color:#003399; background:#f0f4ff; padding:10px; border-radius:8px;\">\n<span>• كاش</span>\n<span>• بطاقة ائتمان</span>\n<span>• بطاقة خصم مباشر</span>\n<span>• تقسيطي</span>\n<span>• شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan)</span>\n</div>\n<div class=\"rule-list\" style=\"margin-bottom:10px;\">\n<li><span class=\"bullet\"></span>مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة (جزء كاش + جزء\n                                تقسيط أو فيزا).</li>\n<li data-c=\"129\"><span class=\"bullet\"></span><strong>إذن التسليم (Delivery Note):</strong> بعد الدفع،\n                                السيستم بيصدر الإذن تلقائياً وفيه كل بيانات العملية:\n                                <ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>رقم العملية Transaction Number.</li>\n<li>اسم الفرع وكودك.</li>\n<li>اسم العميل وموبايله.</li>\n<li>تاريخ الاستلام.</li>\n<li>رقم الإيصال.</li>\n<li>كود المنتج والسيريال.</li>\n<li>سعر المنتج.</li>\n</ul>\n</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            4. خطوة خصم المخزون الإلزامية (Pickup)</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-bottom:8px;\">عشان تقفل العملية صح\n                              والقطعة تتخصم من عهدة الفرع:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>ادخل مرة تانية على مسار: Recall Order</li>\n<li><span class=\"bullet\"></span>اختار زرار Pickup</li>\n<li><span class=\"bullet\"></span>راجع كود المنتج (Item Code) والكمية (Quantity)</li>\n<li><span class=\"bullet\"></span>اضغط على Pickup لإتمام العملية وخصم المخزون.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            5. إصدار الفاتورة والتسليم</div>\n<div style=\"margin-bottom:15px;\">\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>الفاتورة هتصدر تلقائياً على السيستم:</strong>\n                                التاريخ - الوقت - رقم العملية - بياناتك - بيانات الفرع - بيانات العميل - وبيانات المنتج.\n                              </li>\n<li data-c=\"130\"><span class=\"bullet\"></span><span style=\"color:#003399; font-weight:bold;\">التسليم:</span> اطبع الفاتورة وسلم المنتج في\n                                إيد العميل مع الفاتورة.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            6- الضمان ورسالة التقييم CSAT-NPS</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>وضح مين المسئول عن الضمان راية ولا شركة تانية؟ وإديله عناوين\n                              فروع الصيانة.</li>\n<li><span class=\"bullet\"></span>تفعيل الـ QR Code: نبه العميل إنه لازم يمسح الكيو آر كود\n                              لتفعيل الضمان للبراندات دي: De'Longhi – Kenwood – Philips – Sary – Braun.</li>\n<li><span class=\"bullet\"></span>بلغ العميل إنه هيستقبل رسالة SMS لتقييم الخدمة وإن رأيه\n                              بيفرق معانا جداً. ودعه باحترافية.</li>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-shipping\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"131\" style=\"text-align: center; font-size: 22px; margin-bottom: 4px;\">بروتوكول الشحن</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 4px; color: #003399;\">\n                            من فرعك أو فرع آخر</div>\n<div style=\"text-align: center; font-size: 16px; font-weight: bold; margin-bottom: 15px; color: #64748b;\">\n                            \"بيع من أي مكان، ووصّل لأي مكان\"</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            أحياناً العميل بيحتاج جهاز سواء أجهزة كبيرة HA/MDA، أو صغيرة SDA، أو شاشات TV ومحتاج يشحنه،\n                            سواء الجهاز متاح في فرعك أو هنسحبه من فرع تاني، كـ \"صاحب بيت\"<br/>\n<strong>دي الخطوات اللي بتضمن إن الأوردر يتسجل صح ويوصل للعميل في ميعاده:</strong>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            1. الاستقبال وتحديد الطلب</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>استقبل العميل بود، وافهم احتياجاته بأسئلة سريعة.</li>\n<li><span class=\"bullet\"></span>ساعده يختار الجهاز المناسب، واعرض عليه الإكسسوارات أو\n                              البدائل المتاحة لتعظيم البيعة.</li>\n<li><span class=\"bullet\"></span>التحقق من التوافر: شيك على السيستم إذا كان المنتج متاح في\n                              فرعك الحالي أو في فروع تانية، ووضح للعميل خيارات الشحن المتاحة.</li>\n<li data-c=\"132\"><span class=\"bullet\"></span>أكد مع العميل تفاصيل اختياره النهائي: الموديل – الكمية –\n                              السعر.</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            2. شغل السيستم Dynamics: توجيه الشحن</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; font-weight:bold; margin-bottom:10px;\">بمجرد التأكيد افتح\n                              السيستم وامشي على الخطوات دي بالترتيب:</div>\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">بيانات المنتج:</div>\n<div class=\"rule-list\" style=\"margin-bottom:10px;\">\n<li><span class=\"bullet\"></span>إدخال كود المنتج Item Code والكمية.</li>\n<li><span class=\"bullet\"></span>إدخال السيريال نمبر Serial Number للأجهزة اللي ليها سيريال\n                                زي الموبايلات.</li>\n<li><span class=\"bullet\"></span>إضافة تعليق Comment لو في أي ملاحظة اختيارية.</li>\n</div>\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">بيانات العميل:</div>\n<div class=\"rule-list\" style=\"margin-bottom:10px;\">\n<li><span class=\"bullet\"></span>ابحث برقم الموبايل، لو العميل مسجل، بياناته هتظهر\n                                تلقائياً.</li>\n<li><span class=\"bullet\"></span>لو عميل جديد: اختار Add Customer ▶ Create New\n                                Customer وسجل: الاسم – العنوان – رقم الموبايل.</li>\n</div>\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">توجيه الأوردر خطوة الشحن\n                              الأساسية:</div>\n<div class=\"rule-list\" style=\"margin-bottom:10px;\">\n<li><span class=\"bullet\"></span>اضغط على مسار: Order → Shipping Product → Change\n                                Origin</li>\n<li data-c=\"133\"><span class=\"bullet\"></span>اختار \"الفرع\" اللي هيتم الشحن منه سواء فرعك أو فرع تاني.\n                              </li>\n</div>\n<div style=\"color:#003399; font-weight:bold; margin-top:8px;\">مراجعة وتأكيد الشحن:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>راجع بيانات العميل، وبعدين اضغط على Store Shipping وحدد\n                                \"تاريخ الشحن\" المناسب.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            3. مرحلة الدفع Tender</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; margin-bottom:10px;\">اختار مع العميل طريقة الدفع الأنسب ليه\n                              من الخيارات المتاحة:</div>\n<div style=\"display:flex; justify-content:center; gap:12px; flex-wrap:wrap; margin-bottom:10px; font-weight:bold; color:#003399; background:#f0f4ff; padding:10px; border-radius:8px;\">\n<span>• كاش</span>\n<span>• بطاقة ائتمان</span>\n<span>• بطاقة خصم مباشر</span>\n<span>• تقسيطي</span>\n<span>• شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan)</span>\n</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة جزء كاش + جزء\n                                تقسيط أو فيزا.</li>\n<li><span class=\"bullet\"></span><strong>إذن التسليم Delivery Note:</strong> بعد الدفع،\n                                السيستم بيصدر الإذن تلقائياً ابدأ راجع محتوياته: رقم العملية - اسم الفرع/الفرع الآخر -\n                                كودك - اسم وموبايل العميل - تاريخ التسليم - رقم الإيصال - بيانات المنتج.</li>\n<li data-c=\"134\"><span class=\"bullet\"></span>اطبع الإذن وسلم نسخة للعميل في إيده واشكره على ثقته في\n                                راية.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            4- الضمان ورسالة التقييم CSAT-NPS</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-bottom:8px;\">عشان تقفل البيعة باحترافية،\n                              لازم توضح للعميل:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>وضح مين المسئول عن الضمان راية ولا شركة تانية؟ وإديله\n                                عناوين فروع الصيانة.</li>\n<li><span class=\"bullet\"></span>تفعيل الـ QR Code: نبه العميل إنه لازم يمسح الكيو آر كود\n                                لتفعيل الضمان للبراندات دي: De'Longhi – Kenwood – Philips – Sary – Braun.</li>\n<li><span class=\"bullet\"></span>بلغ العميل إنه هيستقبل رسالة SMS لتقييم الخدمة وإن رأيه\n                                بيفرق معانا جداً. ودعه باحترافية.</li>\n</div>\n</div>\n<div style=\"background:#eef2f6; border:1px solid #003399; padding:15px; border-radius:12px; margin-top:20px;\">\n<div style=\"background:#003399; color:white; padding:6px 16px; border-radius:15px; font-weight:bold; text-align:center; width:fit-content; margin:0 auto 10px auto;\">\n                              ما وراء الكواليس: إزاي الشحنة بتتحرك للعميل؟</div>\n<div style=\"text-align:center; font-weight:bold; margin-bottom:10px; color:#003399;\">\n                              المعلومات دي ليك عشان لو العميل سألك عن خط سير الأوردر ومواعيده:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>بمجرد ما بتخلص، السيستم بيبعت طلب لـ Supply Chain كـ\n                                Pickup Request.</li>\n<li data-c=\"135\"><span class=\"bullet\"></span>فريق الـ Fleet بيستلم الطلب ويحدد موعد يروح يستلمه من\n                                الفرع في اليوم التالي.</li>\n<li><span class=\"bullet\"></span>الشحنات بتطلع من الفرع وتتسلم لمركز الفرز Sorting Center\n                                في نفس اليوم.</li>\n<li><span class=\"bullet\"></span>مركز الفرز هو اللي بيوصلها للعميل.</li>\n<li><span class=\"bullet\"></span><strong>مدة التوصيل الإجمالية:</strong> من 3–5 أيام\n                                للقاهرة والجيزة، ومن 5–7 أيام للإسكندرية والصعيد.</li>\n</div>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-discount\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"136\" style=\"text-align: center; font-size: 22px; margin-bottom: 4px;\">بروتوكول طلبات الخصم\n                            الاستثنائي</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                            إزاي تعمل خصم وتريّح العميل صح</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            أحياناً عشان تقفل بيعة كبيرة، العميل بيطلب خصم خاص، راية بتديلك الصلاحية دي كـ \"صاحب بيت\" من\n                            خلال خصم (Price Level A)، بس عشان الخطوة دي فيها موافقات،<br/>\n<strong>دي الطريقة الرسمية اللي تخلص بيها البيعة من غير ما تعطّل ضيفك:</strong>\n</div>\n<div style=\"background:linear-gradient(135deg, #003399 0%, #1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:20px 0 15px 0;\">\n                            📌 المرحلة الأولى: مع العميل (وجهاً لوجه)\n                          </div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            1. الاستقبال والبيع</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>استقبل العميل بابتسامة افهم احتياجاته واعرض عليه المنتج\n                              الأنسب والبدائل المتاحة.</li>\n<li><span class=\"bullet\"></span>بعد ما العميل يستقر نهائياً ويطلب خصم أكد معاه كل تفاصيل\n                              المنتج (الموديل – الكمية – السعر) قبل أي خطوة.</li>\n</div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            2. الموافقة السريعة (المكالمة)</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li data-c=\"137\"><span class=\"bullet\"></span>تواصل فوراً عبر الهاتف مع فريق الـ Merchandising (Category\n                              Manager) لطلب الموافقة السريعة على تطبيق خصم (Price Level A).</li>\n</div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            3. الفاتورة اليدوية والتسليم (عشان متأخرش العميل)</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>بمجرد الموافقة الصدفيّة أصدر \"فاتورة يدوية\" (Manual) للعميل،\n                              وسجل فيها: (اسم العميل - رقم الموبايل - العنوان - الكمية - كود المنتج - السعر).</li>\n<li><span class=\"bullet\"></span>اطبع الفاتورة اليدوية وسلمها للعميل في إيده مع المنتج.</li>\n</div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            4. ختام رحلة العميل (الضمان وتقييم الخدمة NPS&amp;CSAT)</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>وضح مين المسئول عن الضمان وإإيه هي عناوين فروع الصيانة.</li>\n<li><span class=\"bullet\"></span>تفعيل الـ QR Code: نبه عليه يمسح الكيو آر كود لتفعيل الضمان\n                              للبراندات دي: (De'Longhi – Kenwood – Philips – Sary – Braun).</li>\n<li data-c=\"138\"><span class=\"bullet\"></span>بلّغه إنه هيستقبل رسالة (SMS) لتقييم الخدمة وإن رأيه مهم\n                              جداً لينا.</li>\n</div>\n<div style=\"background:linear-gradient(135deg, #003399 0%, #1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:25px 0 15px 0;\">\n                            💻 المرحلة الثانية: شغلك الإداري والسيستم (التقفيل صح)\n                          </div>\n<div style=\"text-align:center; font-weight:bold; margin-bottom:15px; color:#003399;\">بعد ما\n                            العميل يمشي وهو مبسوط، دورك تقفل الورقيات والسيستم عشان تحمي عهدتك:</div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            5. الإيميل الرسمي (خطوة إلزامية)</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>ابعت إيميل فوراً لفريق الـ Merchandising عشان تاخد تأكيد\n                              الخصم المكتوب.</li>\n<li><span class=\"bullet\"></span>الإيميل لازم يكون فيه: (كود المنتج – ماركة التليفون/المنتج –\n                              السعر الحالي).</li>\n<li><span class=\"bullet\"></span>فريق الـ Merchandising هيأكد الخصم ويحدث السعر على سيستم\n                              Dynamics.</li>\n<li><span class=\"bullet\"></span><strong>💡 ملحوظة ذكية:</strong> خصم الـ (Price Level A)\n                              صالح لمدة 24 ساعة فقط فلازم تقفل بيعتك في نفس اليوم.</li>\n</div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            6. إنشاء الطلب على السيستم (Dynamics)</div>\n<div style=\"margin-bottom:15px;\">\n<div data-c=\"139\" style=\"font-weight:bold; margin-bottom:8px;\">افتح السيستم وابدأ سجل البيعة:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span><strong>بيانات المنتج:</strong> دخل كود المنتج (Item Code)\n                                والكمية (Quantity) ثم رقم السيريال (Serial Number) لو المنتج ليه سيريال زي الموبايلات\n                                وتقدر تضيف تعليق (Comment) لو حابب.</li>\n<li><span class=\"bullet\"></span><strong>بيانات العميل:</strong> ابحث برقم الموبايل:\n                                <ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>لو مسجل ➔ البيانات هتظهر.</li>\n<li>لو جديد ➔ اضغط Create New Customer ▶ Add Customer وسجل (الاسم +\n                                    العنوان + رقم الموبايل).</li>\n</ul>\n</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            7. تطبيق الخصم على السيستم (السر هنا)</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>عشان تُفعل الخصم اللي الإدارة وافقت عليه اضغط على مسار:\n                              Special ▶ Price Level A</li>\n</div>\n<div style=\"background:#003399; color:white; padding:6px 14px; border-radius:18px; font-weight:bold; width:fit-content; margin-bottom:10px;\">\n                            8. مرحلة الدفع (Tender) وإصدار الفاتورة:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>اختار طريقة الدفع التي فضل حاسب بيها: كاش، Credit Card،\n                              Debit Card، أو تقسيطي.</li>\n<li data-c=\"140\"><span class=\"bullet\"></span>بمجرد إتمام الخطوة دي السيستم هيصدر الفاتورة النهائية\n                              تلقائياً وكده البيعة اتقفلت صح 100% والعهدة اتظبطت.</li>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-other_branch_delivery\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"141\" style=\"text-align: center; font-size: 22px; margin-bottom: 4px;\">بروتوكول تسليم طلب من فرع\n                            تاني</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                            ضيف زميلك.. هو ضيفك</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            لما العميل يشتري أوردر من فرع تاني ويختار يستلمه من فرعك، ده معناه إن زميلك قفل البيعة،\n                            ودورك كـ \"صاحب بيت\" إنك تكرم الضيف، تسلمه جهازه بسرعة، وتقفل العملية على السيستم عشان تظبط\n                            عهدتك المخزنية.<br/>\n<strong>دي الخطوات الرسمية:</strong>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            1. الاستقبال والبحث عن الطلب</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>استقبل ضيفك بابتسامة ولباقة زي ما إحنا متعودين.</li>\n<li data-c=\"142\"><span class=\"bullet\"></span><strong>على السيستم Dynamics:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>اضغط على مسار: Recall Order</li>\n<li>ابحث عن طلب العميل باستخدام \"رقم الموبايل\" \"أو\" \"رقم الإيصال\".</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            2. تنفيذ الاستلام وخصم المخزون Pickup</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-bottom:8px;\">عشان تسلم العميل وتخصم\n                              القطعة من عهدة فرعك بشكل سليم:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>بعد ما تفتح الطلب، اختار زرار Pickup</li>\n<li><span class=\"bullet\"></span>راجع بدقة شديدة الكمية + كود المنتج Item Code</li>\n<li><span class=\"bullet\"></span>إدخال أرقام السيريال Serial Numbers لو المنتج بيحتاج\n                                سيريال.</li>\n<li><span class=\"bullet\"></span>اضغط مرة تانية على Pickup لإتمام العملية رسمياً وخصم\n                                الكمية من مخزونك.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            3. إصدار الفاتورة والتسليم الفعلي</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>بمجرد إتمام خطوة الـ Pickup، السيستم هيصدر الفاتورة\n                              تلقائياً.</li>\n<li><span class=\"bullet\"></span>الفاتورة هتكون شاملة: التاريخ والوقت – رقم العملية – كودك\n                              كموظف – اسم فرعك – اسم العميل – رقم الإيصال – بيانات المنتج زي الكود والسيريال والسعر.\n                            </li>\n<li data-c=\"143\"><span class=\"bullet\"></span>اطبع الفاتورة فوراً وسلم المنتج في إيد العميل مع الفاتورة.\n                            </li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            4. ختام رحلة العميل الضمان وتقييم الخدمة NPS &amp; CSAT</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"color:#003399; font-weight:bold; margin-bottom:8px;\">قبل ما تودع العميل، لازم\n                              تأكد على أساسيات خدمة ما بعد البيع:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>وضحله مين الجهة المسئولة عن الضمان راية ولا شركة تانية؟\n                                وإديله عناوين فروع الصيانة.</li>\n<li><span class=\"bullet\"></span>تفعيل الـ QR Code: نبه العميل على ضرورة مسح الكيو آر كود\n                                لتفعيل الضمان للبراندات دي: De'Longhi – Kenwood – Philips – Sary – Braun.</li>\n<li><span class=\"bullet\"></span>بلّغه إنه هيستقبل رسالة SMS لاستطلاع رأيه وتقييم الخدمة،\n                                وأكد إن رأيه مهم جداً لينا عشان نطور من نفسنا.</li>\n<li><span class=\"bullet\"></span>ودّع ضيفك بشكل لبق واحترافي عشان يخرج من الفرع وهو راضي\n                                100%.</li>\n</div>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-large_appliance_exchange\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"144\" style=\"text-align: center; font-size: 22px; margin-bottom: 4px;\">بروتوكول استبدال الأجهزة\n                            الكبيرة</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                            بدّل لضيفك لحد باب البيت</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            لما العميل يطلب استبدال جهاز كبير ثلاجة، غسالة، بوتاجاز.. ومش هينفع يجيبه الفرع ومحتاجنا\n                            نبدلهوله من البيت، العملية دي بتتم بخطوات دقيقة جداً عشان نحافظ على حق العميل وحق \"بيتنا\"\n                            وعهدتنا. هنقسمها لـ 3 مراحل:\n                          </div>\n<div style=\"background:linear-gradient(135deg, #003399 0%, #1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:20px 0 15px 0;\">\n                            📌 المرحلة الأولى: الاستقبال والتأكد من الشروط معاك في الفرع\n                          </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>الترحيب والفهم: استقبل العميل بود وافهم منه سبب الاستبدال.\n                            </li>\n<li><span class=\"bullet\"></span>مراجعة شروط الاستبدال جهاز حماية المستهلك CPA:\n                              <ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>خلال 14 يوم: الجهاز بحالته الأصلية وبكل مشتملاته.</li>\n<li>خلال 30 يوم: لازم تقرير فني معتمد من مركز الصيانة.</li>\n</ul>\n</li>\n<li><span class=\"bullet\"></span>تأكيد الشراء: اطلب الفاتورة، أو راجع بيانات الشراء على\n                              السيستم برقم الموبايل أو رقم الطلب.</li>\n<li data-c=\"145\"><span class=\"bullet\"></span>القرار التقرير الفني هو الفيصل:\n                              <ul style=\"margin:5px 0 0 20px; padding:0; list-style:none;\">\n<li>❌ <strong>لو مفيش تقرير فني:</strong> وجه العميل بلباقة شديدة لمركز الصيانة المعتمد\n                                  عشان يفحص المنتج ويجيب التقرير.</li>\n<li>✅ <strong>لو التقرير موجود:</strong> هنبدأ فوراً في الخطوات الإدارية.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:linear-gradient(135deg, #003399 0%, #1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:25px 0 15px 0;\">\n                            💻 المرحلة الثانية: الموافقات وإنشاء الأوردر على السيستم Dynamics\n                          </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>1- طلب الموافقة:</strong> ابعت إيميل لفريق الـ\n                              Merchandising Category Manager مرفق فيه رقم الطلب + التقرير الفني، الرد بالموافقة بيتم\n                              خلال 24 ساعة.</li>\n<li data-c=\"146\"><span class=\"bullet\"></span><strong>2- إنشاء الطلب الجديد بعد الموافقة:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>افتح السيستم واعمل Order جديد.</li>\n<li>دخل كود الصنف والكمية + رقم السيريال.</li>\n<li>🖨️ <strong>خطوة إلزامية التعليق:</strong> لازم تكتب التعليق ده بالنص:<br/>\n<code style=\"background:#f0f4ff; color:#003399; padding:4px 8px; border-radius:4px; font-weight:bold; display:inline-block; margin-top:4px;\">Replacement order – to collect old item upon delivery طلب استبدال – سيتم استلام المنتج القديم عند التسليم</code>\n</li>\n</ul>\n</li>\n<li data-c=\"147\"><span class=\"bullet\"></span><strong>3- توجيه الشحن للمخزن:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>ابحث برقم موبايل العميل.</li>\n<li>اضغط على Order → Shipping Product → Change Origin.</li>\n<li>اختار \"المخزن الرئيسي\" وحدد تاريخ التسليم المناسب.</li>\n</ul>\n</li>\n<li><span class=\"bullet\"></span><strong>4- إتمام الدفع Tender:</strong> اضغط على Tender\n                              واختار وسيلة الدفع لتسوية العملية المحاسبية.</li>\n<li><span class=\"bullet\"></span><strong>5- إبلاغ العميل:</strong> بلّغه بموعد التسليم، وأكد\n                              عليه إن المندوب \"هيستلمه الجهاز الجديد ويستلم منه الجهاز القديم في نفس الوقت\".</li>\n</div>\n<div style=\"background:#eef2f6; border:1px solid #003399; padding:15px; border-radius:12px; margin-top:20px; margin-bottom:20px;\">\n<div style=\"background:#003399; color:white; padding:6px 16px; border-radius:15px; font-weight:bold; text-align:center; width:fit-content; margin:0 auto 10px auto;\">\n                              ما وراء الكواليس: المخازن والتوصيل</div>\n<div style=\"text-align:center; font-weight:bold; margin-bottom:10px; color:#003399;\">عشان لو\n                              العميل سألك:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>المخزن بيجهز الشحنة ويبعتها لمركز الفرز قبل 4 عصراً.</li>\n<li><span class=\"bullet\"></span>مدة التوصيل: 3–5 أيام للقاهرة والجيزة، و5–7 أيام\n                                للإسكندرية والصعيد.</li>\n<li><span class=\"bullet\"></span>فريق التوصيل Fleet بيسلم الجديد ويستلم القديم، ويرجعه\n                                للمخزن عشان يتفحص.</li>\n<li data-c=\"148\"><span class=\"bullet\"></span>المخزن بيبعتلك إيميل أول ما يستلم الجهاز المرتجع عشان تكمل\n                                أنت شغلك.</li>\n</div>\n</div>\n<div style=\"background:linear-gradient(135deg, #003399 0%, #1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:25px 0 15px 0;\">\n                            🔐 المرحلة الثالثة: التقفيلة الإدارية للعهدة بعد إيميل المخزن\n                          </div>\n<div style=\"text-align:center; font-weight:bold; margin-bottom:15px; color:#003399;\">بمجرد ما\n                            المخزن يبلغك إنه استلم الجهاز القديم، لازم تقفل البيعة على السيستم عشان عهدتك:</div>\n<div class=\"rule-list\">\n<li data-c=\"149\"><span class=\"bullet\"></span><strong>1. تنفيذ المرتجع:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>ادخل على السيستم واضغط: <strong>Action ⬅️ Return Transaction</strong>.</li>\n<li>ابحث برقم الإيصال واضغط <strong>Enter</strong>.</li>\n<li>اضغط <strong>Return</strong> وحدد سبب الإرجاع.</li>\n</ul>\n</li>\n<li data-c=\"150\"><span class=\"bullet\"></span><strong>2. إنشاء تحويل مخزني:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>ابعت إيميل لـ مدير المنطقة Area Manager عشان يعمل تحويل للمنتج من الفرع للمخزن.</li>\n<li>مدير المنطقة هيعمل التحويل ويبعتلك \"رقم التحويل\".</li>\n</ul>\n</li>\n<li data-c=\"151\"><span class=\"bullet\"></span><strong>3. إغلاق العملية:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>حدث حالة التحويل على السيستم إلى <strong>Shipped</strong>.</li>\n<li>فريق المخزن هيستلم التحويل ويقفل عملية المرتجع بنجاح 100%.</li>\n</ul>\n</li>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-large_appliance_returns\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"152\" style=\"text-align: center; font-size: 22px; margin-bottom: 8px;\">بروتوكول الإرجاع والاسترداد\n                            للأجهزة الكبيرة</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                            \"حق ضيفك محفوظ لحد باب بيته\"</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                            لما العميل يطلب إرجاع جهاز كبير واسترداد قيمته، ومش هينفع يجيبه الفرع، دورك كـ \"صاحب بيت\"\n                            إنك تدير العملية دي باحترافية لأنها بتشمل أطراف كتير إدارة، مخازن، شحن، وحسابات. دي الخطوات\n                            الرسمية متقسمة حسب الوقت:\n                          </div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            1 المحطة الأولى: الاستقبال والفحص المبدئي العميل قدامك</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>الترحيب وفهم الموقف:</strong> استقبل ضيفك بلباقة،\n                              وافهم منه سبب الإرجاع بهدوء لامتصاص أي غضب.</li>\n<li data-c=\"153\"><span class=\"bullet\"></span><strong>مراجعة الفاتورة والشروط CPA:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>اطلب الفاتورة، أو ابحث عن بيانات الشراء على السيستم بـ رقم الموبايل / رقم الطلب.\n                                </li>\n<li><strong>خلال 14 يوم:</strong> متاح الإرجاع لو الجهاز بحالته الأصلية ومشتملاته\n                                  ومتفتحش.</li>\n<li><strong>خلال 30 يوم أو لو اتفتح 🔧:</strong> لازم تقرير فني معتمد من مركز الصيانة.\n                                </li>\n</ul>\n</li>\n<li data-c=\"154\"><span class=\"bullet\"></span><strong>القرار الحاسم:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>❌ <strong>لو مفيش تقرير فني:</strong> وجّه العميل بلباقة لمركز الصيانة لفحص المنتج\n                                  وإحضار التقرير قبل استكمال أي إجراء.</li>\n<li>✅ <strong>لو التقرير موجود:</strong> هنبدأ فوراً في الإجراءات الإدارية.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            2 المحطة الثانية: الموافقات وتحريك الشحن</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>1. طلب الموافقة:</strong> ابعت إيميل فوراً لفريق\n                              Merchandising Category Manager مرفق فيه رقم الطلب + التقرير الفني. الفريق هيراجع ويبعتلك\n                              الموافقة على الإيميل.</li>\n<li><span class=\"bullet\"></span><strong>2. طلب الاستلام Supply Chain:</strong> بعد الموافقة،\n                              ادخل على سيستم الـ Supply Chain وأنشئ \"شحنة مرتجع\".</li>\n<li><span class=\"bullet\"></span><strong>3. إبلاغ العميل:</strong> بلّغ العميل بوضوح إن\n                              المنتج هيتم استلامه من بيته خلال 48 ساعة، وإن فريق التوصيل هيكلمه ينسق معاه الميعاد.</li>\n</div>\n<div data-c=\"155\" style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            3 المحطة الثالثة: ما وراء الكواليس الاستلام والفحص المخزني</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; margin-bottom:10px; color:#003399; font-weight:bold;\">المرحلة\n                              دي بتتم بعيد عنك، بس لازم تكون عارفها</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>الطلب بيوصل لفريق الشحن Fleet، بيعملوا خطة السير الساعة 7\n                                مساءً، والسائق بيكلم العميل يأكد العنوان والميعاد.</li>\n<li><span class=\"bullet\"></span>المندوب بيستلم الجهاز ويرجعه المخزن.</li>\n<li><span class=\"bullet\"></span>فريق المخزن بيفحص حالة الجهاز، وبعدها بيبعتلك إيميل عشان\n                                يبلغك تكمل إجراءاتك على السيستم.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                            4 المحطة الرابعة: تقفيل السيستم والعهدة Dynamics</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; margin-bottom:10px; color:#003399; font-weight:bold;\">بمجرد\n                              ما تستلم إيميل المخزن، لازم تقفل العملية فوراً عشان تظبط عهدتك:</div>\n<div class=\"rule-list\">\n<li data-c=\"156\"><span class=\"bullet\"></span><strong>1. تنفيذ الإرجاع على السيستم:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>اضغط: <strong>Action</strong> ثم اختار <strong>Return Transaction</strong>.</li>\n<li>ابحث بـ \"رقم الإيصال\" واضغط <strong>Enter</strong>.</li>\n<li>اضغط ⬅️ <strong>Return</strong> وحدد سبب الإرجاع.</li>\n</ul>\n</li>\n<li data-c=\"157\"><span class=\"bullet\"></span><strong>2. تحويل العهدة للمخزن خطوة إلزامية:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>ابعت إيميل لـ مدير المنطقة لإنشاء طلب تحويل من فرعك للمخزن الرئيسي.</li>\n<li>مدير المنطقة هيعمل التحويل ويبعتلك \"رقم التحويل\".</li>\n<li>ادخل على السيستم وحدث حالة التحويل إلى <strong>Shipped</strong>.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              5 المحطة الخامسة: تسوية الفلوس الاسترداد وختام الرحلة</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; margin-bottom:10px; color:#003399; font-weight:bold;\">بعد\n                                تقفيل السيستم، تواصل مع العميل لتبليغه بإتمام العملية، ونفذ الاسترداد حسب طريقة الدفع:\n                              </div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>💵 <strong>لو الدفع كان كاش:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>اطلب من العميل زيارة الفرع لاستلام قيمة المرتجع نقداً.</li>\n</ul>\n</li>\n<li><span class=\"bullet\"></span>💳 <strong>لو الدفع كان فيزا أو بطاقة بنكية:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>أنشئ طلب استرداد على سيستم <strong>Remedy</strong> وأرفق فيه: إيصال المرتجع +\n                                      فاتورة البيع + رقم بطاقة الفيزا.</li>\n<li>بلّغ العميل إن المبلغ هيترد على حسابه/بطاقته خلال 14 يوم عمل.</li>\n</ul>\n</li>\n</div>\n</div>\n<div style=\"text-align:center; margin-top:20px;\">\n<div data-c=\"158\" style=\"background:#eef2f6; border:1px solid #003399; padding:15px; border-radius:12px; display:inline-block; max-width:80%;\">\n                                ✨ <strong>الختام:</strong> اشكر العميل على ثقته في راية، وتأكد من رضاه التام عن مستوى\n                                الخدمة، وودعه باحترافية.\n                              </div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-taqsiti_system\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"159\" style=\"text-align: center; font-size: 22px; margin-bottom: 8px;\">بروتوكول التقسيط بنظام\n                              \"تقسيطى\"</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                              \"سهلها على ضيفك.. وقفل بيعتك صح\"</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                              لما العميل يقرر يشتري قسط، دي فرصتك تقفل بيعة ممتازة. نظام \"تقسيطى\" معمول عشان ينجزك، بس\n                              محتاج تمشي على الخطوات دي بالمللي عشان تحمي العميل وتضمن الموافقة السريعة:\n                            </div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              المرحلة الأولى: الاستقبال وكشف الحساب المبدئي</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>1 الترحيب وفهم العميل:</strong> استقبل ضيفك، افهم\n                                احتياجاته واشرح له \"بروتوكول التقسيط\" ببساطة.</li>\n<li><span class=\"bullet\"></span><strong>2 شغل السيستم المبدئي:</strong> اطلب بطاقة الرقم\n                                القومي، ودخل بياناته على سيستم \"تقسيطى\" عشان السيستم يعمل فحص الـ I-Score ويحدد هو \"عميل\n                                جديد\" ولا \"عميل راية\".</li>\n<li data-c=\"160\"><span class=\"bullet\"></span><strong>3 قرار السيستم اللحظي:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>❌ <strong>حالة الرفض المبدئي:</strong> السيستم بيحول الطلب تلقائياً لفريق الائتمان\n                                    للمراجعة والتحقيق. دورك هنا انتهى مؤقتاً.</li>\n<li>✅ <strong>حالة الموافقة المبدئية:</strong> بنكمل الإجراءات فوراً حسب نوع العميل\n                                    قديم ولا جديد.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              المحطة الثانية: تفريغ العملاء عميل قديم ولا جديد؟</div>\n<div style=\"display:flex; flex-wrap:wrap; gap:20px; margin-bottom:15px;\">\n<div style=\"flex:1; min-width:250px; background:#f9fafb; border:1px solid #e5e7eb; border-radius:12px; padding:15px;\">\n<div style=\"text-align:center; font-weight:bold; color:#003399; margin-bottom:10px;\">\n                                  أولاً: العميل القديم</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>اختار خطة التقسيط والمنتج، وأنشئ الطلب على سيستم\n                                    تقسيطى.</li>\n<li><span class=\"bullet\"></span>العميل بيوقع على \"عقد الحد الائتماني\" لو دي أول مرة\n                                    يوقع فيها.</li>\n<li><span class=\"bullet\"></span>إجراءات الـ KYC إلزامية: التقاط صورة حية Live Photo\n                                    للعميل، وإدخال رمز الـ OTP اللي هيتبعتله.</li>\n</div>\n</div>\n<div style=\"flex:1; min-width:250px; background:#f0f4ff; border:1px solid #ccd6f5; border-radius:12px; padding:15px;\">\n<div style=\"text-align:center; font-weight:bold; color:#003399; margin-bottom:10px;\">\n                                  ثانياً: العميل الجديد</div>\n<div style=\"font-weight:bold; margin-bottom:8px; font-size:13px; color:#1a3755;\">السيستم\n                                  هيحولك لإنشاء \"حد ائتماني جديد\":</div>\n<div class=\"rule-list\" style=\"font-size:13px;\">\n<li><span class=\"bullet\"></span><strong>1. البيانات الأساسية:</strong> دخل الاسم\n                                    بالكامل - الموبايل - الوظيفة ⬅️ ابعت رمز الـ OTP للعميل ودخله ⬅️ السيستم هيعمل فحص\n                                    احتيال Fraud Check للتأكد من الأهلية.</li>\n<li data-c=\"161\"><span class=\"bullet\"></span><strong>2. استكمال البروفايل بعد الفحص:</strong> دخل\n                                    الحالة الاجتماعية - العنوان - بيانات الوظيفة - عضوية النادي - بيانات الضامن إن لزم\n                                    الأمر.</li>\n<li><span class=\"bullet\"></span><strong>3. رفع الورق:</strong> ارفع المستندات المتاحة\n                                    زي بطاقة التأمين الطبي / رخصة السيارة \"اختياري\".</li>\n<li><span class=\"bullet\"></span><strong>4. المراجعة:</strong> السيستم بيبعت للعميل SMS\n                                    بتفاصيل طلبه عشان يقدر يتابعه.</li>\n<li><span class=\"bullet\"></span>🧑‍💻 <strong>هنا بيتدخل فريق الائتمان</strong> يراجع\n                                    الورق، يعمل زيارة ميدانية لو لزم الأمر وياخد قرار الموافقة ويحدد الحد الائتماني،\n                                    وبعدها العميل بيستلم SMS بالموافقة والليميت بتاعه.</li>\n</div>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              المحطة الثالثة: تعلية الليميت Limit Increase خطوة استثنائية</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>لو العميل الليميت بتاعه نزل بس محتاج يزوده عشان يشتري منتج\n                                أغلى:\n                                <ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li data-c=\"162\">اضغط على رابط \"زيادة الحد الائتماني\" على السيستم.</li>\n<li>ارفع مستندات إثبات الدخل زي: خطاب HR حديث - كشف حساب بنكي - بيانات الضامن.</li>\n<li>الطلب بيتبعت فوراً لفريق الائتمان للمراجعة.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              المحطة الرابعة: التفعيل وإتمام البيعة</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>بمجرد ما الليميت يعتمد للعميل الجديد أو بعد التعلية:\n                                <ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li><strong>التفعيل:</strong> العميل بيوقع عقد الحد الائتماني لأول مرة فقط ⬅️ بتعمل\n                                    إجراءات الـ KYC صورة حية + OTP ⬅️ العميل بيستلم SMS بتأكيد التفعيل.</li>\n<li><strong>البيع:</strong> ساعد العميل يختار المنتج اللي يناسب الليميت بتاعه وقيمة\n                                    القسط، وقفل البيعة على السيستم.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              المحطة الخامسة: التسليم وحفظ المستندات التقفيلة الصح</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>الاستلام من الفرع:</strong> العميل بيوقع على\n                                \"نموذج استلام المنتج\" وبياخده في إيده.</li>\n<li data-c=\"163\"><span class=\"bullet\"></span><strong>التوصيل للمنزل:</strong> بيتم في خلال 3-5 أيام\n                                للقاهرة والجيزة، و 5-7 أيام للمحافظات. السائق بيستلم إذن التسليم لأرشيف المخزن ليتسجل\n                                على السيستم.</li>\n</div>\n<div style=\"background:#eef2f6; border:1px solid #003399; padding:15px; border-radius:12px; margin-top:20px; margin-bottom:20px;\">\n<div style=\"background:#003399; color:white; padding:6px 16px; border-radius:15px; font-weight:bold; text-align:center; width:fit-content; margin:0 auto 10px auto;\">\n                                📁 ما وراء الكواليس حفظ الورق</div>\n<div style=\"text-align:center; font-weight:bold; color:#1a3755;\">\n                                فريق الائتمان بيلف على الفروع مرتين شهرياً يجمع مستندات التقسيط الموقعة عشان يأرشفها.\n                                فحافظ على ورقك دايماً كامل ومترتب.\n                              </div>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-small_appliance_returns\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"164\" style=\"text-align: center; font-size: 22px; margin-bottom: 8px;\">بروتوكول مرتجعات الأجهزة\n                              الصغيرة واسترداد الفلوس</div>\n<div style=\"text-align: center; font-size: 18px; font-weight: bold; margin-bottom: 15px; color: #003399;\">\n                              \"حق ضيفك محفوظ.. وعهدتك في أمان\"</div>\n<div class=\"content-text\" style=\"text-align: center; margin-bottom: 20px; line-height: 1.6;\">\n                              لما العميل يقرر يرجع منتج صغير، دي فرصتك كـ \"صاحب بيت\" تثبت له إننا بنحترم حق العميل زي ما\n                              بنحترم فلوسه. العملية دي محتاجة تركيز عالي عشان الفلوس والعهدة تتسوى صح. هنمشيها على 4\n                              مراحل:\n                            </div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              1- الاستقبال والفحص العميل قدامك</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>الترحيب وتحديد الطلب:</strong> استقبل العميل\n                                بابتسامة، وافهم منه سبب الإرجاع بهدوء. تذكر: من حقه يرجع منتج واحد بس من الفاتورة، أو\n                                الفاتورة كلها.</li>\n<li><span class=\"bullet\"></span><strong>مراجعة الفاتورة:</strong> اطلب فاتورة الشراء أو\n                                راجعها على السيستم برقم الموبايل أو رقم الطلب.</li>\n<li data-c=\"165\"><span class=\"bullet\"></span><strong>الفحص القانوني قواعد حماية المستهلك CPA:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li><strong>خلال 14 يوم:</strong> متاح الإرجاع بشرط المنتج يكون بحالته الأصلية.\n                                    ماتفتحش، بكامل مشتملاته وتغليفه، ومراجعة السيريال إن وجد.</li>\n<li><strong>خلال 30 يوم أو لو العميل فتح الكرتونة 🔧:</strong> لازم يكون معاه تقرير\n                                    فني معتمد من مركز الصيانة.</li>\n</ul>\n</li>\n<li data-c=\"166\"><span class=\"bullet\"></span><strong>القرار الحاسم التقرير الفني:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>❌ <strong>لو الجهاز مفتوح ومفيش تقرير:</strong> وجّه العميل بكل لباقة لمركز\n                                    الصيانة المعتمد عشان يفحصوا المنتج ويطلعوله التقرير.</li>\n<li>✅ <strong>لو التقرير موجود أو الجهاز متفتحش:</strong> هنبدأ فوراً في خطوات\n                                    الاسترداد.</li>\n</ul>\n</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              2- موافقة الإدارة خطوة إلزامية</div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>تواصل فوراً مع فريق <strong>Merchandising Category\n                                  Manager</strong> عن طريق الإيميل وممكن تكلمهم في التليفون للسرعة.</li>\n<li><span class=\"bullet\"></span>ابعت في الإيميل: رقم الطلب + التقرير الفني.</li>\n<li><span class=\"bullet\"></span>فريق الـ Merchandising بيراجع الطلب، وهيتبعتلك الموافقة\n                                على الإيميل خلال 24 ساعة كحد أقصى.</li>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              3- السيستم وإيصال المرتجع Dynamics</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"text-align:center; font-weight:bold; margin-bottom:10px; color:#003399;\">بعد\n                                موافقة الإدارة، افتح السيستم ونفذ الآتي بالترتيب عشان تظبط عهدتك:</div>\n<div class=\"rule-list\">\n<li data-c=\"167\"><span class=\"bullet\"></span><strong>1. تنفيذ الإرجاع:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>اضغط على: ⬅️ Action ثم اختار <strong>Return Transaction</strong>.</li>\n<li>ابحث باستخدام \"رقم الإيصال\" واضغط <strong>Enter</strong>.</li>\n<li>اضغط على ⬅️ <strong>Return</strong> ثم اختار \"سبب الإرجاع\".</li>\n</ul>\n</li>\n<li><span class=\"bullet\"></span><strong>2. الحسبة التلقائية:</strong> السيستم هيعالج\n                                  العملية ويحسب مبلغ الاسترداد تلقائياً بناءً على قيمة المنتج في الفاتورة.</li>\n<li><span class=\"bullet\"></span><strong>3. إيصال المرتجع:</strong> السيستم هيصدر إيصال\n                                  مكتوب فيه: رقم العملية، التاريخ والوقت، اسم الفرع، اسم العميل، بيانات المنتج المرتجع،\n                                  وقيمة المبلغ.</li>\n<li><span class=\"bullet\"></span><strong>4. مراجعة العميل:</strong> اطبع الإيصال، وخلّي\n                                  العميل يراجعه ويأكد على بياناته بنفسه.</li>\n</div>\n</div>\n<div style=\"background:#003399; color:white; padding:8px 16px; border-radius:20px; font-weight:bold; text-align:center; margin:15px 0 10px 0;\">\n                              4- تسليم الفلوس التسوية المالية</div>\n<div style=\"margin-bottom:15px;\">\n<div style=\"font-weight:bold; margin-bottom:5px; color:#003399;\">الخطوة دي بتختلف حسب\n                                طريقة دفع العميل الأصلية:</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>🪙 <strong>لو العميل كان دافع كاش:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li data-c=\"168\">يتم رد قيمة المنتج <strong>نقداً للعميل فوراً</strong> في إيده.</li>\n</ul>\n</li>\n<li><span class=\"bullet\"></span>💳 <strong>لو العميل كان دافع فيزا أو بطاقة\n                                    بنكية:</strong>\n<ul style=\"margin:5px 0 0 20px; padding:0; list-style:disc;\">\n<li>الفلوس مش بترجع كاش، لازم تعمل طلب على سيستم <strong>Remedy</strong>.</li>\n<li>مرفقات الـ Remedy الإلزامية: صورة إيصال المرتجع + صورة فاتورة البيع + رقم بطاقة\n                                      الفيزا.</li>\n<li>إبلاغ العميل: لازم توضح للعميل بابتسامة إن المبلغ هيترد على حسابه/بطاقته البنكية\n                                      خلال <strong>14 يوم عمل</strong>.</li>\n</ul>\n</li>\n</div>\n</div>\n<div style=\"text-align:center; margin-top:20px;\">\n<div style=\"font-size:20px; margin-bottom:10px;\">✨ ختام الرحلة ✨</div>\n<div style=\"background:#eef2f6; border:1px solid #003399; padding:15px; border-radius:12px; display:inline-block; max-width:80%;\">\n                                اشكر العميل جداً على وقته، واتأكد إنك قفلت العملية بنجاح. ودّعه بشكل لبق واحترافي يخليه\n                                يتأكد إن \"راية\" دايماً بيته المضمون.\n                              </div>\n</div>\n</div>\n</div>\n</div>\n</div>\n","words":4101},{"id":"store-front","title":"واجهة بيتك","group":"الفرع","icon":"store","html":"\n<div class=\"section-body\">\n<div class=\"main-protocol-tab-content\" id=\"main-protocol-store-front\">\n<div style=\"background:#f0f4ff; border:1px solid #ccd6f5; border-radius:12px; padding:12px 14px; margin-bottom:16px;\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; gap:8px;\">\n<div class=\"guest-step active-step\" data-c=\"169\" onclick=\"showSubProtocolTab('card_language', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">لغة الكروت بطاقة تعارف المنتج</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('product_map', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">خريطة عرض المنتجات</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('sales_cards', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">الكروت البيعية أسلحتك السرية في\n                              الإقناع</div>\n<div class=\"guest-step\" onclick=\"showSubProtocolTab('display_rules', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">قواعد العرض العامة</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-card_language\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"170\" style=\"text-align:center; font-size:22px; margin-bottom:4px;\">\n                              لغة الكروت</div>\n<div style=\"text-align:center; font-size:18px; font-weight:bold; margin-bottom:15px; color:#003399;\">\n                              🏷️ بطاقة تعارف المنتج</div>\n<div class=\"content-text\" style=\"text-align:center; margin-bottom:20px; line-height:1.7;\">\n                              كارت السعر والمواصفات هو أول حاجة عين الضيف بتقع عليها. لو مقاسه غلط أو مكانه عشوائي،\n                              بيشوه المنتج ويضايق الضيف. دي الخريطة المظبوطة لمقاسات وأماكن الكروت:\n                            </div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              ⌚ الإكسسوارات المقاس الأصغر:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong style=\"color:#22c55e;\">المكان:</strong> على حامل\n                                أكريليك صغير تعلق فوق المنتج.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#003399;\">السر البيعي:</strong>\n                                الإكسسوارات حجمها صغير، لو حطيت كارت كبير هتخفي المنتج نفسه! دي منطقتك الذهبية للـ\n                                Cross-selling مع الموبايلات، فخليها دايماً واضحة.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              📱 الموبايلات، اللاب توب، والأجهزة الصغيرة SDA المقاس الصغير:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong style=\"color:#22c55e;\">المكان الصح:</strong> مسطح\n                                نايم على الترابيزة جنب شاشة الموبايل أو لوحة مفاتيح اللاب توب.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#003399;\">السر البيعي:</strong> بيسمح\n                                للضيف يمسك الجهاز <strong>ويجربه براحته</strong> من غير ما الكارت يقع أو يضايقه.</li>\n</div>\n<div data-c=\"171\" style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              📺 الشاشات، الغسالات، البوتاجازات، والبلت إن المقاس المتوسط:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong style=\"color:#22c55e;\">المكان الصح:</strong> يُثبت\n                                بوضوح في الزاوية العلوية اليسرى للمنتج أو الشاشة.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#003399;\">السر البيعي:</strong> ده\n                                مستوى نظر الضيف الطبيعي، بيخليه يقرأ المواصفات وهو باصص للجهاز بتركيز.</li>\n<li><span class=\"bullet\"></span><strong>ملحوظة للغسالات:</strong> لو الغسالة على \"ستاند\n                                أرفف حائطي\"، الكارت يوضع في الزاوية العلوية اليسرى. لو على \"ستاند جزيرة\" في منتصف الفرع،\n                                الكارت يوضع أعلى المنتج في المنتصف.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              ❄️ الثلاجات والفريزرات فقط المقاس الأكبر:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong style=\"color:#22c55e;\">المكان الصح:</strong> يُثبت\n                                في الزاوية العلوية اليسرى للباب العلوي.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#003399;\">السر البيعي:</strong>\n                                التبريد مواصفاته وتفاصيله كتير (السعة، الانفرتر، البلازما...) فمحتاج أكبر كارت عشان\n                                الضيف يقرأ براحته.</li>\n</div>\n<div style=\"background:#fffbeb; border:1px solid #fde68a; padding:15px; border-radius:12px; margin-top:15px; text-align:center;\">\n<div data-c=\"172\" style=\"font-weight:bold; color:#d97706; margin-bottom:6px;\">💡 نصيحة صاحب البيت:\n                              </div>\n<div style=\"color:#92400e; font-weight:bold;\">لو عندك كارت \"خصم\" إضافي، دايماً حطه في\n                                الجهة المقابلة لكارت المواصفات عشان ما يغطيش عليه ويشوه الشكل.</div>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-product_map\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"173\" style=\"text-align:center; font-size:22px; margin-bottom:4px;\">\n                              خريطة عرض المنتجات</div>\n<div style=\"text-align:center; font-size:18px; font-weight:bold; margin-bottom:15px; color:#003399;\">\n                              🗺️ هندسة عين الضيف</div>\n<div class=\"content-text\" style=\"text-align:center; margin-bottom:20px; line-height:1.7;\">\n                              الرص العشوائي بيشتت الضيف، لكن الرص الهندسي بياخد إيده ويقنعه يعلي ميزانيته Up-selling بكل\n                              سلاسة:\n                            </div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              ⌚ الإكسسوارات منطقة الجاذبية:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>دايماً ابدأ بـ \"الساعات الذكية\" في الواجهة، وبعدها\n                                السماعات ثم رص الشواحن، الكابلات، والباور بانك.</li>\n<li><span class=\"bullet\"></span>هندسة الألوان والأحجام: العلب الباكدج اللي لونها أسود أو\n                                أبيض خليها دايماً في \"أول أو آخر الصف\" كإطار بصري شيك، ورتب العلب حسب حجمها عشان الكبيرة\n                                ماتخبيش الصغيرة.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              💻 اللاب توب والـ IT\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>الأجهزة دي بتتجمع وتترتب إما حسب \"البراند\" أو حسب\n                                \"المواصفات\".</li>\n<li><span class=\"bullet\"></span><strong>ليه؟</strong> بيسهل على الضيف المقارنة بين جهازين\n                                في نفس الفئة، وبيسهل عليك إنت خطوة إقناعه بفئة أعلى.</li>\n</div>\n<div data-c=\"174\" style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              📺 الشاشات والغسالات من الأصغر للأكبر:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>ابدأ رص الأجهزة من الحجم الصغير وصولاً للحجم الكبير (مثلاً\n                                من 32 بوصة لـ 75 بوصة، أو من 7 كجم لـ 15 كجم). <strong>وأوعى تنسى</strong> اعرض فقط\n                                المقاسات المعتمدة و<strong style=\"color:#003399;\">كمان تجمع نفس العائلة والمواصفات جنب\n                                  بعض</strong>، عشان تحافظ على تناسق العرض وماتعملش زحمة بصرية للضيف.</li>\n<li><span class=\"bullet\"></span><strong>ليه؟</strong> لأن عين الضيف هتبدأ مع الصغير،\n                                وتلقائياً هتتسحب للحجم الأكبر والمواصفات الأعلى اللي جنبه، ودا بيسهل عليك جداً تقنعه\n                                بالفئة الأعلى.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              ❄️ الثلاجات من الأكبر للأصغر:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>رتب حسب النوع (الأول 4 باب ⬅️ كومبي ⬅️ عادية). وجوه كل نوع\n                                رتب بالسعة اللترية من الأكبر للأصغر.</li>\n<li><span class=\"bullet\"></span><strong>ليه؟</strong> صدمة الانبهار الأولى! لما الضيف يشوف\n                                أعلى وأكبر فئة في الأول، بيحطها كمعيار Benchmark في دماغه وهو بيقارن باقي الأجهزة.</li>\n</div>\n<div data-c=\"175\" style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              🍳 البوتاجازات حسب المقاس ثم السعر:\n                            </div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>جمع كل مقاس لوحده (مثلاً كل الـ 90x60 مع بعض) ورتبهم\n                                تصاعدياً من السعر الأقل للأعلى.</li>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-sales_cards\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"176\" style=\"text-align:center; font-size:22px; margin-bottom:4px;\">\n                              الكروت البيعية</div>\n<div style=\"text-align:center; font-size:18px; font-weight:bold; margin-bottom:15px; color:#003399;\">\n                              🎯 أسلحتك السرية في الإقناع</div>\n<div class=\"content-text\" style=\"text-align:center; margin-bottom:20px; line-height:1.7;\">\n                              كروت التسويق مش مجرد زينة ألوانها حلوة، دي \"طُعم\" بيسهل عليك إغلاق البيعة لو استخدمته\n                              بذكاء وفي مكانه الصح عشان ماتعملش زحمة بصرية للضيف:\n                            </div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              🔥 كارت الأكثر مبيعاً Best Seller &amp; وصل حديثاً New Arrival\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>استخدامه:</strong> ده مفتاحك السحري مع \"الضيف\n                                المتردد\". شاور له على الكارت اللي مكانه أسفل يمين المنتج.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              💸 كارت \"عرض خاص\" السعر قبل وبعد\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong style=\"color:#22c55e;\">المكان الصح:</strong> يوضع\n                                دايماً في الزاوية العلوية اليمنى للمنتج.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#003399;\">السر البيعي:</strong> عين\n                                الضيف وهي بتقرأ كارت المواصفات بتسحب تلقائياً لفوق، فلما يشوف الخصم في الزاوية العلوية\n                                بيحس بقيمة البيعة والتوفير في أول نظرة. عشان كده أوعى تسيب السعر القديم في كارت آخر،\n                                لازم يبقى كارت واحد عليه السعر قبل وبعد.</li>\n</div>\n<div data-c=\"177\" style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              💳 كروت التقسيط زيرو مقدم / بدون فوائد / خصم على الفائدة\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong style=\"color:#22c55e;\">المكان الصح:</strong> يوضع\n                                في الزاوية اليمنى السفلى أو في المنتصف حسب مساحة الجهاز وما يظهره العرض المرئي.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#003399;\">السر البيعي:</strong> بعد\n                                ما الضيف يقتنع بالجهاز ومواصفاته من فوق، عينه بتنزل تحت تدور على التسهيلات وطريقة الدفع،\n                                وهنا كارت الزيرو بيلقط عينه ويشجعه ياخد القرار فوراً.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              🎁 كارت \"هدية مجانية\" أو \"تصفية\" Clearance\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>استخدامه:</strong> اخلق حالة من الاستعجال! حسس\n                                الضيف إن الفرصة دي لو سابها وخرج من الفرع هتضيع عليه، خصوصاً لما يشوف بعينه كارت \"آخر\n                                قطعة\".</li>\n</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-display_rules\" style=\"display:none;\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"178\" style=\"text-align:center; font-size:22px; margin-bottom:4px;\">\n                              قواعد العرض العامة</div>\n<div class=\"content-text\" style=\"text-align:center; margin-bottom:20px; line-height:1.7;\">\n                              عشان تكمل شياكة واجهة بيتك وتضمن إن تجربة الضيف تكون مريحة وآمنة 100%، في شوية تفاصيل\n                              صغيرة بتعمل فرق كبير في العرض المرئي للفرع:\n                            </div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              🏷️ التسعير الشامل قاعدة لا تقبل النقاش:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>مفيش أي منتج في بيتك ينفع يتعرض من غير كارت سعر. المنتج\n                                المجهول بيقلل ثقة الضيف وبيخليه يكسل يسأل ويمشي!</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              🎯 مستوى النظر هو مستوى الشراء:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>خلي دايماً المنتجات \"الأكثر مبيعاً Best-selling\" أو اللي\n                                عليها تركيز في مستوى عين الضيف مباشرة. ده بيخطف عينه فوراً، بيوفر عليه المجهود، وبيسرع\n                                قرار الشراء.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              🛡️ الأمان قبل أي حاجة توزيع الأوزان:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>المنتجات الثقيلة والكراتين الضخمة مكانها دايماً في الرفوف\n                                السفلية أو على الأرض. ده بيحافظ على توازن الاستاندات وبيضمن أمان الضيوف وسلامتك الشخصية.\n                              </li>\n</div>\n<div data-c=\"179\" style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              📏 طابور العرض المحاذاة والترتيب:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>في أقسام الإكسسوارات أو الأجهزة الصغيرة، لازم ترتب العلب\n                                (الباكيدج) بحيث تكون حوافها كلها على خط واحد سواء في أول الرف أو آخره. التنسيق البصري\n                                الدقيق ده بيدي إحساس عالي بالنظام والاحترافية.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              ❄️ التكييفات ليها وضع خاص:\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>في التكييفات بالذات، كارت الخصم دايماً بيتحط في الجهة\n                                المقابلة العكسية لكارت المواصفات. ده بيمنع زحمة الكروت على الوحدة الداخلية وبيخلي الضيف\n                                يشوف تصميم الجهاز واسم البراند بوضوح.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                              ✨ النظافة\n                            </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span>واجهة بيتك لازم تفضل بتلمع! حافظ دايماً على الأجهزة مرتبة\n                                ونظيفة. والأهم إنك تتابع تحديث العرض وتغير الكروت باستمرار عشان تكون متماشية مع أحدث\n                                الحملات الإعلانية New Campaigns اللي الشركة بتنزلها.</li>\n</div>\n</div>\n</div>\n</div>\n</div>\n","words":896},{"id":"house-guard","title":"حارس البيت","group":"الفرع","icon":"shield","html":"\n<div class=\"section-body\">\n<div class=\"main-protocol-tab-content\" id=\"main-protocol-house-guard\">\n<div style=\"background:#f0f4ff; border:1px solid #ccd6f5; border-radius:12px; padding:12px 14px; margin-bottom:16px;\">\n<div class=\"guest-steps\" style=\"flex-wrap: wrap; gap:8px;\">\n<div class=\"guest-step active-step\" data-c=\"180\" onclick=\"showSubProtocolTab('house_guard_protocol', this)\" style=\"cursor:pointer; font-size:12px; padding:10px;\">بروتوكول حارس البيت</div>\n</div>\n</div>\n<div class=\"sub-protocol-tab-content\" id=\"sub-protocol-house_guard_protocol\">\n<div class=\"subsection\">\n<div class=\"subsection-title\" data-c=\"181\" style=\"text-align:center; font-size:22px; margin-bottom:4px;\">\n                              بروتوكول حارس البيت</div>\n<div style=\"text-align:center; font-size:18px; font-weight:bold; margin-bottom:15px; color:#003399;\">\n                              🛡️ أمان فرعك ومكافحة الاحتيال</div>\n<div class=\"content-text\" style=\"text-align:center; margin-bottom:20px; line-height:1.7;\">\n                              \"صاحب البيت\" مش بس بيعرف يبيع ويكبر فاتورته. ده كمان بيعرف يحمي بيته من أي تلاعب أو غش.\n                              وبيحمي نفسه من أي مسألة. ويحمي راية من أي مسألة. الخسارة دي من أي حاجة وبيضيف نفسه منها.\n                              وطبعاً أبسطها وأسهلها (تمويل الاستهلاكي) أو تسهيلات أنظمة التقسيط. دي تسهيلات أحياناً\n                              بيجذب بها الناس الغلط للانتهاز منهم.\n                            </div>\n<li><span class=\"bullet\"></span><strong>التزوير:</strong> تلاعب في البيانات الجوهرية أو في\n                              أرقام القومية (إرسال منفقرات العمل أو النقل التأثير في الرقم القومي نفسه).</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                            2 🧾 قاعدة الـ (KYC) اعرف ضيفك\n                          </div>\n<div class=\"content-text\" style=\"margin-bottom:15px; line-height:1.7;\">\n                            بكل ساطة: \"مافيشعميل مجهول\" قبل ما تبدأ إجراء مالي أو تقسيط، تأكد إنك 100% إن الشخص اللي\n                            واقف قدامك هو فعلاً صاحب البطاقة، وإن بياناته الأصلية صح.\n                          </div>\n<div data-c=\"182\" style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:15px; text-align:center; margin:18px 0 12px 0;\">\n                            3 🔰 الوصايا الذهبية لحماية نفسك (ممنوعات لا تقبل النقاش)\n                          </div>\n<div class=\"content-text\" style=\"margin-bottom:12px; line-height:1.7;\">\n                            التالي ده من صون حقوق دفاعك اللي تباعك للنجاة في جريمة نصب بدون قصد.\n                          </div>\n<div class=\"rule-list\" style=\"margin-bottom:15px;\">\n<li><span class=\"bullet\"></span><strong>راجع الأصل بنفسك:</strong> إياك تقلل أو تضغط على\n                              \"المستند الأصلي\" مستنداً على أي إيرسال فوتو (فيرفيكيشن مرتان) من بره أو ممن بيدعي إنه\n                              تابعها. دي منعتها القانون كلياً.</li>\n<li><span class=\"bullet\"></span><strong>إياك توقع على الضيف:</strong> مهما كانت بياناته تبدو\n                              سليمة أو تعليمات أتته تقسيطية قبل تسجيل الأصلي بمكان الصفقة اللقانونية المباشرة ولوحة الحق\n                              التزوير).</li>\n<li><span class=\"bullet\"></span><strong>لا للتعديل بدون إذن:</strong> لو أي شخص طلب أي أي\n                              شيل أو تعديل أو التعديل في المستند الأصلي في مضمون المستند، فالعميل الأصلي له ملزم للعميل\n                              إلا لو عليه حكم قانوني ملزوم إلا لو تمت الإجراءات الجهة أحكام.\n                              <br/>بعد تمام الإجراءات الجهات لتسليم الجهاز.\n                            </li>\n<li data-c=\"183\"><span class=\"bullet\"></span><strong>🚨 شكوك؟ ارفع سماعة التليفون فوراً</strong> لو أحسست\n                              إن العميل غريب ويدور أو مستنداته مريبة، تليفون فوراً لمديرك أو مستنداته شكلها ملغوب أو\n                              مستنداته شكلها ملعوب فيها هيوجهوك للصح.</li>\n</div>\n<div style=\"background:#eef2f6; border:2px solid #cc0000; padding:15px; border-radius:12px; margin-top:15px;\">\n<div style=\"background:#cc0000; color:white; padding:6px 16px; border-radius:15px; font-weight:bold; text-align:center; width:fit-content; margin:0 auto 10px auto;\">\n                              ⚡ تواصل فوراً مع إدارة مكافحة الاحتيال - Fraud Team</div>\n<div class=\"rule-list\">\n<li><span class=\"bullet\"></span>تواصل فوراً مع إدارة مكافحة الاحتيال (Fraud Team) وفيهم\n                                بشكواك وأسبابها وأدلتها وتأكد من صحة السند.</li>\n</div>\n</div>\n</div>\n</div>\n</div>\n","words":292},{"id":"owner-dictionary","title":"قاموس صاحب البيت","group":"الفرع","icon":"book","html":"\n<div class=\"section-body\">\n<div data-c=\"184\" style=\"font-size:14px; color:#4a5a8a; margin-bottom:15px; text-align:center;\">\n                        عشان تدير بيتك باحترافية وتكون دايماً سايق بخطوة، لازم تكون بتتكلم \"لغة الفرع\" صح. القاموس ده مش\n                        مجرد شوية حروف ومصطلحات، ده \"الكتالوج السري\"\n                      </div>\n<table dir=\"rtl\" style=\"width:100%; border-collapse: collapse; margin-top: 10px; font-size:13px; text-align:right;\">\n<thead>\n<tr style=\"background-color: #1a2f6e; color: white;\">\n<th style=\"padding: 10px; border: 1px solid #d0d8f0;\">الاختصار</th>\n<th style=\"padding: 10px; border: 1px solid #d0d8f0;\">المصطلح الإنجليزي</th>\n<th style=\"padding: 10px; border: 1px solid #d0d8f0;\">💡 تعريفه</th>\n</tr>\n</thead>\n<tbody>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">HA<br/>MDA</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Home Appliances<br/>Medium\n                              Domestic Appliances</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">الأجهزة المنزلية الكبيرة: زي الثلاجات،\n                              الفريزرات، الغسالات وبوتاجازات. دي الأجهزة المعمرة اللي الضيف بياخد وقت عشان يقرر يشتريها.\n                            </td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">SDA</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Small Domestic Appliances\n                            </td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">الأجهزة المنزلية الصغيرة: زي\n                              الميكروويف، والمكنسة و الخلاط والمكوى وأجهزة إعداد الطعام. خد بالك دي أجهزة سريعة وممتازة\n                              جداً لزيادة فاتورتك.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">PC</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Personal Care</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">أجهزة العناية الشخصية: زي ماكينات\n                              الحلاقة، السيشوار، ومكواة الشعر. فئة ممتازة لتقديمها كبدائل أو هدايا.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">AC</td>\n<td data-c=\"185\" dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Air Conditioners</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">أجهزة التكييف: الأجهزة الموسمية اللي\n                              محتاجة تركيز في الشرح على مساحة الغرفة وتقنيات توفير الكهرباء الإنفرتر.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">FL / TL</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Front Load / Top Load</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">أنواع الغسالات: FL تحميل أمامي، و TL\n                              تحميل علوي. مصطلحات سريعة بنستخدمها وإحنا بنشرح للضيف.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">TV / LED</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Televisions / Displays</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">الشاشات: بكل مقاساتها وأنواعها.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">ACC</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Accessories</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">الإكسسوارات: أي كماليات للموبايل أو\n                              اللاب توب زي الساعات الذكية، Smart Wearables، الشواحن والكابلات.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">Dept / Cat</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Department / Category</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">القسم والفئة: بيتك متقسم إدارياً\n                              لأقسام زي التبريد أو الشاشات، وكل قسم تحته فئات زي ديب فريزر أو شاشة ذكية. التقسيمة دي\n                              بتساعدك ترتب أفكارك وتعرض البدايل الصح.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">WH</td>\n<td data-c=\"186\" dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Warehouse</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">المخزن: المكان اللي بتسحب منه أجهزة\n                              الضيف لو مش متاحة في فرعنا. عينك دايماً على رصيد المخزن في السيستم عشان تقفل البيعة بثقة\n                              وتوفر للضيف طلبه.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">VM</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Visual Merchandising</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">العرض المرئي: فن شياكة واجهة بيتك! وهو\n                              طريقة رص الأجهزة وتنسيق الكروت عشان تفتح نفس الضيف وتريّح عينه وهو بيشتري.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">POSM</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Point of Sales Materials\n                            </td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">المواد التسويقية البيعية: دي \"الأسلحة\n                              الصامتة\" بتاعتك! زي كروت الأسعار، كارت \"الأكثر مبيعاً\"، أو \"وصل حديثاً\" اللي بتعلقها على\n                              الجهاز.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">USP</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Unique Selling Proposition\n                            </td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">الميزة التنافسية نقطة البيع الفريدة:\n                              دي \"الخلاصة\" أو السر اللي بيميز الجهاز عن غيره وبيخليه الأنسب لضيفنا زي تقنية تبريد معينة\n                              أو معالج شاشة قوي.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td data-c=\"187\" style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">Attach Rate</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Attach Rate</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">معدل المرفقات ارتباط المبيعات: ده\n                              المؤشر اللي بيقيس شطارتك في الـ Cross-selling! بعت كام إكسسوار مع كل جهاز رئيسي؟ كل ما\n                              تبيع مكملات أكتر، التقييم بتاعك بيعلى.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">ASP</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Average Selling Price</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">متوسط سعر البيع: بيقيس شطارتك في الـ\n                              Up-selling. كل ما تقنع الضيوف بموديلات أعلى وإمكانيات أحسن، متوسط قيمة الفاتورة الـ ASP\n                              بتاعك بيزيد.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">Target</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Daily Target</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">الهدف اليومي: ده التحدي الأساسي بتاعك\n                              كل يوم بتفتح فيه باب الفرع. كل ما تقفل التارجت بدري، كل ما تثبت إنك \"صاحب بيت\" ناجح.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">Ach</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Achievements</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">المحقق الفعلي: العداد اللي بيترجم\n                              مجهودك لمكسب حقيقي، وبيقولك إنت واقف فين بالظبط من التارجت بتاعك.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td data-c=\"188\" style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">MTD</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Month To Date</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">مبيعات الشهر حتى تاريخه: بيعرفك إنت\n                              محقق إيه من التارجت من أول الشهر لحد النهارده. عشان تعرف محتاج تشد حيلك إمتى.</td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">YOY</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Year Over Year</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">المقارنة السنوية: لما مديرك يقولك\n                              فرعنا محقق نمو YOY، معناه إن مبيعاتنا الشهر ده أعلى من نفس الشهر في السنة اللي فاتت. دي\n                              لغة البيزنس عشان تبقى فاهم فرعك بيكبر إزاي.</td>\n</tr>\n<tr style=\"background-color: #f4f6fc;\">\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">Inc</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Incentive</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">العمولة الحافز المادي: مكافأتك\n                              المباشرة على شطارتك في المبيعات وتعبك مع الضيوف. كل ما تكبر فاتورة الضيف، عمولتك بتزيد.\n                            </td>\n</tr>\n<tr>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0; font-weight:bold;\">Contest</td>\n<td dir=\"ltr\" style=\"padding: 10px; border: 1px solid #d0d8f0;\">Contest</td>\n<td style=\"padding: 10px; border: 1px solid #d0d8f0;\">المسابقات البيعية: تحديات بتنزلها\n                              الشركة على براندات أو فئات معينة. دي فرصتك الذهبية عشان تضاعف عمولتك وتثبت إنك بطل\n                              المبيعات في منطقتك!</td>\n</tr>\n</tbody>\n</table>\n</div>\n","words":512},{"id":"delivery","title":"التوصيل للضيف","group":"الفرع","icon":"truck","html":"\n<div style=\"background:#f0f4ff; border:1px solid #ccd6f5; border-radius:12px; padding:16px; margin-bottom:20px; text-align:center;\">\n<h3 data-c=\"189\" style=\"color:#003399; margin-bottom:10px; font-weight:bold; font-size:20px;\">\n                            🚚 💊 بروتوكول التوصيل لراحة ضيفك 🏠\n                          </h3>\n<p style=\"margin:0; font-size:15px; color:#4a5a8a; line-height:1.7;\">\n                            البيعة بتاعتنا مبتنتهيش عند الكاشير، البيعة بتكمل وتنجح لما ضيفك يستلم جهازه لحد باب بيته وهو مبتسم وبدون أي تأخير. عشان كده، فريق التوصيل بيبدأ خطوة جديدة لتسهيل الشحن، ودورك كـ \"صاحب بيت\" إنك تمهدله الطريق بالخطوات دي وأنت بتقفل الأوردر:\n                          </p>\n</div>\n<div class=\"subsection\">\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:18px 0 12px 0; box-shadow: 0 4px 10px rgba(0,51,153,0.2);\">\n                            💬 01 | رقم الواتساب هو مفتاح التوصيل\n                          </div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li><span class=\"bullet\"></span><strong style=\"color:#22c55e;\">الجديد:</strong> العميل هيستقبل رسالة تأكيد وتنسيق على الـ \"واتساب\" الخاص بيه (خطوة احترافية زي شركات الشحن العالمية) عشان نسهل عليه عملية الاستلام.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#cc0000;\">دورك الإلزامي:</strong> لازم تتأكد وتراجع مع العميل إن رقم الموبايل اللي بتسجله على السيستم هو رقمه الأساسي وعليه حساب واتساب شغال.</li>\n</div>\n<div data-c=\"190\" style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:18px 0 12px 0; box-shadow: 0 4px 10px rgba(0,51,153,0.2);\">\n                            📍 02 | العنوان.. تفاصيل التفاصيل (وبالعربي)\n                          </div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li><span class=\"bullet\"></span>سجل عنوان التسليم <strong style=\"color:#003399;\">باللغة العربية</strong> عشان يكون واضح ومتناسق لزميلك مندوب التوصيل.</li>\n<li><span class=\"bullet\"></span><strong style=\"color:#003399;\">الدور ورقم الشقة مش رفاهية!</strong> اكتب العنوان كامل (اسم الشارع، رقم العمارة، الدور، ورقم الشقة، وعلامة مميزة كمان). غياب تفصيلة زي \"الدور\" ممكن تعطل تسليم الأوردر وتعمل تجربة سيئة للعميل.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:18px 0 12px 0; box-shadow: 0 4px 10px rgba(0,51,153,0.2);\">\n                            📝 03 | التفاصيل مهمة مش للزينة\n                          </div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li><span class=\"bullet\"></span>لو ضيفك طلب أي استثناء يخص التوصيل (زي تأجيل ميعاد التسليم ليوم معين، أو التسليم بعد موعد محدد)، <strong style=\"color:#003399;\">لازم تكتب التعليق ده بوضوح</strong> على السيستم عشان فريق المخازن والتوصيل يكونوا في الصورة ويقدموا خدمة تليق باسم راية.</li>\n</div>\n<div style=\"background:linear-gradient(135deg,#003399 0%,#1a3755 100%); color:white; padding:10px 18px; border-radius:12px; font-weight:bold; font-size:16px; text-align:center; margin:18px 0 12px 0; box-shadow: 0 4px 10px rgba(0,51,153,0.2);\">\n                            🔍 04 | الشفافية التامة (العيوب الظاهرية)\n                          </div>\n<div class=\"rule-list\" style=\"margin-bottom:20px;\">\n<li data-c=\"191\"><span class=\"bullet\"></span>لو الجهاز اللي بتبيعه فيه أي خدش أو عيب ظاهري (سواء كان جهاز عرض أو في المخزن وفيه ملحوظة معينة انت عارفها)، <strong style=\"color:#cc0000;\">إلزاماً عليك</strong> تبلغ العميل بيه بوضوح وتأكد عليه قبل إتمام الدفع.</li>\n<li><span class=\"bullet\"></span>الشفافية من البداية بتمنع أي مشاكل أو مرتجعات وقت الاستلام، وبتحافظ على ثقة العميل.</li>\n</div>\n<div style=\"background:#eef2f6; padding:20px; border-radius:12px; margin-top:25px; border-right: 6px solid #f59e0b; box-shadow: 0 4px 15px rgba(0,0,0,0.05); text-align:center;\">\n<div style=\"display:inline-block; background:#f59e0b; color:white; padding:6px 16px; border-radius:20px; font-weight:bold; font-size:14px; margin-bottom:12px;\">\n                              💡 القاعدة الذهبية\n                            </div>\n<h4 data-c=\"192\" style=\"margin:0; font-size:17px; font-weight:bold; color:#1e293b; line-height:1.6;\">\n                              \"الأوردر اللي مكتوب بياناته صح، بيوصل صح.. ريّح زميلك في التوصيل، عشان يريّح عميلك ويرجعلك يشتري تاني!\"\n                            </h4>\n</div>\n</div>\n","words":266}],"chunks":[{"id":0,"sec":"culture","h":"ثقافة راية","t":"الرؤية • الرسالة • القيم الأساسية • ثقافتنا","tabs":[]},{"id":1,"sec":"culture","h":"رؤيتنا","t":"رؤيتنا • أن نكون الشريك التجاري الأكثر تأثيراً وثقة، من خلال وضع معايير جديدة في تجربة العملاء، وتقديم حلول قائمة على القيمة، والتميز في خدمات ما بعد البيع، والتمكين المالي — بما يرسخ شراكات طويلة الأمد تُسهم في تشكيل المستقبل.","tabs":["culture-tab-vision"]},{"id":2,"sec":"culture","h":"مهمتنا","t":"مهمتنا • قيادة تحوّل السوق عبر شراكات استراتيجية، وابتكار مستدام، وحلول تركّز على العميل، بهدف توسيع نطاق الوصول ووضع معايير جديدة للقطاع.","tabs":["culture-tab-mission"]},{"id":3,"sec":"culture","h":"القيم الأساسية","t":"القيم الأساسية","tabs":["culture-tab-values"]},{"id":4,"sec":"culture","h":"التركيز على العملاء","t":"التركيز على العملاء • المبادئ الثابتة التي توجه القرارات","tabs":["culture-tab-values"]},{"id":5,"sec":"culture","h":"التميز","t":"التميز • أفضل الممارسات والمعايير الدولية","tabs":["culture-tab-values"]},{"id":6,"sec":"culture","h":"احترام الآخرين","t":"احترام الآخرين • التوازن بين التكيف والمبادئ","tabs":["culture-tab-values"]},{"id":7,"sec":"culture","h":"العمل الجماعي","t":"العمل الجماعي • قيادة تحوّل السوق عبر شراكات","tabs":["culture-tab-values"]},{"id":8,"sec":"culture","h":"ثقافتنا وقيمنا","t":"ثقافتنا وقيمنا • تلتزم الشركة بتطبيق أفضل الممارسات العالمية في التشغيل، وأمن المعلومات، وإدارة الخدمات، بما يضمن جودة الخدمة واستمرارية الأعمال وفقًا للمعايير الدولية المعتمدة. رغم قدرتنا العالية على التكيف والاستجابة للتغيير، تظل قيمنا الأساسية ثابتة لا تتزعزع.","tabs":["culture-tab-culture"]},{"id":9,"sec":"experience","h":"تجربة العميل","t":"خدمة العميل • تجربة العميل • عوامل التجربة • منظور صاحب البيت","tabs":[]},{"id":10,"sec":"experience","h":"خدمة العميل","t":"خدمة العميل • تقدم للعميل اللي بيدور عليه وتجاوب على أسئلته. ده رد فعل مباشر على طلب واضح.","tabs":["experience-tab-service"]},{"id":11,"sec":"experience","h":"تجربة العميل","t":"تجربة العميل • الرحلة اللي العميل بيعيشها من أول ما بيوصل الفرع لحد خدمة ما بعد البيع. سلسلة بتتجمع وبتكون الإنطباع النهائي عن الشركة. مش مجرد بيع وبس... دي تجربة كاملة.","tabs":["experience-tab-experience"]},{"id":12,"sec":"experience","h":"عوامل التجربة","t":"عوامل التجربة • 🏢 الفرع • • نظافة الفرع والمنتجات • • خريطة عرض المنتجات • • الموسيقى • 👥 الفريق • • الاستقبال والتوديع • • تعامل الفريق مع بعضه • • طريقة التواصل مع العملاء • • المظهر والنظافة الشخصية • • تسهيل الإجراءات","tabs":["experience-tab-factors"]},{"id":13,"sec":"experience","h":"نظرة صاحب البيت لتقديم تجربة ناجحة","t":"نظرة صاحب البيت لتقديم تجربة ناجحة • هنحقق تجربة ناجحة للعميل لما نتعامل بمنظور مختلف.. تكون شايف العميل كأنه ضيفك والضيف دا جايلك بيتك اللي هو الفرع. فتقدمله أحسن تجربة يفضل دايما فاكرك بيها عشان يكون عميل دائم. انت هدفك تكسب العميل مش تكسب بس مجرد عملية البيع. • 🚫 ليس: زبون ✅ العميل = ضيف 🚫 ليس: محل ✅ الفرع = بيتك 🚫 ليس: بياع ✅ استشاري بيع","tabs":["experience-tab-vision"]},{"id":14,"sec":"skills","h":"المهارات الأساسية","t":"الاتصال الفعال • الاستماع الفعال • الحواجز والمظهر","tabs":[]},{"id":15,"sec":"skills","h":"1- مهارة التواصل الفعال","t":"1- مهارة التواصل الفعال • اللي هو القدرة على توصيل أفكارك بطريقة يفهمها العميل بشكل صحيح، من خلال الكلام (لفظي) ومن خلال لغة الجسد ونبرة الصوت (غير لفظي). 93% غير لفظي (لغة الجسد ونبرة الصوت) و7% لفظي (الكلمات). • التواصل غير اللفظي (93%) • التواصل اللفظي (7%)","tabs":["skills-tab-comm"]},{"id":16,"sec":"skills","h":"1- مهارة التواصل الفعال","t":"التواصل البصري: استخدام طريقة المثلث (العينين مع الجبهة) + (العينين مع الأنف) - من 3 لـ 5 ثواني. تجنب النظر للشفاه. • الابتسامة: بنستخدمها في الترحيب، بدون إظهار الأسنان أو المبالغة. لا تُستخدم أثناء غضب العميل. • تعبيرات الوجه: تعبير وجه بشوش ومفرود بدون تكشير. تعبير عن التضامن عند المشكلات. • وضعية الجسد: اتجاه الجسد بكلا الكتفين نحو العميل. استقامة الوقوف وعدم تربيع اليدين. • نبرة الصوت: مستوى صوت متوسط لا عالي ولا منخفض. نبرة مناسبة مع الموقف. تيمبو متوسط. • المسافة مع العميل: 1م (مقدار ذراع) رجل-رجل / امرأة-امرأة. 1.5م (مقدار ذراع ونصف) رجل-امرأة.","tabs":["skills-tab-comm","comm-sub-container-tab-nonverbal"]},{"id":17,"sec":"skills","h":"1- مهارة التواصل الفعال","t":"✅ استخدم حضرتك / فندم / أستاذ / أستاذة / مدام / آنسة • 🚫 لا تستخدم أخويا / باشا / بيه / عسوله / حاج / كبير / غالي / معلم • ✅ بدلاً من الردود المختصرة قل: \"ممكن أستفسر لحضرتك وأرد عليك حالاً\" - \"أقترحلك بديل مناسب\" - \"نشوف مع بعض أنسب حل لحضرتك\" • 🚫 تجنب: ماعرفش / مش موجود / مش عارف / طيب خلاص / مش هينفع / هو ده الموجود / استنى شوية","tabs":["skills-tab-comm","comm-sub-container-tab-verbal"]},{"id":18,"sec":"skills","h":"2- مهارة الاستماع الفعال","t":"2- مهارة الاستماع الفعال","tabs":["skills-tab-listen"]},{"id":19,"sec":"skills","h":"❌ استماع تظاهري","t":"❌ استماع تظاهري • التظاهر بالاستماع من غير تركيز حقيقي. ردود عامة غير مرتبطة بما قيل.","tabs":["skills-tab-listen"]},{"id":20,"sec":"skills","h":"❌ استماع انتقائي","t":"❌ استماع انتقائي • التركيز على أجزاء معينة وتجاهل باقي الرسالة. يوصل انطباع سلبي.","tabs":["skills-tab-listen"]},{"id":21,"sec":"skills","h":"✅ استماع فعال","t":"✅ استماع فعال • الاستماع بتركيز كامل. اسأل أسئلة توضيحية. أعد صياغة الكلام. لا تقاطع.","tabs":["skills-tab-listen"]},{"id":22,"sec":"skills","h":"✅ استماع تضامني","t":"✅ استماع تضامني • يُستخدم عند غضب العميل. إظهار التعاطف مع مشاعره. لا ابتسامة نهائياً.","tabs":["skills-tab-listen"]},{"id":23,"sec":"skills","h":"✅ استماع تضامني","t":"الضغوط والحواجز • المظهر والنظافة","tabs":["skills-tab-barriers"]},{"id":24,"sec":"skills","h":"حواجز تؤثر على المهارات – الضغط","t":"حواجز تؤثر على المهارات – الضغط • حط نفسك مكان العميل: إن العميل مش عارف ضغوطك، متوقع يعيش تجربة حلوة. • افصل نفسك عند انفعالات العملاء: الموضوع مرتبط بسبب الانفعال، العميل بيكون منفعل بسبب إحباط من الخدمة مش منك. • افصل مشاكلك الشخصية عن الشغل: عشان تكون قادر تتعامل مع أي مشكلة. • راقب لغة جسدك: دا محتاج منك تمرين ورقابة على نفسك بشكل مستمر. • اطلب دعم: لو مش قادر تتحكم في الموقف، استعين بزميل أو مديرك.","tabs":["skills-tab-barriers","barriers-sub-container-tab-pressure"]},{"id":25,"sec":"skills","h":"المظهر والنظافة الشخصية","t":"المظهر والنظافة الشخصية • ✅ مسموح به قميص بولو \"راية\" نظيف ومكوي بنطلون جينز غير ممزق أحذية كاجوال أنيقة • 🚫 ممنوع شورت قميص مجعد أو غير نظيف شباشب، أحذية رياضية • النظافة الشخصية: الأظافر – اللحية – الشعر – رائحة الفم – رائحة الجسد","tabs":["skills-tab-barriers","barriers-sub-container-tab-appearance"]},{"id":26,"sec":"guest","h":"منهج GUEST","t":"G Greeting الترحيب • U Understand الفهم • E Expose العرض • S Selling البيع • T Thank الشكر","tabs":[]},{"id":27,"sec":"guest","h":"G – الترحيب (Greeting)","t":"G – الترحيب (Greeting) • هو أول سلوك بيلاحظه العميل منك لما بيدخل الفرع. عشان العميل يحس بأنه مرحب بيه وبيتعامل كضيف جايلك بيتك (الفرع). • ✅ غير لفظي • ابتسامة صادقة مُرحبة • تواصل بصري • وضعية جسم مفتوحة (كلا الكتفين ناحية العميل) • ✅ لفظي 1. صباح الخير / مساء الخير 2. مع حضرتك (اسمك)* 3. أقدر أساعدك ازاي؟** • ⚠️ ماتبدأش بالهزار مع العميل أو تخطي لأي حدود بحجة كسر الحاجز • * انك تَعَرف العميل باسمك ويكلمك بيه دا بيخلق رابطة إنسانية بينك وبينه. ** الألفاظ اللي بتحسس العميل بحسن المعاملة: \"تحت أمرك\" - \"زي ماحضرتك تحب\" - \"اختيار موفق\"","tabs":["guest-tab-G"]},{"id":28,"sec":"guest","h":"U – فهم العميل (Understand)","t":"U – فهم العميل (Understand) • الاستشاري الشاطر هو اللي يعرف يسأل صح فيوصل لاحتياج العميل بسرعة. • Value (القيمة): القيمة الوظيفية / الاقتصادية / الاجتماعية / العاطفية / التجريبية • Pain (الألم): الحاجات اللي بتزعج العميل – تجربة سيئة سابقة – مشكلة سمع عنها • الملاحظة: لاحظ طريقة دخوله ونظراته وتوقفه قدام منتج معين • التساؤل: استخدم الأسئلة المفتوحة أولاً ثم المغلقة • الاستماع الفعال: بعد السؤال بتيجي أهمية الاستماع • ⚠️ لا تحكم مطلقاً على مظهر العميل في قدرته الشرائية أو طريقة الدفع","tabs":["guest-tab-U"]},{"id":29,"sec":"guest","h":"شخصيات العملاء (DISC)","t":"شخصيات العملاء (DISC)","tabs":["guest-tab-U"]},{"id":30,"sec":"guest","h":"D – Dominant (المستعجل/العصبي)","t":"D – Dominant (المستعجل/العصبي) • محدد وحاسم، غير صبور، يحب أن يكون صاحب القرار. افعل: لخص المنتجات بشكل محدد وكن سريعاً. تجنب: لا تفرض رؤيتك، لا تعطيه بدائل كثيرة.","tabs":["guest-tab-U"]},{"id":31,"sec":"guest","h":"I – Influencer (الاجتماعي/الودود)","t":"I – Influencer (الاجتماعي/الودود) • يستخدم لغة جسده كثيراً، يحب يتكلم، مركز الاهتمام. افعل: تفاعل معه وشارك الأمثلة. تجنب: لا تقاطعه، لا تهمل تعليقاته.","tabs":["guest-tab-U"]},{"id":32,"sec":"guest","h":"S – Steady (المتردد/الصامت)","t":"S – Steady (المتردد/الصامت) • مش بيبادر بالكلام، صبور وهادئ، لا يميل للتغيير. افعل: تضامن معه، أخبره رأيك كخبير، أعطه بدائل قليلة. تجنب: لا تضغط عليه، لا تعطيه بدائل كثيرة.","tabs":["guest-tab-U"]},{"id":33,"sec":"guest","h":"C – Cautious (الشكاك/الناصح)","t":"C – Cautious (الشكاك/الناصح) • دقيق ويهتم بالتفاصيل، منطقي وكثير التساؤلات. افعل: كن دقيقاً في معلوماتك، اذكرها بطريقة منطقية. تجنب: لا تتجاهل التفاصيل، لا ترد بإجابات عامة.","tabs":["guest-tab-U"]},{"id":34,"sec":"guest","h":"E – عرض المنتج (Expose)","t":"E – عرض المنتج (Expose) • دور الاستشاري مش بس إنه يبيع مواصفات الجهاز أو يعرض SPECs، دوره إنه يوضح للعميل ازاي المواصفات دي هتفيده هو بالتحديد. • المعلومة والفائدة: اعرض \"المعلومة\" ثم \"الفائدة\" = \"ايه هو\" + \"هيفيدك ازاي\" + \"وهيوفر عليك ايه\" • المشكلة والحل: ابدأ بمشكلة واقعية العملاء ممكن يقابلوها، ثم وضح الحل اللي بيقدمه المنتج • المقارنة: بتوضيح النقاط البيعية في البراندات المختلفة ومساعدة العميل في تحديد أنسب نوع • 🚫 أشهر أخطاء المقارنة: مايسألش عن استخدام العميل / يقارن السعر قبل الأداء / يقول كلام عام من غير أرقام / يميل لبراند واحد / يسيء لبراند معين / يعرض بدائل كثيرة جداً بدون داعي","tabs":["guest-tab-E"]},{"id":35,"sec":"guest","h":"S – المهارات البيعية","t":"S – المهارات البيعية • أ – بيع رأسي عرض نسخة أعلى من نفس نوع المنتج المطلوب (ضمن احتياج العميل) • ب – بيع أفقي عرض منتج آخر (مكمل) للمنتج الأساسي • ج – بيع بديل عند عدم توافر منتج ما، يجب اقتراح بديل قريب في الجودة أو الاستخدام","tabs":["guest-tab-S"]},{"id":36,"sec":"guest","h":"التفاوض","t":"التفاوض • لم يشعر بالقيمة: ارجع لاحتياج العميل، اربط كلامك عن فائدة المنتج بالحاجة اللي هو فعلاً محتاجها • سعر أقل: استخدم التقسيط كحل للعميل للوصول لمنطقة وسط • مقارنة منافس: خصومات بناء على المنافس إذا وُضح إنه نفس المنتج بسعر أقل • ركز على القيمة: لا تبدأ بالسعر، ابدأ بالفائدة. هيوفر ايه على المدى الطويل","tabs":["guest-tab-S"]},{"id":37,"sec":"guest","h":"T – الشكر والتوديع (Thank)","t":"T – الشكر والتوديع (Thank) • إغلاق البيعة: تلخيص مزايا المنتج مع احتياج العميل في النهاية لتأكيد أن هذا هو المنتج المناسب • رسالة Survey: بعد إتمام عملية البيع قبل ما العميل يمشي، لازم نعرفه إنه هيجيله Survey في رسالة SMS على تليفونه • التوديع اللفظي: \"نورتنا يا فندم\" - \"نحب نشوف حضرتك تاني\" • التوديع غير اللفظي: ابتسامة بسيطة – وقفة معتدلة – تواصل بصري مع العميل","tabs":["guest-tab-T"]},{"id":38,"sec":"complaints","h":"التعامل مع الشكاوى","t":"العميل الغاضب • التعامل مع الاعتراض • تصعيد الشكاوى","tabs":[]},{"id":39,"sec":"complaints","h":"عند التعامل مع العميل الغاضب – ثلاث خطوات","t":"عند التعامل مع العميل الغاضب – ثلاث خطوات","tabs":["complaints-tab-angry"]},{"id":40,"sec":"complaints","h":"الوعي","t":"الوعي • قبل أي رد فعل، لازم تكون واعي ليه العميل متضايق: هل المشكلة معايا شخصياً؟ لو كنت مكانه، هل كنت هحس بنفس الانفعال؟","tabs":["complaints-tab-angry"]},{"id":41,"sec":"complaints","h":"التضامن","t":"التضامن • أظهر تعاطفك بتعابير وجه حريصة: \"متفهم موقف حضرتك\" أو \"لو كنت مكانك كنت هحس كده برضه\". تجنب قول كلمات زي \"أهدى\". لا تستخدم ابتسامة أبداً والعميل متعصب.","tabs":["complaints-tab-angry"]},{"id":42,"sec":"complaints","h":"الفهم والحل","t":"الفهم والحل • اسأل أسئلة تساعدك تفهم المشكلة بعمق. رد بطريقة واضحة وصريحة. استخدم كلمات تعكس حرص الشركة: \"احنا في RAYA حريصين على تحقيق رضا حضرتك\".","tabs":["complaints-tab-angry"]},{"id":43,"sec":"complaints","h":"التعامل مع الاعتراض","t":"التعامل مع الاعتراض • الاستماع الجيد + تلخيص الكلام على العميل (عشان يحس أنه فعلاً وصلك رأيه) • شكر العميل على مشاركته لرأيه معنا وأنه رأيه مهم • التأكيد عليه أننا في RAYA بنحرص دايما على التطور والاستماع للعملاء","tabs":["complaints-tab-objection"]},{"id":44,"sec":"complaints","h":"تصعيد الشكاوى – المسار الرسمي (أقصى 48 ساعة)","t":"تصعيد الشكاوى – المسار الرسمي (أقصى 48 ساعة)","tabs":["complaints-tab-escalation"]},{"id":45,"sec":"complaints","h":"الموظف (الوجهة الأولى)","t":"الموظف (الوجهة الأولى) • استقبال شكوى العميل ومحاولة الحل الفوري","tabs":["complaints-tab-escalation"]},{"id":46,"sec":"complaints","h":"مدير الفرع","t":"مدير الفرع • يتدخل ويحاول حل المشكلة إذا لم يتم الحل","tabs":["complaints-tab-escalation"]},{"id":47,"sec":"complaints","h":"مدير المنطقة","t":"مدير المنطقة • يتخذ قراراً فورياً","tabs":["complaints-tab-escalation"]},{"id":48,"sec":"complaints","h":"مدير المبيعات","t":"مدير المبيعات • المراجعة النهائية واتخاذ القرار – الحل المرضي لجميع الأطراف • ⏱️ إجمالي الوقت المسموح لجميع مراحل التصعيد: 48 ساعة كحد أقصى","tabs":["complaints-tab-escalation"]},{"id":49,"sec":"policies","h":"السياسات","t":"سياسة الاستبدال والاسترجاع • Omni-Channel • C-SAT vs NPS • مكافآت العملاء • عناوين الصيانة • صيانة راية والوكيل","tabs":[]},{"id":50,"sec":"policies","h":"السياسات","t":"الإطار الزمني • شروط القبول • إرجاع الفلوس","tabs":["main-policy-exchange"]},{"id":51,"sec":"policies","h":"الإطار الزمني للاسترجاع","t":"الإطار الزمني للاسترجاع • المدة • الشرط • نوع الحق • 14 يوم • المنتج بحالته الأصلية (مقفول ومتبرشم) • تغيير الرأي • 30 يوم • تقديم \"تقرير فني\" من وكيل المنتج يُثبت العيب • عيوب الصناعة","tabs":["main-policy-exchange","sub-policy-timeframe"]},{"id":52,"sec":"policies","h":"شروط قبول الاسترجاع","t":"شروط قبول الاسترجاع • الفاتورة أولاً: فاتورة الشراء هي جواز السفر لأي عملية استرجاع • الأجهزة الذكية (الموبايل والتابلت): العلبة لازم تكون متبرشمة ولم يتم فتحها أو تفعيل الجهاز • منتجات العناية الشخصية: لأسباب صحية بحتة، لا تُسترجع ولا تُستبدل بمجرد فتح علبتها (إلا في حالة إثبات عيب صيانة) • سوء النقل والاستلام: لو العميل نقل الجهاز بشكل خاطئ وتضرر، هنا بنعتذر بلباقة عن الاسترجاع","tabs":["main-policy-exchange","sub-policy-conditions"]},{"id":53,"sec":"policies","h":"طريقة إرجاع الفلوس","t":"طريقة إرجاع الفلوس • 💵 كاش العميل بيستلم قيمة المنتج نقداً من أي فرع من فروعنا • 💳 فيزا/بطاقة المبلغ بيرجع لحسابه خلال 14 يوم عمل عبر طلب Remedy","tabs":["main-policy-exchange","sub-policy-refund"]},{"id":54,"sec":"policies","h":"Omni-Channel – راية كلها بيت واحد","t":"Omni-Channel – راية كلها بيت واحد • معناها إننا بنقدم للضيف أفضل خدمة من خلال كل قنوات بيع راية، سواء كان أونلاين، في الفرع، أو عن طريق الكول سنتر. • سيناريو 1: المنتج مش عندي → ابحث في الفروع التانية، اعرض الحجز والدفع في فرعك والاستلام من الفرع الآخر • سيناريو 2: ضيف الأونلاين والكول سنتر → رحب بيه جداً واطلب رقم الأوردر وسلمه المنتج فوراً • سيناريو 3: شراء المنتج من فرع آخر واسترجاعه → رحب بيه واستلم المرتجع فوراً • سيناريو 4: المنتج مش في الفروع نهائياً → افتح راية شوب Online وساعد العميل يطلبه • 📞 للاستعلام والاستفسار: 19900","tabs":["main-policy-omni"]},{"id":55,"sec":"policies","h":"C-SAT vs NPS – مقياس نجاح صاحب البيت","t":"C-SAT vs NPS – مقياس نجاح صاحب البيت • 😊 C-SAT (رضا العميل) مدى رضاه عن تجربته الآن. الهدف: رضا فوري. الحساب: عدد التقييمات الإيجابية ÷ إجمالي عدد التقييمات × 100 • 📣 NPS (ولاء العميل) مدى احتمالية ترشيحه لراية. الهدف: ولاء دائم. الحساب: % المروجين (9-10) - % المنتقدين (0-6) • الـ CSAT بيقيس نجاحك في بيعة النهاردة، لكن الـ NPS بيقيس نجاحك في بناء علاقة دائمة مع العميل.","tabs":["main-policy-csat"]},{"id":56,"sec":"policies","h":"برنامج مكافآت لعملاء راية","t":"برنامج مكافآت لعملاء راية","tabs":["main-policy-rewards"]},{"id":57,"sec":"policies","h":"أمسح الكود","t":"أمسح الكود • 📱 Scan Me","tabs":["main-policy-rewards"]},{"id":58,"sec":"policies","h":"عناوين مراكز صيانة راية","t":"عناوين مراكز صيانة راية • القاهرة والجيزة • مدينة نصر: 1 شارع عبد الحميد لطفي - آخر مكرم عبيد - راية • شبرا: 57 ش شبرا - بجوار بنك مصر - ميجا ستور راية • جسر السويس: 43 شارع الليث من جسر السويس - أمام عمارات الميرلاند - راية • الهرم: 166 شارع الهرم - بجوار شارع العريش - راية • الدقي: 14 ش مصدق - راية • محافظات أخرى • الإسكندرية: برج 7 أبراج الصيادلة - شارع جامع حاتم - بجوار مديرية الأمن - راية • الزقازيق: شارع د/ طلبة عويضة - برج أديب - راية • أسيوط: 14 ب ش الجمهورية - ميجا ستور راية • طنطا: ش المديرية - مبنى عمر أفندي - الدور الأول - ميجا ستور راية • المنصورة: 22 ش الجمهورية - برج النورس - أمام جامعة المنصورة - راية","tabs":["main-policy-maintenance_centers"]},{"id":59,"sec":"policies","h":"عناوين مراكز صيانة راية","t":"الأقصر: ش التلفزيون مع ش المدينة المنورة - ميجا ستور راية • فروع التجميع • الإسماعيلية: 37 شارع الإسكندرية - بجوار المحطة الجديدة - هاي تك • السويس: 31 شارع الجيش - بجوار مسجد الأربعين - سيد عوض • المنيا: ش طه حسين - أمام النادي الرياضي - العالمية • المنيا: شارع الجمهورية - أمام مطعم الهادي - مغاغة - ستار • للاستعلام والاستفسار يرجى الاتصال على 19900","tabs":["main-policy-maintenance_centers"]},{"id":60,"sec":"policies","h":"صيانة راية & صيانة الوكيل","t":"صيانة راية & صيانة الوكيل • من أهم أدوارك كـ \"صاحب بيت\" إنك تبلغ ضيفك بمراكز الصيانة من غير ما يسأل وكمان تقف جنب ضيفك لو جهازه حصله مشكلة بعد البيع. عشان توجه العميل صح وبثقة، دي الخريطة الكاملة والمعتمدة لكل الماركات: • 1. أجهزة صيانتها في \"بيتنا\" بتدخل صيانة راية وتُتابع عبر الكول سنتر 19900 📞 • البراندات دي العميل بيسلمها لينا أو بيتابعها معانا مباشرة: • الموبايلات والإكسسوارات (HHP) • ACE, AllCall, Aukey, Benco, CMF, HMD, Hoco, Huawei, IKU, Infinix, itel, Lenovo, Micromax, Motorola, Nokia, Nothing, Oraimo, TECNO, SARY • أجهزة التكنولوجيا واللاب توب (IT) • Asus, Canon, Lexmark, Xerox, MSI","tabs":["main-policy-raya_dealer"]},{"id":61,"sec":"policies","h":"صيانة راية & صيانة الوكيل","t":"الشاشات (TV) • Beko, SARY • الأجهزة المنزلية الصغيرة والعناية • Braun, DELONGHI, Kenwood, Philips, SARY • 2. أجهزة صيانتها عند \"الوكيل الخارجي\" Call Service Provider ⚙️ • البراندات دي بتوجه العميل يتواصل مباشرة مع خدمة عملاء الوكيل المختص لتوفير وقته لأنهم أسرع في التعامل معاها: • سامسونج (Samsung): تحول للوكيل لجميع المنتجات 📞 19580 • بيكو (Beko): الأجهزة المنزلية الكبيرة والتكييفات تحول للوكيل الخارجي 📞 16165 (الشاشات والأجهزة الصغيرة صيانة داخلية راية) • كونتكس (Contex): الشاشات (TV) تحول للوكيل الخارجي للشاشات 📞 19501","tabs":["main-policy-raya_dealer"]},{"id":62,"sec":"policies","h":"📌 خد بالك:","t":"📌 خد بالك: • \"لما العميل يجيلك بعطل، متقولوش روح للتوكيل وتسيبه يمشي. افتح الدليل ده،\" • ولو الجهاز تبعنا قوله: \"يا فندم الجهاز ده صيانته تبعنا، ونبلغه أقرب عنوان لمراكز الصيانة القريب منه\" وكمان حضرتك تقدر تكلم 19900 • ولو تبع الوكيل قوله: \"الجهاز ده صيانته بتتم أسرع من خلال التوكيل المعتمد\".. توجيهك الدقيق هو خدمة ما بعد البيع الحقيقية!","tabs":["main-policy-raya_dealer"]},{"id":63,"sec":"protocols","h":"بروتوكولات التقسيط والتمويل","t":"بروتوكولات راية • بروتوكولات التقسيط","tabs":[]},{"id":64,"sec":"protocols","h":"بروتوكولات التقسيط والتمويل","t":"صاحب البيت • النظافة • الانتشار • الإغلاق","tabs":["main-protocol-raya"]},{"id":65,"sec":"protocols","h":"بروتوكول \"صاحب البيت\"","t":"بروتوكول \"صاحب البيت\" • الفرع مش مجرد مكان بنبيع فيه، ده \"بيتنا\" اللي بنستقبل فيه ضيوفنا كل يوم. وعشان التجربة تكون مثالية، لازم يكون عندنا نظام واضح من أول دقيقة بنفتح فيها الباب لحد ما نقفله. • 9:30 صباحاً: الاستعداد لبدء العمل","tabs":["main-protocol-raya","sub-protocol-owner"]},{"id":66,"sec":"protocols","h":"تأكد من تواجد جميع أفراد الفريق","t":"تأكد من تواجد جميع أفراد الفريق • تجهيز الفرع: تشغيل الإضاءة، التكييف، وأجهزة العرض","tabs":["main-protocol-raya","sub-protocol-owner"]},{"id":67,"sec":"protocols","h":"مراجعة سريعة للأهداف اليومية","t":"مراجعة سريعة للأهداف اليومية • مظهر الموظف المحترف (سياسة الملابس) • ✅ المسموح به • قميص بولو \"راية\" نظيف ومكوي • بنطلون جينز غير ممزق • أحذية كاجوال أنيقة • ❌ الممنوع • شورت • قميص مجعد أو غير نظيف • شباشب، أحذية رياضية • 10:00 صباحاً: فتح الأبواب للعملاء • فتح أبواب الفرع واستقبال العملاء بابتسامة واحترافية • (الضيف الأول زي الضيف الأخير، بياخد أحسن خدمة)","tabs":["main-protocol-raya","sub-protocol-owner"]},{"id":68,"sec":"protocols","h":"بروتوكول النظافة واجهة بيتك","t":"بروتوكول النظافة واجهة بيتك • النظافة مش بتمشي لوحدها، \"متابعة\" صاحب البيت هي السر. • صاحب البيت بيفكر عامل النظافة بمسؤوليته • تذكير يومي بجميع نقاط النظافة (التأكد من النظافة بعد الانتهاء) • المسؤولية هنا هي \"المتابعة\" من صاحب البيت لكل تفصيلة. • متابعة نظافة الفرع • الموبايلات خالية من البصمات • الشاشات بتلمع بوضوح • الأرفف مترتبة بشكل مثالي","tabs":["main-protocol-raya","sub-protocol-clean"]},{"id":69,"sec":"protocols","h":"القاعدة الذهبية: متى وكيف؟","t":"القاعدة الذهبية: متى وكيف؟ • النظافة بتتعمل \"قبل\" دخول العملاء أو في أوقات الهدوء... إياك تمسح أو تنظف والضيف واقف قدامك! • ✅ قبل دخول العملاء / أوقات الهدوء (CORRECT) • ❌ أوقات دخول العملاء (WRONG / NO!)","tabs":["main-protocol-raya","sub-protocol-clean"]},{"id":70,"sec":"protocols","h":"بروتوكول الانتشار","t":"بروتوكول الانتشار • أولاً: حسب حجم الفرع عادي ولا ميجا؟ • الفروع العادية: المناطق والتغطية السريعة • طريقة: الفرع بيتقسم لمناطق، وكل موظف مسؤول عن منطقة بس عينه على الفرع كله. • لو زميلك مشغول مع ضيف، إنت بتتحرك فوراً تغطي مكانه عشان مفيش ضيف يدخل وميلاقيش حد يستقبله. • فروع الميجا الأدوار المتعددة: الأدوار والمسؤوليات • موظف الاستقبال: أهم شخص في الفرع الميجا! لازم يكون فيه استاف متمركز على الباب الرئيسي، بيستقبل الضيف، يرحب بيه، ويوجهه للدور أو القسم الصح فوراً. • قائد لكل دور: كل دور لازم يكون فيه موظف ثابت مبيسيبوش، عشان العميل ميطلعش السلم ويلاقي الدور فاضي.","tabs":["main-protocol-raya","sub-protocol-deploy"]},{"id":71,"sec":"protocols","h":"بروتوكول الانتشار","t":"بروتوكول تسليم الضيف عبر الأدوار (التسليم): \"اتفضل، مع حضرتك (اسم الشخص) من (القسم أو البراند) هيساعدك في كل اللي تحتاجه\". • ثانياً: حسب موقع الفرع شارع ولا مول؟ • فروع الشارع: الترافيك والواجهة • الترافيك بييجي على فترات، وفي أوقات الذروة بيكون مكثف. • الاستاف متواجد في النصف الأول كل من الفرع (الواجهة). • بيدي تشجيع للناس إنها تدخل. • فروع المولات: الوقت والتوزيع • عميل المول غالباً وقته أضيق وبيلف على محلات كتير وبيعمل مقارنات سريعة. • التوزيع هنا بيعتمد على 30 ثانية \"سرعة الالتقاط\". • (تأكد من وجود استاف في واجهة فروع الشارع، وركز على سرعة الالتقاط في أول 30 ثانية في المول.)","tabs":["main-protocol-raya","sub-protocol-deploy"]},{"id":72,"sec":"protocols","h":"بروتوكول الاغلاق","t":"بروتوكول الاغلاق • آخر ضيف • الضيف الأهم: لو عميل دخل الفرع قبل موعد الإغلاق بدقيقة واحدة، بيتعامل كأنه أول عميل في اليوم. • ممنوع تماماً نقفل الأنوار أو نلم الأجهزة أو نحسسه إننا مستعجلين. • بعد خروج آخر ضيف • ترتيب الفرع عشان زمايلنا بتوع الشفت الصباحي ييجي يلاقيه جاهز بنسبة 100%. • (الضيف الأخير زي الضيف الأول، بياخد أحسن خدمة وتوديع يليق ببيتنا.)","tabs":["main-protocol-raya","sub-protocol-close"]},{"id":73,"sec":"protocols","h":"بروتوكول الاغلاق","t":"بروتوكول التقسيط • مقابل بطاقة • مقابل حد ائتماني • راتب افتراضي • تمويل غير المؤمن عليهم","tabs":["main-protocol-installment"]},{"id":74,"sec":"protocols","h":"بروتوكول التقسيط","t":"بروتوكول التقسيط • في Raya، إحنا بنسهل على العميل يشتري اللي نفسه فيه، بس كـ \"صاحب بيت\" شاطر، لازم تبقى عارف إزاي تختار البرامج الصح والورق المظبوط عشان العملية تمشي بسرعة وبدون أخطاء. دي قواعدنا الثابتة:","tabs":["main-protocol-installment","sub-protocol-inst_1"]},{"id":75,"sec":"protocols","h":"1. برنامج الأفراد العميل الأساسي","t":"1. برنامج الأفراد العميل الأساسي • السن: من 21 لحد 65 سنة. وممكن لحد 67 سنة لو جاب ضامن درجة أولى. • الدخل: الحد الأدنى لدخله الشهري 3000 جنيه. • لو هيقسط بالبطاقة بس مكتوب فيها الوظيفة: بنعتمدها بس لازم دخله كحد أدنى يكون 7000 جنيه. • مدة الشغل: لازم يكون بقاله في وظيفته الحالية 3 شهور على الأقل. • عبء الدين DBR: أقساط العميل كلها متعديش 50% من دخله. • الوظائف الحكومية المؤقتة: بنقبلها بشرط يجيب برنت تأميني ودخله لا يقل عن 7000 جنيه. لو دخله أعلى، لازم يجيب مفردات مرتب + ضامن درجة أولى.","tabs":["main-protocol-installment","sub-protocol-inst_1"]},{"id":76,"sec":"protocols","h":"2. إمتى بنحتاج نعمل \"زيارة ميدانية\" للعميل؟","t":"2. إمتى بنحتاج نعمل \"زيارة ميدانية\" للعميل؟ • في حالات معينة لازم فريقنا يزور العميل للتأكد، وهي: • العميل بدون عمل أو ربة منزل. • البطاقة مش مكتوب فيها وظيفة. • العميل ملوش تاريخ ائتماني أو أول مرة يقسط عدم وجود I-Score. • لو العميل بيقدم الطلب من فرع خارج محافظة سكنه.","tabs":["main-protocol-installment","sub-protocol-inst_1"]},{"id":77,"sec":"protocols","h":"3. إثبات الدخل: إيه الورق اللي بنقبله؟","t":"3. إثبات الدخل: إيه الورق اللي بنقبله؟ • المقبول 100% • مفردات مرتب مختومة وحديثة، صلاحيتها 3 شهور من تاريخها. • كشف حساب بنكي لآخر 6 شهور باين فيه تحويل الراتب. • الـ Payslip، بنجيب بتاع الشهر الحالي + واحد أقدم. • رسالة SMS موثقة من جهة العمل فيها صافي القبض. • برنت تأميني حديث مكملش 3 شهور، مختوم بختم النسر أو طالع من \"مصر الرقمية\"، ومكتوب فيه اسم الشركة وآخر أجر تأميني. • بيان معاش خلال 3 شهور ومختوم بختم النسر. • حاجات بتسند دخل إضافي بجانب الأساسي: شهادات استثمار أو ودائع باسمه، أو عقود إيجار بتدخله فلوس فعلية. • لتعليات الليمت Limit Increase: لو العميل عاوز يزود الرصيد لازم يجيب أي إثبات دخل جديد من اللي ذكرناهم.","tabs":["main-protocol-installment","sub-protocol-inst_1"]},{"id":78,"sec":"protocols","h":"4. برامج تانية لضيوفنا","t":"4. برامج تانية لضيوفنا • برنامج أصحاب الأعمال Self-Employed: للنشاط القائم. بيحتاج سجل تجاري + كشف حساب 6 شهور + زيارة ميدانية للسكن والنشاط. • برنامج الشركاء Partners: نفس شروط أصحاب الأعمال بالظبط، بس بنزود عليها \"مستند رسمي\" يوضح نسبة ملكية العميل في الشركة دي. • برنامج جيل Z للطلاب: لطلبة الجامعات الحكومية والخاصة المحددة. الضامن: الأب أو الأم بوظيفة مثبتة. الورق المطلوب: كارنيه الطالب + بطاقة الضامن + إثبات دخل الضامن. والحد الائتماني هنا بيتحدد بناءً على دخل الأسرة.","tabs":["main-protocol-installment","sub-protocol-inst_1"]},{"id":79,"sec":"protocols","h":"5. خطوط حمراء: المحظورات عشان نحمي بيتنا","t":"5. خطوط حمراء: المحظورات عشان نحمي بيتنا • مناطق لا نقسط لها Blacklisted Areas: شمال سيناء، حلايب وشلاتين، الواحات، مرسى مطروح، قنطرة شرق. • مهن لا نقسط لها Blacklisted Professions: ضباط الشرطة إلا لو مدنيين، الصحفيون، موظفو هيئة الإسعاف، والمحامي الحر / المستقل بنقبل المحامي بس لو بطاقته مكتوب فيها إنه موظف جوه شركة. • ورق مرفوض تماماً: شهادة الدخل من أي محاسب قانوني، أو الوظائف الحكومية بنظام \"اليومية\".","tabs":["main-protocol-installment","sub-protocol-inst_1"]},{"id":80,"sec":"protocols","h":"6. ضيوفنا الغاليين ذوي الاحتياجات الخاصة","t":"6. ضيوفنا الغاليين ذوي الاحتياجات الخاصة • بالنسبة للعملاء من المكفوفين، بنرحب بيهم جداً، ولكن لتسهيل وتأمين الإجراءات يُشترط وجود \"ضامن درجة أولى\" الزوج أو الزوجة.","tabs":["main-protocol-installment","sub-protocol-inst_1"]},{"id":81,"sec":"protocols","h":"💳 بروتوكول \"حد ائتماني مقابل بطاقة\"","t":"💳 بروتوكول \"حد ائتماني مقابل بطاقة\"","tabs":["main-protocol-installment","sub-protocol-inst_2"]},{"id":82,"sec":"protocols","h":"إزاي نقسط لضيفنا بناءً على كارت المشتريات؟","t":"إزاي نقسط لضيفنا بناءً على كارت المشتريات؟ • لو ضيفنا معاه بطاقة ائتمان Credit Card وعاوز يعتمد عليها عشان ياخد حد ائتماني يقسط بيه عندنا، دي الشروط اللي لازم نمشي عليها عشان نسهلها عليه ونحفظ حق \"بيتنا\":","tabs":["main-protocol-installment","sub-protocol-inst_2"]},{"id":83,"sec":"protocols","h":"1. مين الضيف اللي يقدر يستفيد من البرنامج ده؟","t":"1. مين الضيف اللي يقدر يستفيد من البرنامج ده؟ • السن: لازم يكون عمره من 21 سنة كحد أدنى، لحد 65 سنة كحد أقصى. • التعليم: البرنامج ده مخصص للضيوف الحاصلين على مؤهل جامعي بكالوريوس أو ليسانس. • الشغل: لازم يكون بقاله في وظيفته 6 شهور على الأقل وبنتأكد من ده من البطاقة، أو التأمينات، أو منصة مصر الرقمية. • مهن مش هينفع معاها البرنامج: الفنيين، العمالة اليدوية، السائقين، تجار الخضار والفاكهة، الجزارين، والمزارعين / الجناينية. • الورق المطلوب: أسهل حاجة.. بطاقة رقم قومي سارية وبس!","tabs":["main-protocol-installment","sub-protocol-inst_2"]},{"id":84,"sec":"protocols","h":"2. الفحص الائتماني I-Score: هو لميزان بتاعنا","t":"2. الفحص الائتماني I-Score: هو لميزان بتاعنا • لازم نعمل استعلام إلزامي. • بطاقة الائتمان بتاعة العميل لازم تكون من النوع \"الغير مضمنة\" Unsecured. • العميل لازم يكون عنده بطاقة ائتمان حقيقية مبنية على ثقة البنك فيه مش بطاقة معمولها إصدار بضمان فلوس محجوزة.","tabs":["main-protocol-installment","sub-protocol-inst_2"]},{"id":85,"sec":"protocols","h":"3. تفاصيل التمويل والمدة","t":"3. تفاصيل التمويل والمدة • عبء الدين DBR: زي ما إحنا متعودين، أقساط الضيف كلها متعديش 50% من دخله. • مدة التقسيط: بتبدأ من 10 شهور لحد 36 شهر.","tabs":["main-protocol-installment","sub-protocol-inst_2"]},{"id":86,"sec":"protocols","h":"💳 بروتوكول \"الحد الائتماني مقابل الحد الائتماني\"","t":"💳 بروتوكول \"الحد الائتماني مقابل الحد الائتماني\"","tabs":["main-protocol-installment","sub-protocol-inst_3"]},{"id":87,"sec":"protocols","h":"التقسيط بضمان ليميت شركات تانية","t":"التقسيط بضمان ليميت شركات تانية • لو ضيفنا معندوش بطاقة ائتمان بنكية، بس عنده ليميت تقسيط شغال مع شركات تانية معتمدة نقدر نعتمد عليه ونديله ليميت يشتري بيه من عندنا. دي القواعد اللي هنمشي عليها:","tabs":["main-protocol-installment","sub-protocol-inst_3"]},{"id":88,"sec":"protocols","h":"1. مين الضيف اللي يقدر يستفيد من البرنامج ده؟","t":"1. مين الضيف اللي يقدر يستفيد من البرنامج ده؟ • السن: لازم يكون عمره من 21 سنة كحد أدنى، لحد 65 سنة كحد أقصى. • التعليم: البرنامج ده مخصص للضيوف الحاصلين على مؤهل جامعي بكالوريوس أو ليسانس. • الشغل: لازم يكون بقاله في وظيفته 6 شهور على الأقل وبنتأكد من ده من البطاقة، أو التأمينات، أو منصة مصر الرقمية. • مهن مش هينفع معاها البرنامج: الفنيين، العمالة اليدوية، السائقين، تجار الخضار والفاكهة، الجزارين، والمزارعين / الجناينية. • الورق المطلوب: أسهل حاجة.. بطاقة رقم قومي سارية وبس!","tabs":["main-protocol-installment","sub-protocol-inst_3"]},{"id":89,"sec":"protocols","h":"2. الفحص الائتماني I-Score: هو لميزان بتاعنا","t":"2. الفحص الائتماني I-Score: هو لميزان بتاعنا • لازم نعمل فحص إلزامي للـ I-Score.","tabs":["main-protocol-installment","sub-protocol-inst_3"]},{"id":90,"sec":"protocols","h":"3. تفاصيل التمويل والمدة","t":"3. تفاصيل التمويل والمدة • حجم العملية: الحد الأدنى لمبلغ التمويل Ticket Size هو 25,000 جنيه مصري. • مدة السداد: Tenor التقسيط متاح من 10 شهور لحد 36 شهر. • عبء الدين DBR: زي ما إحنا متعودين، أقساط الضيف كلها متعديش 50% من دخله.","tabs":["main-protocol-installment","sub-protocol-inst_3"]},{"id":91,"sec":"protocols","h":"5. إيه هي الشركات المعتمدة عندنا؟","t":"5. إيه هي الشركات المعتمدة عندنا؟ • بنقبل الليميت من الشركات دي فقط • أمان Aman • فاليو Valu • سهولة Souhoula • كليفر Clever • حالاً Halan • ترو True","tabs":["main-protocol-installment","sub-protocol-inst_3"]},{"id":92,"sec":"protocols","h":"بروتوكول دخل الراتب الافتراضي","t":"بروتوكول دخل الراتب الافتراضي","tabs":["main-protocol-installment","sub-protocol-inst_4"]},{"id":93,"sec":"protocols","h":"إزاي نقسط بالوظيفة","t":"إزاي نقسط بالوظيفة • البرنامج ده بقى معمول عشان نسهّل على ضيوفنا اللي معندهمش إثبات دخل مباشر، بس شغالين في وظايف ممتازة ومستقرة. الهدف هنا إننا نحدد الليميت للعميل بناءً على متوسط رواتب السوق لمهنته عشان تناسب أسعار الإلكترونيات عندنا.","tabs":["main-protocol-installment","sub-protocol-inst_4"]},{"id":94,"sec":"protocols","h":"1. مين الضيف المؤهل للبرنامج؟ شروط الموافقة السريعة","t":"1. مين الضيف المؤهل للبرنامج؟ شروط الموافقة السريعة • عشان تدخل العميل في البرنامج ده، لازم تنطبق عليه الشروط دي: • السن: من 21 عاماً إلى 65 عاماً كحد أقصى. • التعليم: مؤهل جامعي بكالوريوس / ليسانس. • مدة العمل: لا تقل عن 3 أشهر يتم التحقق عبر ظهر البطاقة، التأمينات، أو بوابة مصر الرقمية. • استثناء بسيط للموظف المبتدئ Junior: لو شغال في القطاع الحكومي بقاله أقل من 6 شهور، لازم نسأله عن قيمة دخله الفعلي وبنفصح عنه صراحةً. • مهن خارج البرنامج: الفنيين، العمالة اليدوية، السائقين، بائعي الخضروات والفاكهة، الجزارين، والجناينية.","tabs":["main-protocol-installment","sub-protocol-inst_4"]},{"id":95,"sec":"protocols","h":"2. الفحص الائتماني I-Score الميزان بتاعنا","t":"2. الفحص الائتماني I-Score الميزان بتاعنا • لازم نعمل استعلام إلزامي.","tabs":["main-protocol-installment","sub-protocol-inst_4"]},{"id":96,"sec":"protocols","h":"3. تفاصيل التقسيط","t":"3. تفاصيل التقسيط • عبء الدين DBR: أقساط الضيف كلها متعديش 50% من الدخل الافتراضي اللي هنحسبهوله. • مدة التقسيط: التقسيط متاح من 10 شهور لحد 36 شهر.","tabs":["main-protocol-installment","sub-protocol-inst_4"]},{"id":97,"sec":"protocols","h":"3. تفاصيل التقسيط","t":"أكاديمية راية للتجزئة · مهارة في كبسولة","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":98,"sec":"protocols","h":"العميل اللي مش مؤمن عليه… ليه طريق للتقسيط","t":"العميل اللي مش مؤمن عليه… ليه طريق للتقسيط • برنامجين تمويل لازم تكون حافظهم: سواقين أوبر وديدي وإن درايفر، وأصحاب الكروت الطبية من شركات التأمين.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":99,"sec":"protocols","h":"المهارة في جملة","t":"المهارة في جملة • لما العميل يقولك «أنا مش متأمن عليا»، ما تقفلش الكلام. اسأله بيشتغل إيه، ولو سواق على تطبيق أو معاه كارت طبي، اطلب منه الورق الصح من أول مرة. • ليه مهمة للعميل؟ بياخد الجهاز اللي محتاجه بالتقسيط، ومن غير ما يرجع البيت يجيب ورق ناقص. • ليه مهمة ليك؟ بيعة كانت هتضيع بتتقفل، والملف بيعدّي من أول مرة من غير رفض أو تأخير.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":100,"sec":"protocols","h":"البرنامج الأول","t":"البرنامج الأول","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":101,"sec":"protocols","h":"سواقين أوبر وديدي وإن درايفر","t":"سواقين أوبر وديدي وإن درايفر • العميل بيشتغل على عربيته في تطبيق توصيل ركاب • السن • 30 سنة لحد 60 سنة • مدة التقسيط • 10 شهور لحد 36 شهر • إثبات الدخل • اختار واحد بس من الاتنين: • الطريقة الأولى كشف صافي أرباح آخر 6 شهور من التطبيق + فيديو من التطبيق يظهر فيه بيانات العميل • الطريقة التانية كشف حساب بنكي آخر 6 شهور فيه تحويلات الدخل، ويعتمده قسم الـFRMU • ورق لازم في كل الحالات • بطاقة رقم قومي سارية • العميل هو مالك العربية وصاحب الرخصة • رخصة العربية سارية 6 شهور على الأقل وتغطي مدة التقسيط كلها (يعتمدها الـFRMU) • موديل العربية ما يزيدش عن 10 سنين • حساب الدخل • متوسط صافي الإيرادات المحولة في آخر 6 شهور.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":102,"sec":"protocols","h":"سواقين أوبر وديدي وإن درايفر","t":"لو العميل كمان بياخد مرتب الدخل = متوسط المرتب + متوسط دخل التطبيقات • الشغل والتحقق • شغال على التطبيق من 6 شهور على الأقل ، وده بيبان من كشف التطبيق أو فيديو يوضح تاريخ إنشاء الحساب • زيارة منزلية إلزامية لحد ما نظام الـDVS الجديد يتطبق • الآي سكور • نفس معايير التاريخ الائتماني العادية، داخليًا وخارجيًا. • مضاعف الائتمان • (متوسط الدخل ÷ 2 ) − التزامات الآي سكور × 8 • ×8 عنده سجل آي سكور أكتر من 6 شهور • ×4 مالوش آي سكور، أو سجله أقل من 6 شهور • مثال للتوضيح متوسط دخله 14,000 ← النص 7,000 ← ناقص التزامات 2,000 = 5,000 ← × 8 = 40,000 جنيه • الحد الأقصى لعبء الدين (DBR) هو 50% من الدخل في كل الحالات.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":103,"sec":"protocols","h":"البرنامج التاني","t":"البرنامج التاني","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":104,"sec":"protocols","h":"عملاء الكارت الطبي (شركات التأمين)","t":"عملاء الكارت الطبي (شركات التأمين) • العميل مش مؤمن عليه اجتماعيًا، بس شغله عامله كارت طبي من شركة تأمين • السن • 25 سنة لحد 60 سنة • مدة التقسيط • 10 شهور لحد 36 شهر • الورق المطلوب • بطاقة هوية سارية • كارت طبي صادر من 6 شهور على الأقل • فيديو من تطبيق شركة التأمين على الموبايل يظهر فيه بيانات العميل • حساب الدخل • على أساس برنامج الدخل الافتراضي . • مدة الخدمة • شغال من 6 شهور على الأقل. • لو الكارت الطبي أحدث من 6 شهور، العميل لازم يجيب مستند زيادة يثبت مدة خدمته. • الآي سكور • سجل نضيف داخليًا وخارجيًا. • مضاعف الائتمان • ×8 شركات الفئة (أ) • ×4 شركات الفئة (ب) • الحد الأقصى لعبء الدين (DBR) هو 50% في الفئتين.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":105,"sec":"protocols","h":"عملاء الكارت الطبي (شركات التأمين)","t":"شركة التأمين في أنهي فئة؟ اكتب اسمها من على الكارت • خلي بالك من الأسماء اللي شبه بعض: «الدلتا للتأمين» فئة (أ) لكن «الدلتا لتأمينات الحياة» فئة (ب). ونفس الكلام في «قناة السويس». و«مصر للتأمين» و«مصر لتأمينات الحياة» (أ) لكن «مصر للتأمين التكافلي» (ب).","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":106,"sec":"protocols","h":"الفئة (أ) ×8","t":"الفئة (أ) ×8 • ميتلايف مصر MetLife Egypt • أروب للتأمين Arope Insurance • المهندس للتأمين Mohandes Insurance • الدلتا للتأمين Delta Insurance • قناة السويس للتأمين Suez Canal Insurance • رويال للتأمين Royal Insurance • أكسا مصر AXA Egypt • المصرية للتأمين التكافلي Egyptian Takaful Insurance • بوبا مصر Bupa Egypt • مصر للتأمين Misr Insurance • أليانز مصر Allianz Egypt • جي آي جي مصر GIG Egypt • أورينت للتأمين التكافلي (نكست كير) Orient Takaful Insurance (Next Care) • مصر لتأمينات الحياة Misr Life Insurance","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":107,"sec":"protocols","h":"الفئة (ب) ×4","t":"الفئة (ب) ×4 • جلوب ميد مصر Globe Med Egypt • إسكان للتأمين Iskan Insurance • طوكيو مارين مصر Tokio Marine Egypt • الدلتا لتأمينات الحياة Delta Life Assurance • قناة السويس لتأمينات الحياة Suez Canal Life Insurance • إيه آي جي مصر AIG Egypt • ثروة للتأمين Sarwa Insurance • تشب للتأمين Chubb Insurance • المصرية السعودية للتأمين Egyptian Saudi Insurance House • صندوق معاشات المقاولون العرب Arab Contractors Pension Fund • مصر للتأمين التكافلي Misr Takaful Insurance • إيجي كير Egy Care • الشركة دي مش في القايمة. ارجع لمديرك أو لقسم الائتمان قبل ما توعد العميل بحاجة.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":108,"sec":"protocols","h":"مقارنة سريعة","t":"مقارنة سريعة • الخانات الملونة هي اللي بيحصل فيها لخبطة. • البند • السواقين • الكارت الطبي • السن • 30 – 60 • 25 – 60 • مدة التقسيط • 10 – 36 شهر • 10 – 36 شهر • إثبات الدخل • كشف التطبيق + فيديو، أو كشف بنكي • كارت طبي + فيديو من تطبيق التأمين • حساب الدخل • متوسط صافي آخر 6 شهور • برنامج الدخل الافتراضي • مدة الشغل • 6 شهور على التطبيق • 6 شهور خدمة • زيارة منزلية • إلزامية • مش مذكورة • الآي سكور • المعايير العادية • سجل نضيف • المضاعف • ×8 بآي سكور، ×4 من غيره • ×8 فئة (أ)، ×4 فئة (ب) • عبء الدين • 50% بحد أقصى • 50% بحد أقصى","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":109,"sec":"protocols","h":"موقف من الفرع","t":"موقف من الفرع • العميل عاوز التلاجة دي قسط، بس أنا مش متأمن عليا. • أنت ولا يهمك، عندنا برامج لده. حضرتك بتشتغل إيه؟ • العميل سواق على أوبر بعربيتي. • أنت تمام. العربية والرخصة باسم حضرتك؟ وشغال على التطبيق بقالك قد إيه؟ • العميل باسمي، وبقالي سنة تقريبًا. • أنت ممتاز. هنحتاج بطاقتك، ورخصة العربية، وكشف أرباح آخر 6 شهور من التطبيق مع فيديو يبين بياناتك. ولو تحب، كشف حساب البنك بتاع آخر 6 شهور ينفع بدل كشف التطبيق.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":110,"sec":"protocols","h":"قول","t":"قول • «حضرتك بتشتغل إيه؟» • «العربية والرخصة باسمك؟» • «الكارت الطبي ده طالع من إمتى؟» • «ده الورق اللي هنحتاجه، عشان الملف يعدي من أول مرة»","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":111,"sec":"protocols","h":"ما تقولش","t":"ما تقولش • «مفيش تقسيط من غير تأمينات» • «هات أي ورق وإحنا نشوف» • «مضمونة، هتتقبل أكيد» • «اتعملك رفض عشان كذا» (سبب الرفض ما بيتقالش)","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":112,"sec":"protocols","h":"نقاط لازم تاخد بالك منها","t":"نقاط لازم تاخد بالك منها • السواق لازم يكون هو مالك العربية. لو العربية باسم حد تاني، ما ينفعش على البرنامج ده. • موديل العربية أقدم من 10 سنين؟ ما ينفعش. • الرخصة لازم تغطي مدة التقسيط كلها ، مش بس 6 شهور. • الكارت الطبي أحدث من 6 شهور؟ اطلب مستند يثبت مدة الخدمة قبل ما تبدأ. • دايمًا اتأكد من فئة شركة التأمين من القايمة، لأنها بتفرق في المضاعف. • ما تديش العميل وعد بالقبول، وما تقولوش سبب الرفض لو حصل.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":113,"sec":"protocols","h":"اختبر نفسك قبل الامتحان","t":"اختبر نفسك قبل الامتحان • فكر في الإجابة، وبعدين دوس على السؤال تشوفها. • 1 سواق على إن درايفر عنده 28 سنة. ينفع على برنامج السواقين؟ الإجابة 2 عميل معاه كارت طبي من «بوبا مصر». المضاعف كام؟ الإجابة 3 سواق أوبر ما عندوش كشف أرباح من التطبيق. فيه بديل؟ الإجابة 4 الكارت الطبي طالع من 4 شهور بس. نعمل إيه؟ الإجابة 5 سواق ديدي ما عندوش أي سجل آي سكور. المضاعف كام؟ الإجابة 6 عربية السواق موديل 2014. ينفع؟ الإجابة • لأ، السن في برنامج السواقين من 30 لـ 60 سنة. • ×8، لأن بوبا مصر فئة (أ). • أيوه، كشف حساب بنكي آخر 6 شهور فيه تحويلات الدخل، ويعتمده الـFRMU. • نطلب من العميل مستند إضافي يثبت إن مدة خدمته 6 شهور على الأقل.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":114,"sec":"protocols","h":"اختبر نفسك قبل الامتحان","t":"×4، وعبء الدين ما يزيدش عن 50%. • لأ، موديل العربية لازم ما يزيدش عن 10 سنين.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":115,"sec":"protocols","h":"الخلاصة","t":"الخلاصة • اسأل العميل بيشتغل إيه قبل ما تقوله لأ. السواق ليه برنامج، وصاحب الكارت الطبي ليه برنامج، والورق الصح من أول مرة بيقفل البيعة. • ذاكر الكبسولة كويس، وبعدها امتحان الكبسولة.","tabs":["main-protocol-installment","sub-protocol-inst_5"]},{"id":116,"sec":"sales-procedures","h":"إجراءات البيع","t":"بروتوكول إتمام البيع • بروتوكول التوصيل للمنزل • بروتوكول طلبات الكول سنتر • بروتوكول الشحن • بروتوكول طلبات الخصم الاستثنائي • بروتوكول تسليم طلب من فرع تاني • بروتوكول استبدال الأجهزة الكبيرة • بروتوكول مرتجعات الأجهزة الصغيرة واسترداد الفلوس • بروتوكول الإرجاع والاسترداد للأجهزة الكبيرة • بروتوكول التقسيط بنظام \"تقسيطى\"","tabs":["main-protocol-sales-procedures"]},{"id":117,"sec":"sales-procedures","h":"بروتوكول إتمام البيع","t":"بروتوكول إتمام البيع • إزاي تقفل البيعة بأسلوب \"صاحب البيت\" • إنت كاستشاري بيع في راية، إتمام البيعة مش مجرد فاتورة بتطبعها، دي رحلة بتبدأ بابتسامة وبتنتهي بعميل ولاؤه ليك وللفرع. دي الخطوات الرسمية الثابتة عشان نقفل البيعة صح 100%: • 1- الاستقبال وكشف الاحتياج الترحيب • زي ما متعودين، استقبل ضيفك بابتسامة عشان تفتح الكلام. • ابدأ اطرح أسئلة بسيطة وذكية عشان تفهم احتياجاته الفعلية والسبب الأساسي للشراء. • 2- الاختيار والعرض البيع • زي ما بنعمل دايماً ساعد العميل يختار المنتج الأنسب ليه حسب احتياجاته • دورك كاستشاري: اقترح بدائل مناسبة، أو منتجات إضافية إكسسوارات/أجهزة تكميلية مع شرح مميزاتها بوضوح.","tabs":["main-protocol-sales-procedures","sub-protocol-sales_completion"]},{"id":118,"sec":"sales-procedures","h":"بروتوكول إتمام البيع","t":"3- المراجعة والتأكيد قبل السيستم • اتأكد إن العميل استقر على المنتج النهائي ومقتنع بيه 100%. • خطوة إلزامية: راجع مع العميل تفاصيل الطلب كاملة الموديل - الكمية - السعر النهائي قبل ما تفتح السيستم. • 4- شغل السيستم: إنشاء الطلب على الداينمكس • افتح نظام Dynamics وابدأ إدخال البيانات بالترتيب الآتي: • بيانات المنتج: • إدخال كود المنتج Item Code والكمية. ملاحظة: تقدر تضيف أكتر من منتج في نفس الطلب. • إدخال السيريال نمبر Serial Number: إلزامي للأجهزة اللي ليها سيريال زي الموبايلات. • إضافة تعليق Comment: خطوة اختيارية لو محتاج تسجل ملاحظة معينة. • بيانات العميل البروفايل: • ابحث أولاً باستخدام رقم الموبايل.","tabs":["main-protocol-sales-procedures","sub-protocol-sales_completion"]},{"id":119,"sec":"sales-procedures","h":"بروتوكول إتمام البيع","t":"لو العميل مسجل قبل كده ← البيانات هتظهر تلقائياً. • لو عميل جديد ← يتم إنشاء حساب جديد فوراً وتسجيل الاسم + العنوان + رقم الموبايل. • 5- مرحلة الدفع Tender • اختار مع العميل طريقة الدفع الأنسب ليه من الخيارات المتاحة: • • كاش • بطاقة ائتمان • بطاقة خصم مباشر • تقسيطي • شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan) • مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة جزء كاش + جزء تقسيط أو فيزا. • بمجرد إتمام الدفع، النظام بيصدر الفاتورة تلقائياً. • 6- التسليم وما بعد البيع الضمان والتقييم • اطبع الفاتورة وسلمها للعميل في إيده مع المنتج • اشكره بلباقة على اختياره لـ \"راية\".","tabs":["main-protocol-sales-procedures","sub-protocol-sales_completion"]},{"id":120,"sec":"sales-procedures","h":"بروتوكول إتمام البيع","t":"شرح الضمان خطوة هامة جداً: وضح للعميل الآتي بالتفصيل: • مين الجهة المسئولة عن الضمان راية ولا شركة تانية؟. • عناوين فروع الصيانة الخاصة بالمنتج. • تفعيل ضمان الـ QR Code نبه العميل على ضرورة مسح الـ QR Code لتفعيل الضمان لمنتجات البراندات دي: De'Longhi - Kenwood - Philips - Sary - Braun. • 7- التسليم وما بعد البيع الضمان والتقييم • رسالة التقييم: NPS/CSAT • بلغ العميل إنه هيستقبل رسالة نصية SMS لتقييم الخدمة، وأكد له إن رأيه مهم جداً بالنسبة لينا عشان نحسن مستوانا. • 8- التوديع ختام الرحلة • راجع سريعاً في سرك إنك عملت كل الخطوات بنجاح • ودع العميل بشكل لبق واحترافي زي ما انت بتعمل يا بطل كل مرة ، وقوله منتظرين زيارتك مرة تانية.","tabs":["main-protocol-sales-procedures","sub-protocol-sales_completion"]},{"id":121,"sec":"sales-procedures","h":"بروتوكول إتمام البيع","t":"💡 القاعدة الذهبية لصاحب البيت: • \"النظام في إدخال البيانات مش روتين، ده حماية ليك وللعميل.. والبيعة مبتنتهيش عند الدفع، بتنتهي لما العميل يفهم ضمانه ويخرج مبسوط!\"","tabs":["main-protocol-sales-procedures","sub-protocol-sales_completion"]},{"id":122,"sec":"sales-procedures","h":"بروتوكول التوصيل للمنزل","t":"بروتوكول التوصيل للمنزل • من الفرع لحد باب البيت • لما العميل يختار أجهزة محتاجة توصيل زي الشاشات TV، الأجهزة الكبيرة HA/MDA، أو حتى الأجهزة الصغيرة SDA دورك كـ \"صاحب بيت\" إنك تضمن وصول أجهزته بأمان وبدون أي خطأ في البيانات. دي الخطوات الرسمية: • 1- الاستقبال وتأكيد الاختيار • استقبل ضيفك بود وافهم احتياجاته بأسئلة بسيطة. • ساعده يختار الأنسب، واقترح عليه بدائل أو منتجات إضافية Up-selling • بعد الاستقرار النهائي، أكد معاه تفاصيل المنتج بوضوح الموديل - الكمية - السعر. • 2- شغل السيستم: إنشاء الطلب على الداينمكس • بيانات المنتج: • إدخال كود المنتج Item Code والكمية متاح إضافة أكثر من منتج.","tabs":["main-protocol-sales-procedures","sub-protocol-home_delivery"]},{"id":123,"sec":"sales-procedures","h":"بروتوكول التوصيل للمنزل","t":"إدخال السيريال نمبر Serial Number للأجهزة اللي ليها سيريال. • إضافة تعليق Comment لو في أي ملاحظة اختيارية. • بيانات العميل: • ابحث برقم الموبايل لو مسجل، بياناته هتظهر فوراً. • لو عميل جديد: اختار Add Customer ▶ Create New Customer وسجل: الاسم - العنوان - رقم الموبايل. • 3- ضبط البوصلة: تحديد الشحن والتوصيل • مراجعة دقيقة: راجع مع العميل عنوان التوصيل ورقم الموبايل حرفاً حرفاً لضمان دقة التسليم.","tabs":["main-protocol-sales-procedures","sub-protocol-home_delivery"]},{"id":124,"sec":"sales-procedures","h":"على السيستم:","t":"على السيستم: • اضغط على Order → Shipping Product → Change Origin. • ثم اختار \"المخزن الرئيسي\". • حدد \"تاريخ التوصيل\" المطلوب والمناسب للعميل. • المراجعة النهائية: أكد مع العميل للمرة الأخيرة الموديل، الكمية، السعر، عنوان وتاريخ التوصيل. • 4- مرحلة الدفع Tender • اختار مع العميل طريقة الدفع الأنسب ليه من الخيارات المتاحة: • • كاش • بطاقة ائتمان • بطاقة خصم مباشر • تقسيطي • شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan) • مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة جزء كاش + جزء تقسيط أو فيزا. • 5- إذن التسليم Delivery Note • بمجرد إتمام الدفع، السيستم بيصدر \"إذن التسليم\" تلقائياً.","tabs":["main-protocol-sales-procedures","sub-protocol-home_delivery"]},{"id":125,"sec":"sales-procedures","h":"على السيستم:","t":"محتويات الإذن: رقم العملية - Transaction Number - اسم الفرع - كود الموظف - اسم العميل ورقم موبايله - تاريخ التوصيل - رقم الإيصال - كود المنتج والسيريال إن وجد. • التسليم: اطبع الإذن وسلمه للعميل في إيده، وأكد عليه إن \"المندوب هيكلمه يوم التوصيل المحدد للتنسيق\". • 6- الضمان ورسالة التقييم CSAT-NPS • وضح مين المسئول عن الضمان راية ولا شركة تانية؟ وإديله عناوين فروع الصيانة. • تفعيل الـ QR Code: نبه العميل إنه لازم يمسح الكيو آر كود لتفعيل الضمان للبراندات دي: De'Longhi - Kenwood - Philips - Sary - Braun. • بلغ العميل إنه هيستقبل رسالة SMS لتقييم الخدمة وإن رأيه بيفرق معانا جداً. ودعه باحترافية.","tabs":["main-protocol-sales-procedures","sub-protocol-home_delivery"]},{"id":126,"sec":"sales-procedures","h":"على السيستم:","t":"ما وراء الكواليس: معلومات تهمك عشان تطمن العميل • عشان تكون عارف دورة حياة المنتج بعد ما بتعمل الأوردر: • الطلب يُرسل تلقائياً لنظام المخزن. • فريق المخزن بيجهز الطلبات من 7:00 صباحاً لـ 3:00 مساءً. • أمين المخزن بيسلم المنتجات لمندوب العمليات عشان تتحول لمركز الفرز Sorting Center. • الشحنات بتتغلف والفواتير بتطبع قبل الساعة 4:00 مساءً عشان تخرج للتوصيل تاني يوم. • مدة التوصيل الفعلية: من 3 لـ 5 أيام في القاهرة والجيزة، ومن 5 لـ 7 أيام في الإسكندرية والصعيد.","tabs":["main-protocol-sales-procedures","sub-protocol-home_delivery"]},{"id":127,"sec":"sales-procedures","h":"بروتوكول طلبات الكول سنتر","t":"بروتوكول طلبات الكول سنتر • الاستلام من الفرع • \"كمل بيعة زميلك للاستلام الفوري\" • لما العميل يطلب أوردر من خلال خدمة العملاء ويختار يستلمه من فرعك، ده معناه إن زميلك في الكول سنتر بدأ البيعة، ودورك كـ \"صاحب بيت\" إنك تكملها وتقفلها بسرعة واحترافية. دي الخطوات الرسمية من أول ما العميل يدخل الفرع: • 1. ما وراء الكواليس (إيه اللي حصل قبل ما العميل يجيلك؟) • عشان تكون فاهم الصورة كاملة موظف الكول سنتر عمل الآتي: • استقبل العميل، حدد طلبه، وتأكد من توافر المنتج في فرعك. • سجل بيانات العميل وتفاصيل الطلب على شاشة (Remedy – Inquiry Window). • حفظ الطلب، واللي اترحل تلقائياً كنظام بيع (Sales Order) على سيستم Dynamics.","tabs":["main-protocol-sales-procedures","sub-protocol-call_center"]},{"id":128,"sec":"sales-procedures","h":"بروتوكول طلبات الكول سنتر","t":"بلّغ العميل يتوجه لفرعك ومعه \"رقم الأوردر\". • 2. دورك كـ \"صاحب البيت\" (استقبال وتسليم) • بمجرد دخول العميل الفرع، دي الخطوات الإلزامية اللي هتعملها: • الاستقبال: رحب بضيفك بابتسامة، واطلب منه \"رقم الموبايل\" أو \"رقم الطلب\". • مراجعة الطلب على السيستم (Dynamics). • اضغط على Order ▶ Recall Order • ابحث برقم الموبايل أو رقم الطلب، وراجع كل التفاصيل مع العميل. • 3. مرحلة الدفع (Tender) • اختار مع العميل طريقة الدفع الأنسب ليه من الخيارات المتاحة: • • كاش • بطاقة ائتمان • بطاقة خصم مباشر • تقسيطي • شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan) • مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة (جزء كاش + جزء تقسيط أو فيزا).","tabs":["main-protocol-sales-procedures","sub-protocol-call_center"]},{"id":129,"sec":"sales-procedures","h":"بروتوكول طلبات الكول سنتر","t":"إذن التسليم (Delivery Note): بعد الدفع، السيستم بيصدر الإذن تلقائياً وفيه كل بيانات العملية: • رقم العملية Transaction Number. • اسم الفرع وكودك. • اسم العميل وموبايله. • تاريخ الاستلام. • رقم الإيصال. • كود المنتج والسيريال. • سعر المنتج. • 4. خطوة خصم المخزون الإلزامية (Pickup) • عشان تقفل العملية صح والقطعة تتخصم من عهدة الفرع: • ادخل مرة تانية على مسار: Recall Order • اختار زرار Pickup • راجع كود المنتج (Item Code) والكمية (Quantity) • اضغط على Pickup لإتمام العملية وخصم المخزون. • 5. إصدار الفاتورة والتسليم • الفاتورة هتصدر تلقائياً على السيستم: التاريخ - الوقت - رقم العملية - بياناتك - بيانات الفرع - بيانات العميل - وبيانات المنتج.","tabs":["main-protocol-sales-procedures","sub-protocol-call_center"]},{"id":130,"sec":"sales-procedures","h":"بروتوكول طلبات الكول سنتر","t":"التسليم: اطبع الفاتورة وسلم المنتج في إيد العميل مع الفاتورة. • 6- الضمان ورسالة التقييم CSAT-NPS • وضح مين المسئول عن الضمان راية ولا شركة تانية؟ وإديله عناوين فروع الصيانة. • تفعيل الـ QR Code: نبه العميل إنه لازم يمسح الكيو آر كود لتفعيل الضمان للبراندات دي: De'Longhi – Kenwood – Philips – Sary – Braun. • بلغ العميل إنه هيستقبل رسالة SMS لتقييم الخدمة وإن رأيه بيفرق معانا جداً. ودعه باحترافية.","tabs":["main-protocol-sales-procedures","sub-protocol-call_center"]},{"id":131,"sec":"sales-procedures","h":"بروتوكول الشحن","t":"بروتوكول الشحن • من فرعك أو فرع آخر • \"بيع من أي مكان، ووصّل لأي مكان\" • أحياناً العميل بيحتاج جهاز سواء أجهزة كبيرة HA/MDA، أو صغيرة SDA، أو شاشات TV ومحتاج يشحنه، سواء الجهاز متاح في فرعك أو هنسحبه من فرع تاني، كـ \"صاحب بيت\" دي الخطوات اللي بتضمن إن الأوردر يتسجل صح ويوصل للعميل في ميعاده: • 1. الاستقبال وتحديد الطلب • استقبل العميل بود، وافهم احتياجاته بأسئلة سريعة. • ساعده يختار الجهاز المناسب، واعرض عليه الإكسسوارات أو البدائل المتاحة لتعظيم البيعة. • التحقق من التوافر: شيك على السيستم إذا كان المنتج متاح في فرعك الحالي أو في فروع تانية، ووضح للعميل خيارات الشحن المتاحة.","tabs":["main-protocol-sales-procedures","sub-protocol-shipping"]},{"id":132,"sec":"sales-procedures","h":"بروتوكول الشحن","t":"أكد مع العميل تفاصيل اختياره النهائي: الموديل – الكمية – السعر. • 2. شغل السيستم Dynamics: توجيه الشحن • بمجرد التأكيد افتح السيستم وامشي على الخطوات دي بالترتيب: • بيانات المنتج: • إدخال كود المنتج Item Code والكمية. • إدخال السيريال نمبر Serial Number للأجهزة اللي ليها سيريال زي الموبايلات. • إضافة تعليق Comment لو في أي ملاحظة اختيارية. • بيانات العميل: • ابحث برقم الموبايل، لو العميل مسجل، بياناته هتظهر تلقائياً. • لو عميل جديد: اختار Add Customer ▶ Create New Customer وسجل: الاسم – العنوان – رقم الموبايل. • توجيه الأوردر خطوة الشحن الأساسية: • اضغط على مسار: Order → Shipping Product → Change Origin","tabs":["main-protocol-sales-procedures","sub-protocol-shipping"]},{"id":133,"sec":"sales-procedures","h":"بروتوكول الشحن","t":"اختار \"الفرع\" اللي هيتم الشحن منه سواء فرعك أو فرع تاني. • مراجعة وتأكيد الشحن: • راجع بيانات العميل، وبعدين اضغط على Store Shipping وحدد \"تاريخ الشحن\" المناسب. • 3. مرحلة الدفع Tender • اختار مع العميل طريقة الدفع الأنسب ليه من الخيارات المتاحة: • • كاش • بطاقة ائتمان • بطاقة خصم مباشر • تقسيطي • شركات التكنولوجيا المالية (أمان، Sohoola، ValU، Halan) • مرونة الدفع: متاح للعميل يدفع بطريقة مزدوجة جزء كاش + جزء تقسيط أو فيزا. • إذن التسليم Delivery Note: بعد الدفع، السيستم بيصدر الإذن تلقائياً ابدأ راجع محتوياته: رقم العملية - اسم الفرع/الفرع الآخر - كودك - اسم وموبايل العميل - تاريخ التسليم - رقم الإيصال - بيانات المنتج.","tabs":["main-protocol-sales-procedures","sub-protocol-shipping"]},{"id":134,"sec":"sales-procedures","h":"بروتوكول الشحن","t":"اطبع الإذن وسلم نسخة للعميل في إيده واشكره على ثقته في راية. • 4- الضمان ورسالة التقييم CSAT-NPS • عشان تقفل البيعة باحترافية، لازم توضح للعميل: • وضح مين المسئول عن الضمان راية ولا شركة تانية؟ وإديله عناوين فروع الصيانة. • تفعيل الـ QR Code: نبه العميل إنه لازم يمسح الكيو آر كود لتفعيل الضمان للبراندات دي: De'Longhi – Kenwood – Philips – Sary – Braun. • بلغ العميل إنه هيستقبل رسالة SMS لتقييم الخدمة وإن رأيه بيفرق معانا جداً. ودعه باحترافية. • ما وراء الكواليس: إزاي الشحنة بتتحرك للعميل؟ • المعلومات دي ليك عشان لو العميل سألك عن خط سير الأوردر ومواعيده: • بمجرد ما بتخلص، السيستم بيبعت طلب لـ Supply Chain كـ Pickup Request.","tabs":["main-protocol-sales-procedures","sub-protocol-shipping"]},{"id":135,"sec":"sales-procedures","h":"بروتوكول الشحن","t":"فريق الـ Fleet بيستلم الطلب ويحدد موعد يروح يستلمه من الفرع في اليوم التالي. • الشحنات بتطلع من الفرع وتتسلم لمركز الفرز Sorting Center في نفس اليوم. • مركز الفرز هو اللي بيوصلها للعميل. • مدة التوصيل الإجمالية: من 3–5 أيام للقاهرة والجيزة، ومن 5–7 أيام للإسكندرية والصعيد.","tabs":["main-protocol-sales-procedures","sub-protocol-shipping"]},{"id":136,"sec":"sales-procedures","h":"بروتوكول طلبات الخصم الاستثنائي","t":"بروتوكول طلبات الخصم الاستثنائي • إزاي تعمل خصم وتريّح العميل صح • أحياناً عشان تقفل بيعة كبيرة، العميل بيطلب خصم خاص، راية بتديلك الصلاحية دي كـ \"صاحب بيت\" من خلال خصم (Price Level A)، بس عشان الخطوة دي فيها موافقات، دي الطريقة الرسمية اللي تخلص بيها البيعة من غير ما تعطّل ضيفك: • 📌 المرحلة الأولى: مع العميل (وجهاً لوجه) • 1. الاستقبال والبيع • استقبل العميل بابتسامة افهم احتياجاته واعرض عليه المنتج الأنسب والبدائل المتاحة. • بعد ما العميل يستقر نهائياً ويطلب خصم أكد معاه كل تفاصيل المنتج (الموديل – الكمية – السعر) قبل أي خطوة. • 2. الموافقة السريعة (المكالمة)","tabs":["main-protocol-sales-procedures","sub-protocol-discount"]},{"id":137,"sec":"sales-procedures","h":"بروتوكول طلبات الخصم الاستثنائي","t":"تواصل فوراً عبر الهاتف مع فريق الـ Merchandising (Category Manager) لطلب الموافقة السريعة على تطبيق خصم (Price Level A). • 3. الفاتورة اليدوية والتسليم (عشان متأخرش العميل) • بمجرد الموافقة الصدفيّة أصدر \"فاتورة يدوية\" (Manual) للعميل، وسجل فيها: (اسم العميل - رقم الموبايل - العنوان - الكمية - كود المنتج - السعر). • اطبع الفاتورة اليدوية وسلمها للعميل في إيده مع المنتج. • 4. ختام رحلة العميل (الضمان وتقييم الخدمة NPS&CSAT) • وضح مين المسئول عن الضمان وإإيه هي عناوين فروع الصيانة. • تفعيل الـ QR Code: نبه عليه يمسح الكيو آر كود لتفعيل الضمان للبراندات دي: (De'Longhi – Kenwood – Philips – Sary – Braun).","tabs":["main-protocol-sales-procedures","sub-protocol-discount"]},{"id":138,"sec":"sales-procedures","h":"بروتوكول طلبات الخصم الاستثنائي","t":"بلّغه إنه هيستقبل رسالة (SMS) لتقييم الخدمة وإن رأيه مهم جداً لينا. • 💻 المرحلة الثانية: شغلك الإداري والسيستم (التقفيل صح) • بعد ما العميل يمشي وهو مبسوط، دورك تقفل الورقيات والسيستم عشان تحمي عهدتك: • 5. الإيميل الرسمي (خطوة إلزامية) • ابعت إيميل فوراً لفريق الـ Merchandising عشان تاخد تأكيد الخصم المكتوب. • الإيميل لازم يكون فيه: (كود المنتج – ماركة التليفون/المنتج – السعر الحالي). • فريق الـ Merchandising هيأكد الخصم ويحدث السعر على سيستم Dynamics. • 💡 ملحوظة ذكية: خصم الـ (Price Level A) صالح لمدة 24 ساعة فقط فلازم تقفل بيعتك في نفس اليوم. • 6. إنشاء الطلب على السيستم (Dynamics)","tabs":["main-protocol-sales-procedures","sub-protocol-discount"]},{"id":139,"sec":"sales-procedures","h":"بروتوكول طلبات الخصم الاستثنائي","t":"افتح السيستم وابدأ سجل البيعة: • بيانات المنتج: دخل كود المنتج (Item Code) والكمية (Quantity) ثم رقم السيريال (Serial Number) لو المنتج ليه سيريال زي الموبايلات وتقدر تضيف تعليق (Comment) لو حابب. • بيانات العميل: ابحث برقم الموبايل: • لو مسجل ➔ البيانات هتظهر. • لو جديد ➔ اضغط Create New Customer ▶ Add Customer وسجل (الاسم + العنوان + رقم الموبايل). • 7. تطبيق الخصم على السيستم (السر هنا) • عشان تُفعل الخصم اللي الإدارة وافقت عليه اضغط على مسار: Special ▶ Price Level A • 8. مرحلة الدفع (Tender) وإصدار الفاتورة: • اختار طريقة الدفع التي فضل حاسب بيها: كاش، Credit Card، Debit Card، أو تقسيطي.","tabs":["main-protocol-sales-procedures","sub-protocol-discount"]},{"id":140,"sec":"sales-procedures","h":"بروتوكول طلبات الخصم الاستثنائي","t":"بمجرد إتمام الخطوة دي السيستم هيصدر الفاتورة النهائية تلقائياً وكده البيعة اتقفلت صح 100% والعهدة اتظبطت.","tabs":["main-protocol-sales-procedures","sub-protocol-discount"]},{"id":141,"sec":"sales-procedures","h":"بروتوكول تسليم طلب من فرع تاني","t":"بروتوكول تسليم طلب من فرع تاني • ضيف زميلك.. هو ضيفك • لما العميل يشتري أوردر من فرع تاني ويختار يستلمه من فرعك، ده معناه إن زميلك قفل البيعة، ودورك كـ \"صاحب بيت\" إنك تكرم الضيف، تسلمه جهازه بسرعة، وتقفل العملية على السيستم عشان تظبط عهدتك المخزنية. دي الخطوات الرسمية: • 1. الاستقبال والبحث عن الطلب • استقبل ضيفك بابتسامة ولباقة زي ما إحنا متعودين.","tabs":["main-protocol-sales-procedures","sub-protocol-other_branch_delivery"]},{"id":142,"sec":"sales-procedures","h":"على السيستم Dynamics:","t":"على السيستم Dynamics: • اضغط على مسار: Recall Order • ابحث عن طلب العميل باستخدام \"رقم الموبايل\" \"أو\" \"رقم الإيصال\". • 2. تنفيذ الاستلام وخصم المخزون Pickup • عشان تسلم العميل وتخصم القطعة من عهدة فرعك بشكل سليم: • بعد ما تفتح الطلب، اختار زرار Pickup • راجع بدقة شديدة الكمية + كود المنتج Item Code • إدخال أرقام السيريال Serial Numbers لو المنتج بيحتاج سيريال. • اضغط مرة تانية على Pickup لإتمام العملية رسمياً وخصم الكمية من مخزونك. • 3. إصدار الفاتورة والتسليم الفعلي • بمجرد إتمام خطوة الـ Pickup، السيستم هيصدر الفاتورة تلقائياً. • الفاتورة هتكون شاملة: التاريخ والوقت – رقم العملية – كودك كموظف – اسم فرعك – اسم العميل – رقم الإيصال – بيانات المنتج زي الكود والسيريال والسعر.","tabs":["main-protocol-sales-procedures","sub-protocol-other_branch_delivery"]},{"id":143,"sec":"sales-procedures","h":"على السيستم Dynamics:","t":"اطبع الفاتورة فوراً وسلم المنتج في إيد العميل مع الفاتورة. • 4. ختام رحلة العميل الضمان وتقييم الخدمة NPS & CSAT • قبل ما تودع العميل، لازم تأكد على أساسيات خدمة ما بعد البيع: • وضحله مين الجهة المسئولة عن الضمان راية ولا شركة تانية؟ وإديله عناوين فروع الصيانة. • تفعيل الـ QR Code: نبه العميل على ضرورة مسح الكيو آر كود لتفعيل الضمان للبراندات دي: De'Longhi – Kenwood – Philips – Sary – Braun. • بلّغه إنه هيستقبل رسالة SMS لاستطلاع رأيه وتقييم الخدمة، وأكد إن رأيه مهم جداً لينا عشان نطور من نفسنا. • ودّع ضيفك بشكل لبق واحترافي عشان يخرج من الفرع وهو راضي 100%.","tabs":["main-protocol-sales-procedures","sub-protocol-other_branch_delivery"]},{"id":144,"sec":"sales-procedures","h":"بروتوكول استبدال الأجهزة الكبيرة","t":"بروتوكول استبدال الأجهزة الكبيرة • بدّل لضيفك لحد باب البيت • لما العميل يطلب استبدال جهاز كبير ثلاجة، غسالة، بوتاجاز.. ومش هينفع يجيبه الفرع ومحتاجنا نبدلهوله من البيت، العملية دي بتتم بخطوات دقيقة جداً عشان نحافظ على حق العميل وحق \"بيتنا\" وعهدتنا. هنقسمها لـ 3 مراحل: • 📌 المرحلة الأولى: الاستقبال والتأكد من الشروط معاك في الفرع • الترحيب والفهم: استقبل العميل بود وافهم منه سبب الاستبدال. • مراجعة شروط الاستبدال جهاز حماية المستهلك CPA: • خلال 14 يوم: الجهاز بحالته الأصلية وبكل مشتملاته. • خلال 30 يوم: لازم تقرير فني معتمد من مركز الصيانة. • تأكيد الشراء: اطلب الفاتورة، أو راجع بيانات الشراء على السيستم برقم الموبايل أو رقم الطلب.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":145,"sec":"sales-procedures","h":"بروتوكول استبدال الأجهزة الكبيرة","t":"القرار التقرير الفني هو الفيصل: • ❌ لو مفيش تقرير فني: وجه العميل بلباقة شديدة لمركز الصيانة المعتمد عشان يفحص المنتج ويجيب التقرير. • ✅ لو التقرير موجود: هنبدأ فوراً في الخطوات الإدارية. • 💻 المرحلة الثانية: الموافقات وإنشاء الأوردر على السيستم Dynamics • 1- طلب الموافقة: ابعت إيميل لفريق الـ Merchandising Category Manager مرفق فيه رقم الطلب + التقرير الفني، الرد بالموافقة بيتم خلال 24 ساعة.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":146,"sec":"sales-procedures","h":"2- إنشاء الطلب الجديد بعد الموافقة:","t":"2- إنشاء الطلب الجديد بعد الموافقة: • افتح السيستم واعمل Order جديد. • دخل كود الصنف والكمية + رقم السيريال. • 🖨️ خطوة إلزامية التعليق: لازم تكتب التعليق ده بالنص: Replacement order – to collect old item upon delivery طلب استبدال – سيتم استلام المنتج القديم عند التسليم","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":147,"sec":"sales-procedures","h":"3- توجيه الشحن للمخزن:","t":"3- توجيه الشحن للمخزن: • ابحث برقم موبايل العميل. • اضغط على Order → Shipping Product → Change Origin. • اختار \"المخزن الرئيسي\" وحدد تاريخ التسليم المناسب. • 4- إتمام الدفع Tender: اضغط على Tender واختار وسيلة الدفع لتسوية العملية المحاسبية. • 5- إبلاغ العميل: بلّغه بموعد التسليم، وأكد عليه إن المندوب \"هيستلمه الجهاز الجديد ويستلم منه الجهاز القديم في نفس الوقت\". • ما وراء الكواليس: المخازن والتوصيل • عشان لو العميل سألك: • المخزن بيجهز الشحنة ويبعتها لمركز الفرز قبل 4 عصراً. • مدة التوصيل: 3–5 أيام للقاهرة والجيزة، و5–7 أيام للإسكندرية والصعيد. • فريق التوصيل Fleet بيسلم الجديد ويستلم القديم، ويرجعه للمخزن عشان يتفحص.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":148,"sec":"sales-procedures","h":"3- توجيه الشحن للمخزن:","t":"المخزن بيبعتلك إيميل أول ما يستلم الجهاز المرتجع عشان تكمل أنت شغلك. • 🔐 المرحلة الثالثة: التقفيلة الإدارية للعهدة بعد إيميل المخزن • بمجرد ما المخزن يبلغك إنه استلم الجهاز القديم، لازم تقفل البيعة على السيستم عشان عهدتك:","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":149,"sec":"sales-procedures","h":"1. تنفيذ المرتجع:","t":"1. تنفيذ المرتجع: • ادخل على السيستم واضغط: Action ⬅️ Return Transaction . • ابحث برقم الإيصال واضغط Enter . • اضغط Return وحدد سبب الإرجاع.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":150,"sec":"sales-procedures","h":"2. إنشاء تحويل مخزني:","t":"2. إنشاء تحويل مخزني: • ابعت إيميل لـ مدير المنطقة Area Manager عشان يعمل تحويل للمنتج من الفرع للمخزن. • مدير المنطقة هيعمل التحويل ويبعتلك \"رقم التحويل\".","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":151,"sec":"sales-procedures","h":"3. إغلاق العملية:","t":"3. إغلاق العملية: • حدث حالة التحويل على السيستم إلى Shipped . • فريق المخزن هيستلم التحويل ويقفل عملية المرتجع بنجاح 100%.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_exchange"]},{"id":152,"sec":"sales-procedures","h":"بروتوكول الإرجاع والاسترداد للأجهزة الكبيرة","t":"بروتوكول الإرجاع والاسترداد للأجهزة الكبيرة • \"حق ضيفك محفوظ لحد باب بيته\" • لما العميل يطلب إرجاع جهاز كبير واسترداد قيمته، ومش هينفع يجيبه الفرع، دورك كـ \"صاحب بيت\" إنك تدير العملية دي باحترافية لأنها بتشمل أطراف كتير إدارة، مخازن، شحن، وحسابات. دي الخطوات الرسمية متقسمة حسب الوقت: • 1 المحطة الأولى: الاستقبال والفحص المبدئي العميل قدامك • الترحيب وفهم الموقف: استقبل ضيفك بلباقة، وافهم منه سبب الإرجاع بهدوء لامتصاص أي غضب.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_returns"]},{"id":153,"sec":"sales-procedures","h":"مراجعة الفاتورة والشروط CPA:","t":"مراجعة الفاتورة والشروط CPA: • اطلب الفاتورة، أو ابحث عن بيانات الشراء على السيستم بـ رقم الموبايل / رقم الطلب. • خلال 14 يوم: متاح الإرجاع لو الجهاز بحالته الأصلية ومشتملاته ومتفتحش. • خلال 30 يوم أو لو اتفتح 🔧: لازم تقرير فني معتمد من مركز الصيانة.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_returns"]},{"id":154,"sec":"sales-procedures","h":"القرار الحاسم:","t":"القرار الحاسم: • ❌ لو مفيش تقرير فني: وجّه العميل بلباقة لمركز الصيانة لفحص المنتج وإحضار التقرير قبل استكمال أي إجراء. • ✅ لو التقرير موجود: هنبدأ فوراً في الإجراءات الإدارية. • 2 المحطة الثانية: الموافقات وتحريك الشحن • 1. طلب الموافقة: ابعت إيميل فوراً لفريق Merchandising Category Manager مرفق فيه رقم الطلب + التقرير الفني. الفريق هيراجع ويبعتلك الموافقة على الإيميل. • 2. طلب الاستلام Supply Chain: بعد الموافقة، ادخل على سيستم الـ Supply Chain وأنشئ \"شحنة مرتجع\". • 3. إبلاغ العميل: بلّغ العميل بوضوح إن المنتج هيتم استلامه من بيته خلال 48 ساعة، وإن فريق التوصيل هيكلمه ينسق معاه الميعاد.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_returns"]},{"id":155,"sec":"sales-procedures","h":"القرار الحاسم:","t":"3 المحطة الثالثة: ما وراء الكواليس الاستلام والفحص المخزني • المرحلة دي بتتم بعيد عنك، بس لازم تكون عارفها • الطلب بيوصل لفريق الشحن Fleet، بيعملوا خطة السير الساعة 7 مساءً، والسائق بيكلم العميل يأكد العنوان والميعاد. • المندوب بيستلم الجهاز ويرجعه المخزن. • فريق المخزن بيفحص حالة الجهاز، وبعدها بيبعتلك إيميل عشان يبلغك تكمل إجراءاتك على السيستم. • 4 المحطة الرابعة: تقفيل السيستم والعهدة Dynamics • بمجرد ما تستلم إيميل المخزن، لازم تقفل العملية فوراً عشان تظبط عهدتك:","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_returns"]},{"id":156,"sec":"sales-procedures","h":"1. تنفيذ الإرجاع على السيستم:","t":"1. تنفيذ الإرجاع على السيستم: • اضغط: Action ثم اختار Return Transaction . • ابحث بـ \"رقم الإيصال\" واضغط Enter . • اضغط ⬅️ Return وحدد سبب الإرجاع.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_returns"]},{"id":157,"sec":"sales-procedures","h":"2. تحويل العهدة للمخزن خطوة إلزامية:","t":"2. تحويل العهدة للمخزن خطوة إلزامية: • ابعت إيميل لـ مدير المنطقة لإنشاء طلب تحويل من فرعك للمخزن الرئيسي. • مدير المنطقة هيعمل التحويل ويبعتلك \"رقم التحويل\". • ادخل على السيستم وحدث حالة التحويل إلى Shipped . • 5 المحطة الخامسة: تسوية الفلوس الاسترداد وختام الرحلة • بعد تقفيل السيستم، تواصل مع العميل لتبليغه بإتمام العملية، ونفذ الاسترداد حسب طريقة الدفع: • 💵 لو الدفع كان كاش: • اطلب من العميل زيارة الفرع لاستلام قيمة المرتجع نقداً. • 💳 لو الدفع كان فيزا أو بطاقة بنكية: • أنشئ طلب استرداد على سيستم Remedy وأرفق فيه: إيصال المرتجع + فاتورة البيع + رقم بطاقة الفيزا. • بلّغ العميل إن المبلغ هيترد على حسابه/بطاقته خلال 14 يوم عمل.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_returns"]},{"id":158,"sec":"sales-procedures","h":"2. تحويل العهدة للمخزن خطوة إلزامية:","t":"✨ الختام: اشكر العميل على ثقته في راية، وتأكد من رضاه التام عن مستوى الخدمة، وودعه باحترافية.","tabs":["main-protocol-sales-procedures","sub-protocol-large_appliance_returns"]},{"id":159,"sec":"sales-procedures","h":"بروتوكول التقسيط بنظام \"تقسيطى\"","t":"بروتوكول التقسيط بنظام \"تقسيطى\" • \"سهلها على ضيفك.. وقفل بيعتك صح\" • لما العميل يقرر يشتري قسط، دي فرصتك تقفل بيعة ممتازة. نظام \"تقسيطى\" معمول عشان ينجزك، بس محتاج تمشي على الخطوات دي بالمللي عشان تحمي العميل وتضمن الموافقة السريعة: • المرحلة الأولى: الاستقبال وكشف الحساب المبدئي • 1 الترحيب وفهم العميل: استقبل ضيفك، افهم احتياجاته واشرح له \"بروتوكول التقسيط\" ببساطة. • 2 شغل السيستم المبدئي: اطلب بطاقة الرقم القومي، ودخل بياناته على سيستم \"تقسيطى\" عشان السيستم يعمل فحص الـ I-Score ويحدد هو \"عميل جديد\" ولا \"عميل راية\".","tabs":["main-protocol-sales-procedures","sub-protocol-taqsiti_system"]},{"id":160,"sec":"sales-procedures","h":"3 قرار السيستم اللحظي:","t":"3 قرار السيستم اللحظي: • ❌ حالة الرفض المبدئي: السيستم بيحول الطلب تلقائياً لفريق الائتمان للمراجعة والتحقيق. دورك هنا انتهى مؤقتاً. • ✅ حالة الموافقة المبدئية: بنكمل الإجراءات فوراً حسب نوع العميل قديم ولا جديد. • المحطة الثانية: تفريغ العملاء عميل قديم ولا جديد؟ • أولاً: العميل القديم • اختار خطة التقسيط والمنتج، وأنشئ الطلب على سيستم تقسيطى. • العميل بيوقع على \"عقد الحد الائتماني\" لو دي أول مرة يوقع فيها. • إجراءات الـ KYC إلزامية: التقاط صورة حية Live Photo للعميل، وإدخال رمز الـ OTP اللي هيتبعتله. • ثانياً: العميل الجديد • السيستم هيحولك لإنشاء \"حد ائتماني جديد\": • 1. البيانات الأساسية: دخل الاسم بالكامل - الموبايل - الوظيفة ⬅️ ابعت رمز الـ OTP للعميل ودخله ⬅️ السيستم هيعمل فحص احتيال Fraud Check للتأكد من الأهلية.","tabs":["main-protocol-sales-procedures","sub-protocol-taqsiti_system"]},{"id":161,"sec":"sales-procedures","h":"3 قرار السيستم اللحظي:","t":"2. استكمال البروفايل بعد الفحص: دخل الحالة الاجتماعية - العنوان - بيانات الوظيفة - عضوية النادي - بيانات الضامن إن لزم الأمر. • 3. رفع الورق: ارفع المستندات المتاحة زي بطاقة التأمين الطبي / رخصة السيارة \"اختياري\". • 4. المراجعة: السيستم بيبعت للعميل SMS بتفاصيل طلبه عشان يقدر يتابعه. • 🧑‍💻 هنا بيتدخل فريق الائتمان يراجع الورق، يعمل زيارة ميدانية لو لزم الأمر وياخد قرار الموافقة ويحدد الحد الائتماني، وبعدها العميل بيستلم SMS بالموافقة والليميت بتاعه. • المحطة الثالثة: تعلية الليميت Limit Increase خطوة استثنائية • لو العميل الليميت بتاعه نزل بس محتاج يزوده عشان يشتري منتج أغلى:","tabs":["main-protocol-sales-procedures","sub-protocol-taqsiti_system"]},{"id":162,"sec":"sales-procedures","h":"3 قرار السيستم اللحظي:","t":"اضغط على رابط \"زيادة الحد الائتماني\" على السيستم. • ارفع مستندات إثبات الدخل زي: خطاب HR حديث - كشف حساب بنكي - بيانات الضامن. • الطلب بيتبعت فوراً لفريق الائتمان للمراجعة. • المحطة الرابعة: التفعيل وإتمام البيعة • بمجرد ما الليميت يعتمد للعميل الجديد أو بعد التعلية: • التفعيل: العميل بيوقع عقد الحد الائتماني لأول مرة فقط ⬅️ بتعمل إجراءات الـ KYC صورة حية + OTP ⬅️ العميل بيستلم SMS بتأكيد التفعيل. • البيع: ساعد العميل يختار المنتج اللي يناسب الليميت بتاعه وقيمة القسط، وقفل البيعة على السيستم. • المحطة الخامسة: التسليم وحفظ المستندات التقفيلة الصح • الاستلام من الفرع: العميل بيوقع على \"نموذج استلام المنتج\" وبياخده في إيده.","tabs":["main-protocol-sales-procedures","sub-protocol-taqsiti_system"]},{"id":163,"sec":"sales-procedures","h":"3 قرار السيستم اللحظي:","t":"التوصيل للمنزل: بيتم في خلال 3-5 أيام للقاهرة والجيزة، و 5-7 أيام للمحافظات. السائق بيستلم إذن التسليم لأرشيف المخزن ليتسجل على السيستم. • 📁 ما وراء الكواليس حفظ الورق • فريق الائتمان بيلف على الفروع مرتين شهرياً يجمع مستندات التقسيط الموقعة عشان يأرشفها. فحافظ على ورقك دايماً كامل ومترتب.","tabs":["main-protocol-sales-procedures","sub-protocol-taqsiti_system"]},{"id":164,"sec":"sales-procedures","h":"بروتوكول مرتجعات الأجهزة الصغيرة واسترداد الفلوس","t":"بروتوكول مرتجعات الأجهزة الصغيرة واسترداد الفلوس • \"حق ضيفك محفوظ.. وعهدتك في أمان\" • لما العميل يقرر يرجع منتج صغير، دي فرصتك كـ \"صاحب بيت\" تثبت له إننا بنحترم حق العميل زي ما بنحترم فلوسه. العملية دي محتاجة تركيز عالي عشان الفلوس والعهدة تتسوى صح. هنمشيها على 4 مراحل: • 1- الاستقبال والفحص العميل قدامك • الترحيب وتحديد الطلب: استقبل العميل بابتسامة، وافهم منه سبب الإرجاع بهدوء. تذكر: من حقه يرجع منتج واحد بس من الفاتورة، أو الفاتورة كلها. • مراجعة الفاتورة: اطلب فاتورة الشراء أو راجعها على السيستم برقم الموبايل أو رقم الطلب.","tabs":["main-protocol-sales-procedures","sub-protocol-small_appliance_returns"]},{"id":165,"sec":"sales-procedures","h":"الفحص القانوني قواعد حماية المستهلك CPA:","t":"الفحص القانوني قواعد حماية المستهلك CPA: • خلال 14 يوم: متاح الإرجاع بشرط المنتج يكون بحالته الأصلية. ماتفتحش، بكامل مشتملاته وتغليفه، ومراجعة السيريال إن وجد. • خلال 30 يوم أو لو العميل فتح الكرتونة 🔧: لازم يكون معاه تقرير فني معتمد من مركز الصيانة.","tabs":["main-protocol-sales-procedures","sub-protocol-small_appliance_returns"]},{"id":166,"sec":"sales-procedures","h":"القرار الحاسم التقرير الفني:","t":"القرار الحاسم التقرير الفني: • ❌ لو الجهاز مفتوح ومفيش تقرير: وجّه العميل بكل لباقة لمركز الصيانة المعتمد عشان يفحصوا المنتج ويطلعوله التقرير. • ✅ لو التقرير موجود أو الجهاز متفتحش: هنبدأ فوراً في خطوات الاسترداد. • 2- موافقة الإدارة خطوة إلزامية • تواصل فوراً مع فريق Merchandising Category Manager عن طريق الإيميل وممكن تكلمهم في التليفون للسرعة. • ابعت في الإيميل: رقم الطلب + التقرير الفني. • فريق الـ Merchandising بيراجع الطلب، وهيتبعتلك الموافقة على الإيميل خلال 24 ساعة كحد أقصى. • 3- السيستم وإيصال المرتجع Dynamics • بعد موافقة الإدارة، افتح السيستم ونفذ الآتي بالترتيب عشان تظبط عهدتك:","tabs":["main-protocol-sales-procedures","sub-protocol-small_appliance_returns"]},{"id":167,"sec":"sales-procedures","h":"1. تنفيذ الإرجاع:","t":"1. تنفيذ الإرجاع: • اضغط على: ⬅️ Action ثم اختار Return Transaction . • ابحث باستخدام \"رقم الإيصال\" واضغط Enter . • اضغط على ⬅️ Return ثم اختار \"سبب الإرجاع\". • 2. الحسبة التلقائية: السيستم هيعالج العملية ويحسب مبلغ الاسترداد تلقائياً بناءً على قيمة المنتج في الفاتورة. • 3. إيصال المرتجع: السيستم هيصدر إيصال مكتوب فيه: رقم العملية، التاريخ والوقت، اسم الفرع، اسم العميل، بيانات المنتج المرتجع، وقيمة المبلغ. • 4. مراجعة العميل: اطبع الإيصال، وخلّي العميل يراجعه ويأكد على بياناته بنفسه. • 4- تسليم الفلوس التسوية المالية • الخطوة دي بتختلف حسب طريقة دفع العميل الأصلية: • 🪙 لو العميل كان دافع كاش:","tabs":["main-protocol-sales-procedures","sub-protocol-small_appliance_returns"]},{"id":168,"sec":"sales-procedures","h":"1. تنفيذ الإرجاع:","t":"يتم رد قيمة المنتج نقداً للعميل فوراً في إيده. • 💳 لو العميل كان دافع فيزا أو بطاقة بنكية: • الفلوس مش بترجع كاش، لازم تعمل طلب على سيستم Remedy . • مرفقات الـ Remedy الإلزامية: صورة إيصال المرتجع + صورة فاتورة البيع + رقم بطاقة الفيزا. • إبلاغ العميل: لازم توضح للعميل بابتسامة إن المبلغ هيترد على حسابه/بطاقته البنكية خلال 14 يوم عمل . • ✨ ختام الرحلة ✨ • اشكر العميل جداً على وقته، واتأكد إنك قفلت العملية بنجاح. ودّعه بشكل لبق واحترافي يخليه يتأكد إن \"راية\" دايماً بيته المضمون.","tabs":["main-protocol-sales-procedures","sub-protocol-small_appliance_returns"]},{"id":169,"sec":"store-front","h":"واجهة بيتك","t":"لغة الكروت بطاقة تعارف المنتج • خريطة عرض المنتجات • الكروت البيعية أسلحتك السرية في الإقناع • قواعد العرض العامة","tabs":["main-protocol-store-front"]},{"id":170,"sec":"store-front","h":"لغة الكروت","t":"لغة الكروت • 🏷️ بطاقة تعارف المنتج • كارت السعر والمواصفات هو أول حاجة عين الضيف بتقع عليها. لو مقاسه غلط أو مكانه عشوائي، بيشوه المنتج ويضايق الضيف. دي الخريطة المظبوطة لمقاسات وأماكن الكروت: • ⌚ الإكسسوارات المقاس الأصغر: • المكان: على حامل أكريليك صغير تعلق فوق المنتج. • السر البيعي: الإكسسوارات حجمها صغير، لو حطيت كارت كبير هتخفي المنتج نفسه! دي منطقتك الذهبية للـ Cross-selling مع الموبايلات، فخليها دايماً واضحة. • 📱 الموبايلات، اللاب توب، والأجهزة الصغيرة SDA المقاس الصغير: • المكان الصح: مسطح نايم على الترابيزة جنب شاشة الموبايل أو لوحة مفاتيح اللاب توب. • السر البيعي: بيسمح للضيف يمسك الجهاز ويجربه براحته من غير ما الكارت يقع أو يضايقه.","tabs":["main-protocol-store-front","sub-protocol-card_language"]},{"id":171,"sec":"store-front","h":"لغة الكروت","t":"📺 الشاشات، الغسالات، البوتاجازات، والبلت إن المقاس المتوسط: • المكان الصح: يُثبت بوضوح في الزاوية العلوية اليسرى للمنتج أو الشاشة. • السر البيعي: ده مستوى نظر الضيف الطبيعي، بيخليه يقرأ المواصفات وهو باصص للجهاز بتركيز. • ملحوظة للغسالات: لو الغسالة على \"ستاند أرفف حائطي\"، الكارت يوضع في الزاوية العلوية اليسرى. لو على \"ستاند جزيرة\" في منتصف الفرع، الكارت يوضع أعلى المنتج في المنتصف. • ❄️ الثلاجات والفريزرات فقط المقاس الأكبر: • المكان الصح: يُثبت في الزاوية العلوية اليسرى للباب العلوي. • السر البيعي: التبريد مواصفاته وتفاصيله كتير (السعة، الانفرتر، البلازما...) فمحتاج أكبر كارت عشان الضيف يقرأ براحته.","tabs":["main-protocol-store-front","sub-protocol-card_language"]},{"id":172,"sec":"store-front","h":"لغة الكروت","t":"💡 نصيحة صاحب البيت: • لو عندك كارت \"خصم\" إضافي، دايماً حطه في الجهة المقابلة لكارت المواصفات عشان ما يغطيش عليه ويشوه الشكل.","tabs":["main-protocol-store-front","sub-protocol-card_language"]},{"id":173,"sec":"store-front","h":"خريطة عرض المنتجات","t":"خريطة عرض المنتجات • 🗺️ هندسة عين الضيف • الرص العشوائي بيشتت الضيف، لكن الرص الهندسي بياخد إيده ويقنعه يعلي ميزانيته Up-selling بكل سلاسة: • ⌚ الإكسسوارات منطقة الجاذبية: • دايماً ابدأ بـ \"الساعات الذكية\" في الواجهة، وبعدها السماعات ثم رص الشواحن، الكابلات، والباور بانك. • هندسة الألوان والأحجام: العلب الباكدج اللي لونها أسود أو أبيض خليها دايماً في \"أول أو آخر الصف\" كإطار بصري شيك، ورتب العلب حسب حجمها عشان الكبيرة ماتخبيش الصغيرة. • 💻 اللاب توب والـ IT • الأجهزة دي بتتجمع وتترتب إما حسب \"البراند\" أو حسب \"المواصفات\". • ليه؟ بيسهل على الضيف المقارنة بين جهازين في نفس الفئة، وبيسهل عليك إنت خطوة إقناعه بفئة أعلى.","tabs":["main-protocol-store-front","sub-protocol-product_map"]},{"id":174,"sec":"store-front","h":"خريطة عرض المنتجات","t":"📺 الشاشات والغسالات من الأصغر للأكبر: • ابدأ رص الأجهزة من الحجم الصغير وصولاً للحجم الكبير (مثلاً من 32 بوصة لـ 75 بوصة، أو من 7 كجم لـ 15 كجم). وأوعى تنسى اعرض فقط المقاسات المعتمدة و كمان تجمع نفس العائلة والمواصفات جنب بعض ، عشان تحافظ على تناسق العرض وماتعملش زحمة بصرية للضيف. • ليه؟ لأن عين الضيف هتبدأ مع الصغير، وتلقائياً هتتسحب للحجم الأكبر والمواصفات الأعلى اللي جنبه، ودا بيسهل عليك جداً تقنعه بالفئة الأعلى. • ❄️ الثلاجات من الأكبر للأصغر: • رتب حسب النوع (الأول 4 باب ⬅️ كومبي ⬅️ عادية). وجوه كل نوع رتب بالسعة اللترية من الأكبر للأصغر. • ليه؟ صدمة الانبهار الأولى! لما الضيف يشوف أعلى وأكبر فئة في الأول، بيحطها كمعيار Benchmark في دماغه وهو بيقارن باقي الأجهزة.","tabs":["main-protocol-store-front","sub-protocol-product_map"]},{"id":175,"sec":"store-front","h":"خريطة عرض المنتجات","t":"🍳 البوتاجازات حسب المقاس ثم السعر: • جمع كل مقاس لوحده (مثلاً كل الـ 90x60 مع بعض) ورتبهم تصاعدياً من السعر الأقل للأعلى.","tabs":["main-protocol-store-front","sub-protocol-product_map"]},{"id":176,"sec":"store-front","h":"الكروت البيعية","t":"الكروت البيعية • 🎯 أسلحتك السرية في الإقناع • كروت التسويق مش مجرد زينة ألوانها حلوة، دي \"طُعم\" بيسهل عليك إغلاق البيعة لو استخدمته بذكاء وفي مكانه الصح عشان ماتعملش زحمة بصرية للضيف: • 🔥 كارت الأكثر مبيعاً Best Seller & وصل حديثاً New Arrival • استخدامه: ده مفتاحك السحري مع \"الضيف المتردد\". شاور له على الكارت اللي مكانه أسفل يمين المنتج. • 💸 كارت \"عرض خاص\" السعر قبل وبعد • المكان الصح: يوضع دايماً في الزاوية العلوية اليمنى للمنتج. • السر البيعي: عين الضيف وهي بتقرأ كارت المواصفات بتسحب تلقائياً لفوق، فلما يشوف الخصم في الزاوية العلوية بيحس بقيمة البيعة والتوفير في أول نظرة. عشان كده أوعى تسيب السعر القديم في كارت آخر، لازم يبقى كارت واحد عليه السعر قبل وبعد.","tabs":["main-protocol-store-front","sub-protocol-sales_cards"]},{"id":177,"sec":"store-front","h":"الكروت البيعية","t":"💳 كروت التقسيط زيرو مقدم / بدون فوائد / خصم على الفائدة • المكان الصح: يوضع في الزاوية اليمنى السفلى أو في المنتصف حسب مساحة الجهاز وما يظهره العرض المرئي. • السر البيعي: بعد ما الضيف يقتنع بالجهاز ومواصفاته من فوق، عينه بتنزل تحت تدور على التسهيلات وطريقة الدفع، وهنا كارت الزيرو بيلقط عينه ويشجعه ياخد القرار فوراً. • 🎁 كارت \"هدية مجانية\" أو \"تصفية\" Clearance • استخدامه: اخلق حالة من الاستعجال! حسس الضيف إن الفرصة دي لو سابها وخرج من الفرع هتضيع عليه، خصوصاً لما يشوف بعينه كارت \"آخر قطعة\".","tabs":["main-protocol-store-front","sub-protocol-sales_cards"]},{"id":178,"sec":"store-front","h":"قواعد العرض العامة","t":"قواعد العرض العامة • عشان تكمل شياكة واجهة بيتك وتضمن إن تجربة الضيف تكون مريحة وآمنة 100%، في شوية تفاصيل صغيرة بتعمل فرق كبير في العرض المرئي للفرع: • 🏷️ التسعير الشامل قاعدة لا تقبل النقاش: • مفيش أي منتج في بيتك ينفع يتعرض من غير كارت سعر. المنتج المجهول بيقلل ثقة الضيف وبيخليه يكسل يسأل ويمشي! • 🎯 مستوى النظر هو مستوى الشراء: • خلي دايماً المنتجات \"الأكثر مبيعاً Best-selling\" أو اللي عليها تركيز في مستوى عين الضيف مباشرة. ده بيخطف عينه فوراً، بيوفر عليه المجهود، وبيسرع قرار الشراء. • 🛡️ الأمان قبل أي حاجة توزيع الأوزان: • المنتجات الثقيلة والكراتين الضخمة مكانها دايماً في الرفوف السفلية أو على الأرض. ده بيحافظ على توازن الاستاندات وبيضمن أمان الضيوف وسلامتك الشخصية.","tabs":["main-protocol-store-front","sub-protocol-display_rules"]},{"id":179,"sec":"store-front","h":"قواعد العرض العامة","t":"📏 طابور العرض المحاذاة والترتيب: • في أقسام الإكسسوارات أو الأجهزة الصغيرة، لازم ترتب العلب (الباكيدج) بحيث تكون حوافها كلها على خط واحد سواء في أول الرف أو آخره. التنسيق البصري الدقيق ده بيدي إحساس عالي بالنظام والاحترافية. • ❄️ التكييفات ليها وضع خاص: • في التكييفات بالذات، كارت الخصم دايماً بيتحط في الجهة المقابلة العكسية لكارت المواصفات. ده بيمنع زحمة الكروت على الوحدة الداخلية وبيخلي الضيف يشوف تصميم الجهاز واسم البراند بوضوح. • ✨ النظافة • واجهة بيتك لازم تفضل بتلمع! حافظ دايماً على الأجهزة مرتبة ونظيفة. والأهم إنك تتابع تحديث العرض وتغير الكروت باستمرار عشان تكون متماشية مع أحدث الحملات الإعلانية New Campaigns اللي الشركة بتنزلها.","tabs":["main-protocol-store-front","sub-protocol-display_rules"]},{"id":180,"sec":"house-guard","h":"حارس البيت","t":"بروتوكول حارس البيت","tabs":["main-protocol-house-guard"]},{"id":181,"sec":"house-guard","h":"بروتوكول حارس البيت","t":"بروتوكول حارس البيت • 🛡️ أمان فرعك ومكافحة الاحتيال • \"صاحب البيت\" مش بس بيعرف يبيع ويكبر فاتورته. ده كمان بيعرف يحمي بيته من أي تلاعب أو غش. وبيحمي نفسه من أي مسألة. ويحمي راية من أي مسألة. الخسارة دي من أي حاجة وبيضيف نفسه منها. وطبعاً أبسطها وأسهلها (تمويل الاستهلاكي) أو تسهيلات أنظمة التقسيط. دي تسهيلات أحياناً بيجذب بها الناس الغلط للانتهاز منهم. • التزوير: تلاعب في البيانات الجوهرية أو في أرقام القومية (إرسال منفقرات العمل أو النقل التأثير في الرقم القومي نفسه). • 2 🧾 قاعدة الـ (KYC) اعرف ضيفك • بكل ساطة: \"مافيشعميل مجهول\" قبل ما تبدأ إجراء مالي أو تقسيط، تأكد إنك 100% إن الشخص اللي واقف قدامك هو فعلاً صاحب البطاقة، وإن بياناته الأصلية صح.","tabs":["main-protocol-house-guard","sub-protocol-house_guard_protocol"]},{"id":182,"sec":"house-guard","h":"بروتوكول حارس البيت","t":"3 🔰 الوصايا الذهبية لحماية نفسك (ممنوعات لا تقبل النقاش) • التالي ده من صون حقوق دفاعك اللي تباعك للنجاة في جريمة نصب بدون قصد. • راجع الأصل بنفسك: إياك تقلل أو تضغط على \"المستند الأصلي\" مستنداً على أي إيرسال فوتو (فيرفيكيشن مرتان) من بره أو ممن بيدعي إنه تابعها. دي منعتها القانون كلياً. • إياك توقع على الضيف: مهما كانت بياناته تبدو سليمة أو تعليمات أتته تقسيطية قبل تسجيل الأصلي بمكان الصفقة اللقانونية المباشرة ولوحة الحق التزوير). • لا للتعديل بدون إذن: لو أي شخص طلب أي أي شيل أو تعديل أو التعديل في المستند الأصلي في مضمون المستند، فالعميل الأصلي له ملزم للعميل إلا لو عليه حكم قانوني ملزوم إلا لو تمت الإجراءات الجهة أحكام. بعد تمام الإجراءات الجهات لتسليم الجهاز.","tabs":["main-protocol-house-guard","sub-protocol-house_guard_protocol"]},{"id":183,"sec":"house-guard","h":"بروتوكول حارس البيت","t":"🚨 شكوك؟ ارفع سماعة التليفون فوراً لو أحسست إن العميل غريب ويدور أو مستنداته مريبة، تليفون فوراً لمديرك أو مستنداته شكلها ملغوب أو مستنداته شكلها ملعوب فيها هيوجهوك للصح. • ⚡ تواصل فوراً مع إدارة مكافحة الاحتيال - Fraud Team • تواصل فوراً مع إدارة مكافحة الاحتيال (Fraud Team) وفيهم بشكواك وأسبابها وأدلتها وتأكد من صحة السند.","tabs":["main-protocol-house-guard","sub-protocol-house_guard_protocol"]},{"id":184,"sec":"owner-dictionary","h":"قاموس صاحب البيت","t":"عشان تدير بيتك باحترافية وتكون دايماً سايق بخطوة، لازم تكون بتتكلم \"لغة الفرع\" صح. القاموس ده مش مجرد شوية حروف ومصطلحات، ده \"الكتالوج السري\" • الاختصار • المصطلح الإنجليزي • 💡 تعريفه • HA MDA • Home Appliances Medium Domestic Appliances • الأجهزة المنزلية الكبيرة: زي الثلاجات، الفريزرات، الغسالات وبوتاجازات. دي الأجهزة المعمرة اللي الضيف بياخد وقت عشان يقرر يشتريها. • SDA • Small Domestic Appliances • الأجهزة المنزلية الصغيرة: زي الميكروويف، والمكنسة و الخلاط والمكوى وأجهزة إعداد الطعام. خد بالك دي أجهزة سريعة وممتازة جداً لزيادة فاتورتك. • Personal Care • أجهزة العناية الشخصية: زي ماكينات الحلاقة، السيشوار، ومكواة الشعر. فئة ممتازة لتقديمها كبدائل أو هدايا.","tabs":[]},{"id":185,"sec":"owner-dictionary","h":"قاموس صاحب البيت","t":"Air Conditioners • أجهزة التكييف: الأجهزة الموسمية اللي محتاجة تركيز في الشرح على مساحة الغرفة وتقنيات توفير الكهرباء الإنفرتر. • FL / TL • Front Load / Top Load • أنواع الغسالات: FL تحميل أمامي، و TL تحميل علوي. مصطلحات سريعة بنستخدمها وإحنا بنشرح للضيف. • TV / LED • Televisions / Displays • الشاشات: بكل مقاساتها وأنواعها. • ACC • Accessories • الإكسسوارات: أي كماليات للموبايل أو اللاب توب زي الساعات الذكية، Smart Wearables، الشواحن والكابلات. • Dept / Cat • Department / Category • القسم والفئة: بيتك متقسم إدارياً لأقسام زي التبريد أو الشاشات، وكل قسم تحته فئات زي ديب فريزر أو شاشة ذكية. التقسيمة دي بتساعدك ترتب أفكارك وتعرض البدايل الصح.","tabs":[]},{"id":186,"sec":"owner-dictionary","h":"قاموس صاحب البيت","t":"Warehouse • المخزن: المكان اللي بتسحب منه أجهزة الضيف لو مش متاحة في فرعنا. عينك دايماً على رصيد المخزن في السيستم عشان تقفل البيعة بثقة وتوفر للضيف طلبه. • Visual Merchandising • العرض المرئي: فن شياكة واجهة بيتك! وهو طريقة رص الأجهزة وتنسيق الكروت عشان تفتح نفس الضيف وتريّح عينه وهو بيشتري. • POSM • Point of Sales Materials • المواد التسويقية البيعية: دي \"الأسلحة الصامتة\" بتاعتك! زي كروت الأسعار، كارت \"الأكثر مبيعاً\"، أو \"وصل حديثاً\" اللي بتعلقها على الجهاز. • USP • Unique Selling Proposition • الميزة التنافسية نقطة البيع الفريدة: دي \"الخلاصة\" أو السر اللي بيميز الجهاز عن غيره وبيخليه الأنسب لضيفنا زي تقنية تبريد معينة أو معالج شاشة قوي.","tabs":[]},{"id":187,"sec":"owner-dictionary","h":"قاموس صاحب البيت","t":"Attach Rate • Attach Rate • معدل المرفقات ارتباط المبيعات: ده المؤشر اللي بيقيس شطارتك في الـ Cross-selling! بعت كام إكسسوار مع كل جهاز رئيسي؟ كل ما تبيع مكملات أكتر، التقييم بتاعك بيعلى. • ASP • Average Selling Price • متوسط سعر البيع: بيقيس شطارتك في الـ Up-selling. كل ما تقنع الضيوف بموديلات أعلى وإمكانيات أحسن، متوسط قيمة الفاتورة الـ ASP بتاعك بيزيد. • Target • Daily Target • الهدف اليومي: ده التحدي الأساسي بتاعك كل يوم بتفتح فيه باب الفرع. كل ما تقفل التارجت بدري، كل ما تثبت إنك \"صاحب بيت\" ناجح. • Ach • Achievements • المحقق الفعلي: العداد اللي بيترجم مجهودك لمكسب حقيقي، وبيقولك إنت واقف فين بالظبط من التارجت بتاعك.","tabs":[]},{"id":188,"sec":"owner-dictionary","h":"قاموس صاحب البيت","t":"MTD • Month To Date • مبيعات الشهر حتى تاريخه: بيعرفك إنت محقق إيه من التارجت من أول الشهر لحد النهارده. عشان تعرف محتاج تشد حيلك إمتى. • YOY • Year Over Year • المقارنة السنوية: لما مديرك يقولك فرعنا محقق نمو YOY، معناه إن مبيعاتنا الشهر ده أعلى من نفس الشهر في السنة اللي فاتت. دي لغة البيزنس عشان تبقى فاهم فرعك بيكبر إزاي. • Inc • Incentive • العمولة الحافز المادي: مكافأتك المباشرة على شطارتك في المبيعات وتعبك مع الضيوف. كل ما تكبر فاتورة الضيف، عمولتك بتزيد. • Contest • Contest • المسابقات البيعية: تحديات بتنزلها الشركة على براندات أو فئات معينة. دي فرصتك الذهبية عشان تضاعف عمولتك وتثبت إنك بطل المبيعات في منطقتك!","tabs":[]},{"id":189,"sec":"delivery","h":"🚚 💊 بروتوكول التوصيل لراحة ضيفك 🏠","t":"🚚 💊 بروتوكول التوصيل لراحة ضيفك 🏠 • البيعة بتاعتنا مبتنتهيش عند الكاشير، البيعة بتكمل وتنجح لما ضيفك يستلم جهازه لحد باب بيته وهو مبتسم وبدون أي تأخير. عشان كده، فريق التوصيل بيبدأ خطوة جديدة لتسهيل الشحن، ودورك كـ \"صاحب بيت\" إنك تمهدله الطريق بالخطوات دي وأنت بتقفل الأوردر: • 💬 01 | رقم الواتساب هو مفتاح التوصيل • الجديد: العميل هيستقبل رسالة تأكيد وتنسيق على الـ \"واتساب\" الخاص بيه (خطوة احترافية زي شركات الشحن العالمية) عشان نسهل عليه عملية الاستلام. • دورك الإلزامي: لازم تتأكد وتراجع مع العميل إن رقم الموبايل اللي بتسجله على السيستم هو رقمه الأساسي وعليه حساب واتساب شغال.","tabs":[]},{"id":190,"sec":"delivery","h":"🚚 💊 بروتوكول التوصيل لراحة ضيفك 🏠","t":"📍 02 | العنوان.. تفاصيل التفاصيل (وبالعربي) • سجل عنوان التسليم باللغة العربية عشان يكون واضح ومتناسق لزميلك مندوب التوصيل. • الدور ورقم الشقة مش رفاهية! اكتب العنوان كامل (اسم الشارع، رقم العمارة، الدور، ورقم الشقة، وعلامة مميزة كمان). غياب تفصيلة زي \"الدور\" ممكن تعطل تسليم الأوردر وتعمل تجربة سيئة للعميل. • 📝 03 | التفاصيل مهمة مش للزينة • لو ضيفك طلب أي استثناء يخص التوصيل (زي تأجيل ميعاد التسليم ليوم معين، أو التسليم بعد موعد محدد)، لازم تكتب التعليق ده بوضوح على السيستم عشان فريق المخازن والتوصيل يكونوا في الصورة ويقدموا خدمة تليق باسم راية. • 🔍 04 | الشفافية التامة (العيوب الظاهرية)","tabs":[]},{"id":191,"sec":"delivery","h":"🚚 💊 بروتوكول التوصيل لراحة ضيفك 🏠","t":"لو الجهاز اللي بتبيعه فيه أي خدش أو عيب ظاهري (سواء كان جهاز عرض أو في المخزن وفيه ملحوظة معينة انت عارفها)، إلزاماً عليك تبلغ العميل بيه بوضوح وتأكد عليه قبل إتمام الدفع. • الشفافية من البداية بتمنع أي مشاكل أو مرتجعات وقت الاستلام، وبتحافظ على ثقة العميل. • 💡 القاعدة الذهبية","tabs":[]},{"id":192,"sec":"delivery","h":"\"الأوردر اللي مكتوب بياناته صح، بيوصل صح.. ريّح زميلك في التوصيل، عشان يريّح عمي","t":"\"الأوردر اللي مكتوب بياناته صح، بيوصل صح.. ريّح زميلك في التوصيل، عشان يريّح عميلك ويرجعلك يشتري تاني!\"","tabs":[]}]};
